window.__D("text/torat-chaim/c023",{"p":[[2300541032,"הצמצום בהשתלשלו' כו' שנ[ת]גלה למטה בגשמיות כמו למעלה מעלה ברוחניות העולם העליון בלי הפרש כלל, וכך יהי' בגילוי בחי' מל' דא\"ס שקודם הצמצום דקו\"ח במל' דאצי' שיהי' שוה למטה בעשי' בצומח וחי גשמיי' כמו למעלה ממש (וגם דעכשיו נק' קדו\"ש בשמים ובארץ בשוה ממש וכמ\"ש השמים והארץ אני מלא כו' זהו בבחי' ההעלם ולע\"ל יהי' בבחי' הגילוי ממש למטה כמו למעלה מטעם הנ\"ל). ומטעם זה סוס ורוכבו רמה בים שנתבטלו ממציאותם לגמרי לפי שאין גיאות דסוס ורוכבו דק\"נ מגיעי' לשם כלל ואין להם מקום כלל כי אין להם מקום במציאו' יש ודבר מה רק בבחי' ההשתלשלו' דצמצום בהעלם וגילוי כו' וע\"כ רמה בים ברוממות והשלכה מלמעלה למטה כא' כנ\"ל מפני שהי' למעלה מבחי' מעלה ומטה דעומ\"ר ועומ\"ת שוין ממש כנ\"ל וד\"ל (וזהו ג\"כ הטעם שאמר להם משה ואתם תחרישון וא' בזהר לא תתערו מידי אפי' במח' בהעלם וכ\"ש בדבור בתפלה וצעקה כו' כי אין בחי' העלא' מ\"ן דאותיות דמו\"ד בכוונה ורעותא דלבא<sup data-n=\"8719\">809</sup> מגיע שם כלל וגם תפלה דמשה איש האלקי' לא הגיע לשם כלל וכמ\"ש למשה מה תצעק אל\"י<sup data-n=\"8720\">810</sup> כו', לפי שצירופי אותיות דמ\"י<sup data-n=\"8721\">811</sup> באי' בבחי' ההשתלשלו' דהעלם לגילוי שהוא בבחי' מעלה ומטה עד רום המעלות ששייך שם ענין עלי' דתפלה וירידה והמשכה, אבל בפנימי' מהו\"ע ית' שנתגלה למטה כמו למעלה ממש להיותו למעלה מכל עיקר ומקור ההשתל' אין שם בחי' מעלה ומטה כלל מפני שנמצא למטה ולמעלה בשוה ממש ע\"כ לא יועיל העלא' מ\"ן דתפלה גם במס\"נ כצעקה דמשה, רק השתיקה בביטול [ה]מציאות לגמרי מכל וכל <span data-k=\"pg\">רנט</span> ּ וכמ\"ש ואתם תחרישון לגמרי לא תתערו מידי כי עצמו' אוא\"ס ממש אינו שורה רק בבחי' ביטול לגמרי כשתיקה כמ\"ש במ\"א וד\"ל).\n<b>(אך</b> א\"כ יש להבין האיך הי' קי\"ס הכנה למ\"ת אחר שאין בחי' צירופי אותיות דמו\"ד העלם וגילוי מגיע שם כלל ובמ\"ת הי' דוקא בחי' גילוי אוא\"ס באותיות התורה בא' אנכי כו' שזהו בחי' סוסים דקדושה כנ\"ל, הענין הוא דאדרבה משום שהי' בחי' ההעלא' וביטול המציאות דאותיות מו\"ד שנק' סוס כו' כמו ואתם תחרישון כנ\"ל מזה הי' ההכנה למ\"ת שיהי' בחי' ירידה והמשכה דמהו\"ע ית' שיהי' בחי' ההעלם דעצמו' ממש למטה כמו למעלה ממש, והיינו בהתלבשו' באותיות התו' דוקא שבהן מתלבש מפנימי' ועצמו' דאוא\"ס ממש להיות עי\"ז למטה כמו למעלה ממש (כמו שיהי' בעוה\"ב כנ\"ל), משא\"כ בצירופי אותיות דמו\"ד דתפלה וכה\"ג וד\"ל (וכנ\"ל בענין איזה בית אשר תבנו לי כו' דאע\"פ ששה\"ש לא כו' להיותו למעלה מעומ\"ר ועמ\"ת ([וגם] מבחי' חו\"ג שבעצמו' ממש כנ\"ל) מ\"מ צמצם שכינתו בין ב' בדי הארון שבו לוחות דתורה ששם נתפס מהו\"ע ממש כו' וכמו עכשיו בד\"א של הלכה שנק' מקומו ממש כנ\"ל), כמ\"ש במ\"א במ\"ש דוד אחת שאלתי<sup data-n=\"8722\">812</sup> כו' שבתי בבית ה' כו' וממילא יומשך",[["8719","809","<b>ורעותא דלבא</b>: ו: ליתא."],["8720","810","<b>מה תצעק אלי</b>: בשלח יד, טו."],["8721","811","<b>דמ\"י</b>: או: דמו\"ד."],["8722","812","<b>אחת שאלתי</b>: ראה גם לעיל פ' שמות מח, ד. וש\"נ."]]],[2300541036,"ממקור כל המקיפים שהוא לחזות בנועם ה' ולבקר בהיכלו כו' עד בצור ירוממני כו') (והיינו מה שבמ\"ת הנסתרות נעשו נגלות שהוא בחי' סתים דאורייתא שנק' נסתרות ונפלאות באו בגילוי בי' הדברות שזהו גם בחי' התוה\"ק שא' ואהי' אצלו אמון מופלא ומוצנע בא בבחי' גילוי ממש כנ\"ל בענין סוס כו').\n<b>ובזה</b> יתורץ הסתירה שיש בענין קי\"ס בין הזהר וכתבי האריז\"ל<sup data-n=\"8723\">813</sup>, שע\"פ דעת הזהר הי' בבחי' ההעלאה דאו\"ח מלמטה למעלה דוקא (שזהו כמו בקיעת המסך מבריא' לאצי' מלמטה למעלה) כמ\"ש במ\"א דכד סליק ימא גלגלוהי<sup data-n=\"8724\">814</sup> כו' שזהו שנעשה מבחי' גילוי העלם כו' כמ\"ש במ\"א (בש\"א<sup data-n=\"8725\">815</sup> ), ולפ\"ד האריז\"ל הי' בקי\"ס גילוי ירידה והמשכה דאו\"י מלמעלה למטה כו' (שזהו בקיע' המסך מאצי' לבריאה מלמעלמ\"ט דוקא) וע\"כ ראתה שפחה על הים<sup data-n=\"8726\">816</sup> מה שלא כו' [כמ\"ש זה אלי לנוכח] (כמשי\"ת). ובאמת אין כאן מחלוקת כלל דשניהם אמת שהי' בבחי' ההעלא' דאו\"ח בתשובה שלימה כנ\"ל עד שהיו בנ\"י בביטול המציאו' בשתיקה לגמרי כנ\"ל בפי' דעת הזהר, וגם זה אמת שהי' בחי' ירידה דאו\"י מלמעלה למטה דוקא שנעשה מהעלם עצמו גילוי כמ\"ש הפך ים ליבשה כו' כנ\"ל (שיותר נוטה כפ\"ד האריז\"ל) וכמ\"ש זה אלי כו' והוא מפני שהי' גילוי א\"ס למטה כמו למעלה ממש כנ\"ל וכמו שיהי' בעוה\"ב וע\"כ ראתה שפחה על הים כו' וכמו שיהי' לע\"ל שיראו כ\"ב ו[יהי'] פחד ה' על כל הברואי' למטה כמו למעלה ממש, וזהו מפני שהי' הכנה למ\"ת דוקא שיבא בגילוי למטה ולמעלה בשוה באותיות התורה כנ\"ל. וזהו אז ישיר משה ובנ\"י שזהו בחי' או\"י ואו\"ח יחד כנ\"ל הגם שהן ב' הפכים נתכללו יחד ולכך הי' קי\"ס הכנה למ\"ת דוקא לפי ב' הדיעות הנ\"ל משום דהא בהא תליא דוקא והיו לאחדים ממש מטעם הנ\"ל וד\"ל).\n<b>וגם</b> עכשיו יש בכל יום ענין הנ\"ל בקי\"ס ומ\"ת שזהו ענין התפלה והתורה, שהתפלה בבחי' או\"ח דרך<sup data-n=\"8727\">817</sup> לבך כו' (רק לא כקי\"ס שא' ואתם תחרישו\"ן אלא כמו נפ\"א בשתיקה לגמרי כמ\"ש במ\"א ע\"פ והאיש <span data-k=\"pg\">520</span> ּ משתאה מחריש<sup data-n=\"8728\">818</sup> כו'), ומצות ת\"ת בבחי' או\"י והא בהא תליא דוקא כידוע (וזהו שרמזו רז\"ל ע\"פ ביום ההוא יהי' מצילות הסוס קדש לה' כל מה שיהי' הסוס רץ ומיצל כו', דהנה מבואר במ\"א בענין ת\"א הרצים<sup data-n=\"8729\">819</sup> כו' וכמבואר למעלה שיש בכח של האותיות דסוסים להעלות לרוכב ולנשאו למקום רחוק לנצח לאויבו להשיג שלל רב ממנו ברדיפתו ומרוצתו בכח וגבו' הסוס דוקא כו', וכך הוא בבחי'",[["8723","813","<b>הזהר וכתבי האריז\"ל</b>: ראה זהר בשלח מח, ב. פע\"ח (שחה\"מ) שכ\"א, פ\"ח. לקמן קצו, ב. מאמרי אדה\"א ויקרא ח\"א ע' ריב ואילך. וש\"נ. שה\"א עא, ב ובהערה 10."],["8724","814","<b>דכד סליק ימא גלגלוהי</b>: זהר שם."],["8725","815","<b>בש\"א</b>: בשער האמונה פנ\"ד."],["8726","816","<b>ראתה שפחה על הים</b>: נסמן לעיל קמד, ב."],["8727","817","<b>דרך</b>: או: דרץ."],["8728","818","<b>והאיש משתאה מחריש</b>: ח\"ש כד, כא [בדילוג]. ראה ד\"ה זה בסידור שער נפ\"א ע' 182. שע\"ת מד, ב. תו\"ח ח\"ש קלז, ד ובהערה 1."],["8729","819","<b>ת\"א הרצים</b>: מל\"א יד, כח. ראה מאמרי אדה\"ז הקצרים ע' ריב. וש\"נ. וראה גם דר\"מ פד, רע\"ב. לקמן פ' משפטים רצד, ב."]]],[2300541039,"אותיות דתורה דוקא שנק' סוסים דקדושה שבכחם לרוץ למקומות הרחוקי' להרוג יניקת החיצוני' משרשם למעלה והוא לבער כל עמ\"ר<sup data-n=\"8730\">820</sup> בק\"נ גם הגנוז בהעלם ולהשיג העלא' רפ\"ח ניצוצי' שנפל שם כו' כענין מאור שבה<sup data-n=\"8731\">821</sup> כו' ונק' סם חיים<sup data-n=\"8732\">822</sup> כו'. ואמנם [הרי] יש גם בסוס ורוכבו דמו\"ד דק\"נ ג\"כ להשיג ולרדוף להשיג תוס' יניקה מן הקדושה כמו אמר אויב ארדוף אשיג כו' כידוע, ולזאת הי' קי\"ס שסוס ורוכבו רמה בים כו' והוא מפני שה' איש מלחמה כו' כמא' בים נדמה להם כבחור עושה מלחמה (כמשי\"ת) והוא בבחי' סוס דאותיות התורה כמ\"ש לסוסתי ברכבי פרעה דמיתיך רעייתי כו' וד\"ל. וזהו מה שיהי' בחי' הסוס דקדושה רץ ומיצל מן השונא שהן היכלות דק\"נ ע\"י אותיות התורה דבחכמה בדיבור דוקא אתברירו<sup data-n=\"8733\">823</sup> יהי' הכל קדש לה' שיהי' מזה תוס' אור בקד\"ש העליון דחכ' קדוש' כיתרון האור שבא מן החשך<sup data-n=\"8734\">824</sup> דוקא כמ\"ש במ\"א וד\"ל).\n<b>עזי</b> וזמרת יה ויהי לי לישועה, הנה הזכיר כאן ב' דברים עזי וזמרת י\"ה ומאמצעות שניהם הי' לי לישועה כו', להיות שתחלה א' אשירה לה' בבחי' שיר שהוא בפה כמ\"ש ויאמרו לאמר אשירה לה' כו' וכאן א' וזמר\"ת י\"ה הזמרה הוא בכלי כמ\"ש דוד גם אני אודך<sup data-n=\"8735\">825</sup> בכלי נבל אמתך אלקי אזמרה לך בכנור קדוש ישראל, וזהו יתרון מעלה בזמר בכלי שבו ועל ידו נמשך מבחי' המקיף העליון ביותר כמ\"ש אמת\"ך אלק\"י באמתת עצמותך אזמרה לך כו' וכשיר הלוים שהי' בכלי<sup data-n=\"8736\">826</sup> דוקא. וזהו שבשיר א' אשירה להוי' וכאן א' זמרת י\"ה שהוא בבחי' מקיף די\"ה דשם הוי' שהן בחי' המקיפים דחו\"ב ב' מזלות<sup data-n=\"8737\">827</sup> דונוצ\"ר ונק\"ה כו' שהן שרשי כל אורות דאצי' בבחי' ההעלם ומקיף דכת\"ר בכלל, כידוע בענין והחכ' מאין תמצא<sup data-n=\"8738\">828</sup> מאין ליש להיות נק' חכים באו\"כ כחכ' מוחא ונק' מבין כו' דהיינו ב' שמות דע\"ב ס\"ג<sup data-n=\"8739\">829</sup> כו', דמצד עצמות המאציל לאו מכא\"מ כלל ונק' חכים ולא בחכ' ידיעא כו'. וזהו ג\"כ בחי' הנסתרות דתורה שא' הנסתרות לה' אלקינו בחי' סתים דאורייתא שהוא בבחי' מקיף די\"ה כמו ח\"ע דתוה\"ק שנק' אמו\"ן מופלא ומוצנ\"ע כו' כנ\"ל שזהו בבחי' מקיף די\"ה דחו\"ב דתושב\"כ ושבע\"פ<sup data-n=\"8740\">830</sup> כידוע, וע\"ז א' וזמר\"ת י\"ה שיבאו בחי' הנסתרות מן ההעלם לגילוי כנ\"ל בפי' כי גא\"ה גא\"ה כו', שבקי\"ס הי' היפך ההעלם דסדכ\"ס עצמו להיות בבחי' גילוי כמו התלבשות ההעלם דנסתרות דתורה באותיות התורה הנגלות במ\"ת כנ\"ל שזהו שהי' קי\"ס דוקא הכנה למ\"ת כנ\"ל, וע\"כ א' וזמר\"ת י\"ה בזמ\"ר בכלי דוקא כמו בנבל וכנור ותוף כו' <span data-k=\"pg\">רס</span> ּ שעי\"ז יבא מן [ה]העלם [ו]מקיף לגילוי להיות",[["8730","820","<b>עמ\"ר</b>: ו: עומק רע."],["8731","821","<b>מאור שבה</b>: נסמן לעיל פ' שמות טז, ג."],["8732","822","<b>סם חיים</b>: ערובין נד, א."],["8733","823","<b>בחכמה. . אתברירו</b>: נסמן לעיל י, ג."],["8734","824","<b>כיתרון האור שבא מן החשך</b>: קהלת ב, יג. ראה מאמרי אדה\"א בראשית ע' קפ. וש\"נ."],["8735","825","<b>גם אני אודך</b>: תהלים עא, כב. ראה גם לעיל פ' בא קט, א."],["8736","826","<b>וכשיר הלוים שהי' בכלי</b>: ראה ערכין י, א (במשנה). סוכה נ, ב ואילך. רמב\"ם הל' כלי המקדש פ\"ג, ה\"ג. לעיל פ' בא קט, ג."],["8737","827","<b>המקיפים דחו\"ב ב' מזלות</b>: ראה הנסמן לעיל פ' שמות לו, א הערה 455."],["8738","828","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["8739","829","<b>מבין. . ס\"ג</b>: נסמן לעיל פ' וארא פד, ד."],["8740","830","<b>דחו\"ב דתושב\"כ ושבע\"פ</b>: נסמן לעיל פ' בא צד, ד."]]],[2300541042,"ל[י] לישוע\"ה בפו\"מ שכל ישועה בא' מכח ההעלם דמקיף שבא בהתלבשות למטה להיות למגן ומחסה נגד האויב והוא שא' עזי וזמרת י\"ה כמו ה' עוזי ומעוזי<sup data-n=\"8741\">831</sup> כו', והן ב' מקיפים דכת\"ר וחכ' בכלל שנק' נסתרות או נפלאות וכנ\"ל בענין סדכ\"ס שגם בחי' הסתימין שהן מקיף דחו\"ב נק' גילוי לגבי בחי' ההעלם דמקיף דכתר שנק' אדו\"ן הנפלאו\"ת ועוש\"ה פל\"א והוא שנק' עז\"י [ממש] ד\"ל (אבל במ\"ש אשירה להוי' להיות שזהו בחי' הגילוי אור בכלי בבחי' או\"פ שהוא בד' אותיות דשם הוי' כשבא בגילוי דו\"ה הנגלות לנו כו' כנ\"ל כמ\"ש ויספו ענוים בהוי' שמחה שהן מצות הוי', זהו ע\"י השיר בפה דוקא ולא בכלי כו').\n<b>ובאמת</b> יותר נכון לפרש בהיפוך דמ\"ש אשירה לה' בשיר בפה כו' זהו למעלה יותר מזמרת י\"ה כו', כי הנה מבואר למעלה במ\"ש אשירה להוי' זה הי' בחי' ההעלא' דאו\"ח להמשיך בחי' או\"י דתו\"מ בגשמיות במ\"ת שנק' מצות הוי' ותורת הוי' כו' הנגלות לנו לשמור ולעשות בפו\"מ שזהו יותר עליון בשרשם בעצמו' א\"ס ב\"ה ממש מן בחי' הנסתרות דתו\"מ הרוחניי' שבבחי' תוה\"ק<sup data-n=\"8742\">832</sup> שהיתה אצלו אמו\"ן כו', שזהו ההפרש בין משפ\"ט וצדק\"ה כו', וע\"כ א' באבות ושמי הוי' לא נודעתי להם רק באברהם א' אשר יצוה כו' ושמרו דרך הוי' לעשות כו' כנ\"ל באריכות משום דנתחב\"ס דוקא וסוף מעשה המצות בגשמיות עבמח\"ת כו', וא\"כ הי' צריך שיהי' בחי' ההעלאה להמשכה גבוה כזאת מבחי' הפנימי' ועצמיות יותר שזהו בחי' השירה בפה דוקא שהוא הנק' שיר פשוט<sup data-n=\"8743\">833</sup> שיוצא מנקודת פנימי' הבל הלב בלתי מורכב עדיין בדבר מה כלל גם לא ברצון ותענוג מורכב כו' והוא בבחי' כת\"ר שבכת\"ר שלמעלה גם מבחי' מקיף דכת\"ר בחו\"ב הנק' י\"ה שהן בחי' הנסתרות דתו\"מ כו'. וזהו אשיר\"ה להוי' דוקא להיות מתלבש בשם הוי' שבא בגילוי מהעלם די\"ה לשמור ולעשות בגשמיות בסומ\"ר וע\"ט כו' שנק' צדק\"ה כנ\"ל והוא לשם הוי' העצמי דתו\"מ שעבמח\"ת לנסתרות די\"ה דחו\"ב דתוה\"ק כו', והיינו כי גא\"ה גא\"ה כו' שנק' אדון הנפלאות שגם סדכ\"ס יבא מן ההעלם לגילוי (להיותו למעלה גם מבחי' מעלה ומטה דחו\"ג שבעצמות ממש כנ\"ל), ואח\"כ א' עזי וזמרת י\"ה שזהו בחי' המקיף דסדכ\"ס דכת\"ר להיות מקיף לחו\"ב שנק' זה<sup data-n=\"8744\">834</sup> שהן בחי' הנסתרות שיבאו לגילוי בבחי' שמירה ומגן ומחסה להיות לי לישועה נגד האויב כנ\"ל, שהוא בבחי' זמרת י\"ה בחי' שיר כפול דחו\"ב<sup data-n=\"8745\">835</sup> כו' וכידוע דשיר כפול זהו בבחי' מקיף דחו\"ב וכטעמי' [ו]נגינות דתורה וכה\"ג, וכמ\"ש במ\"א במ\"ש דוד זמירות היו לי חוקיך<sup data-n=\"8746\">836</sup> בבית מגורי להצילו מן האויב שהוא לעמוד לנגד המקטרג שז\"ש ויהי לי לישועה לי דוקא (כמשי\"ת) וד\"ל.",[["8741","831","<b>ה' עוזי ומעוזי</b>: ירמי' טז, יט."],["8742","832","<b>תוה\"ק</b>: ו: ח\"ע הקדומה."],["8743","833","<b>שיר פשוט</b>: ראה לעיל פ' בא קו, ד. וש\"נ."],["8744","834","<b>זה</b>: או: י\"ה."],["8745","835","<b>שיר כפול דחו\"ב</b>: ראה הערה 833."],["8746","836","<b>זמירות היו לי חוקיך</b>: תהלים קיט, נד. ראה מאמרי אדה\"ז תקס\"ו ע' שעא. כתובים ח\"ב ע' קפז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370149\" data-slug=\"torah-or\" data-id=\"3901370149\">תו\"א מקץ לב, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח שם ריט, ד</a>. רכו, ג ואילך."]]],[2300541045,"<b>והנה</b> יש עוד לפרש בפי' [ו]זמרת י\"ה שאינו ענין זמרה ושיר אלא הוא ענין כריתה וכיסוח כמו כרמך לא תזמור<sup data-n=\"8747\">837</sup> וכן זמיר עריצים<sup data-n=\"8748\">838</sup> (עיין פרש\"י שפי' כן דלא כת\"א שפי' וזמרתי ותושבחתי כו'), והיינו שב' אותיות הללו די\"ה (שזהו <span data-k=\"pg\">522</span> ּ כללות דתושב\"כ ושבע\"פ שהיו כלולים תחלה בבחי' ההעלם דחו\"ב שבעצמות המאציל שנק' חכים ולא כו' כנ\"ל) נזמרו ונחצבו ממקורם ובאו מבחי' ההעלם לגילוי להיות במהות בפ\"ע להיות נחקקי' במהות אותיות בצרופים שונים, כמו עד\"מ החוצב אבן אחת מן ההר הגדול שקודם החציבה לא הי' במהות אבן בפ\"ע <sup data-n=\"8749\">839</sup>כלל אלא כלול הי' ומתאחד עם ההר הגדול רק אחר שנכרת ונחצב מן ההר נעשה במהות אבן אחת גדולה ונק' אבן ומחלקי' אותו לחלקי' אבנים רבים לבנות מהם בנין בסדר הנחת האבנים זא\"ז כו'. וכך יובן בענין חו\"ב דתשב\"כ ושבע\"פ דכתיב אז רא\"ה ויספר\"ה הכינה כו' שנמשך ונחצב מן ההעלם דחו\"ב שבעצמו' א\"ס דלתבונתו אין מספר<sup data-n=\"8750\">840</sup> כלל למעלה מבחי' התחלקות אותיות, רק מבחי' יו\"ד דח\"ע העצמי' ממש נמשך פרטי ההתחלקות דצירופי אותיות דכ\"ד ספרי' דאוריי' וכן מה\"א דבינה שלמעלה נמשך פרטי התחלקו' דתושבע\"פ והן אותיות י\"ה שנק' נסתרות לה' כו', ובאו לגילוי להיות מהם בנין כל התו\"מ בצירופי' שונים שהן אורות בכלים רבים כידוע דהאותיות נק' אבנים<sup data-n=\"8751\">841</sup> (וכדוגמא שא' פסל לך<sup data-n=\"8752\">842</sup> שני לוחות אבנים כו' שהי' כתוב בהן י' הדברות שהן כללות כל התו\"מ והיו שני לוחות אבנים הללו מונחים בארון האלקי' ועי\"ז הי' גילוי עצמו' א\"ס על הכפ[ו]ר[ת] כו'). וכך היא למעלה במקור הראשון להשתלשלו' העולמות מבחי' ההעלם לגילוי מבחי' סדכ\"ס עצמו דלמת\"ב כלל אפי' בחי' מח' הקדומה שנק' חכמה שלמעלה וכמ\"ש אנת חכים ולא בחכ' ידיעא כלל וכן מבין ולא בבינה ידיעא [כלל] כו' וכדי שיהי' נק' חכים ומבין כו' צריך שיהי' ע\"י צמצום ובקיעה שיבקע האור מעצמו' חו\"ב שלמעלה שהן בבחי' א\"ס ממש להיות מקור למקור להשתלשלו', דהיינו שיאיר מן ההעלם לגילוי בכלל [ב]ב' אותיות די\"ה לבד כמו בחוצב אבן מן ההר הגדול כנ\"ל (וכמא' עבד מאנא רברבא<sup data-n=\"8753\">843</sup> וקרא בה גרמי' חכם כו', וכמשל בקיעת אור החכ' שנבקע מהעלם כח המשכיל ההיולי שכלול בעצמו' הנפש ממש הנק' נפש השכלי' בעצם כו' וכידוע דהוא המדע<sup data-n=\"8754\">844</sup> כו' וד\"ל). וזהו ענין בקיעת היו\"ד דשם ס\"ג<sup data-n=\"8755\">845</sup> שנבקע ויצא מבחי' טה\"ע כו' (כמ\"ש בעמק המלך) שהוא בחי' הרושם שנשאר אחר הצמצום שנמשך בהשתלשלו' דרל\"א שערים<sup data-n=\"8756\">846</sup> פנים ואחור כו'). ואפשר זהו פי' המא' בריש הורמנא<sup data-n=\"8757\">847</sup> כו' גליף גליפו בטה\"ע שאין הכוונה ענין גליפ' וחקיקת אותיות אלא ענין כריתה וחציבה שעי\"ז יוצאי' ובולטי' והיו כמו אבן בפ\"ע, כי חציבה זו הוא למעלה מחקיקת אותיות דתושב\"כ כנ\"ל,",[["8747","837","<b>כרמך לא תזמור</b>: בהר כה, ד [ושם: וכרמך]."],["8748","838","<b>זמיר עריצים</b>: ישעי' כה, ה."],["8749","839","<b>כלל</b>: ו: ליתא."],["8750","840","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["8751","841","<b>דהאותיות נק' אבנים</b>: ראה ס\"י פ\"ד, מי\"ב."],["8752","842","<b>פסל לך</b>: תשא לד, א."],["8753","843","<b>עבד מאנא רברבא</b>: ראה זהר (רע\"מ) בא מב, ב."],["8754","844","<b>דהוא המדע</b>: נסמן לעיל פ' בא קא, ד."],["8755","845","<b>בקיעת היו\"ד דשם ס\"ג</b>: נסמן לעיל פ' בא קנ, ד."],["8756","846","<b>דרל\"א שערים</b>: ראה ס\"י פ\"ב, מ\"ד. מ\"ה. מאמרי אדה\"א ויקרא ח\"ב ע' תתקטו."],["8757","847","<b>בריש הורמנא</b>: ראה זהר בראשית טו, א."]]],[2300541048,"אלא כמו לוחות האבן שנחקק בהן האותיות כנ\"ל שזהו שנק' גליפו כמו אתוון אתגליפו<sup data-n=\"8758\">848</sup> כשנעשי' מובדלי' במהות בפ\"ע כמו בליט' בדבר נבדל לחוץ כו', וזהו גליף גליפו ב' חציבות דיו\"ד וה\"א כנ\"ל שהן שרש התו\"מ בעצמו' א\"ס ממש כנ\"ל. וזהו אב\"ן א' ב\"ן<sup data-n=\"8759\">849</sup> דח\"ע ונק' אבן הראש\"ה<sup data-n=\"8760\">850</sup> שכוללת כל האותיות שמתחלקי' ממנה כו'), ואותיות י\"ה הללו הן שרשי כל האצי' שמהם נמשך מן ההעלם לגילוי כמ\"ש כי בי\"ה ה' צור עולמים<sup data-n=\"8761\">851</sup> שהן בכלל בחי' העלם וגילוי שזהו עלמין דאתכסיין ועלמין דאתגליין<sup data-n=\"8762\">852</sup> כידוע, וזהו וזמרת י\"ה שנכרתו ונחצבו אותיות י\"ה <span data-k=\"pg\">רסא</span> ּ מהעלם העצמות כנ\"ל וד\"ל (ומ\"ש אם בחוקתי תלכו שזהו ג\"כ ענין חקיקת אותיות<sup data-n=\"8763\">853</sup> שלמעלה מן בחי' אותיות הכתב וכן ענין זאת חוקת התורה<sup data-n=\"8764\">854</sup> כו' כמ\"ש במ\"א שמבחי' חקיקה זאת נמשך בחי' אותיות שבתורה שבכת\"ב כו', גם זה אמת, אבל גם בחי' חקיקה זאת היא כלולה באותיות די\"ה שנק' זמר\"ת י\"ה כנ\"ל שהן כמו<sup data-n=\"8765\">855</sup> עצם האבן שנחצב ונכרת מן ההר כמו לוחות האבן שנחצבו מן ההר וכתיב חרות על הלוחות<sup data-n=\"8766\">856</sup> שהי' בבחי' חקיק' אותיות דוקא כמ\"ש במ\"א), וכידוע דשרש נש\"י חקוקי' בעצמו' אור א\"ס ב\"ה בבחי' אותיות עצמיי' כחקיקת אותיות באבן די'<sup data-n=\"8767\">857</sup> במהות א' בלי פירוד כלל, וכך הן אותיות התורה שכללותם הן בחי' י\"ה דחו\"ב שלמעלה שנק' נסתרות לה' כו'.\n<b>וזהו</b> עזי וזמר\"ת י\"ה פי' עזי כפי ת\"א תקפי שהוא עצם התוקף והכח ועוז שממנו נמשך כל בחי' כח ועוז ותוקף בגילוי מן ההעלם להיות לבחי' מגן ומחסה עוז לנש\"י דוקא כמו ה' עוזי ומעוזי כו' ונק' אדו\"ן עוזינ\"ו צור<sup data-n=\"8768\">858</sup> כו' כמו בצור ירוממני<sup data-n=\"8769\">859</sup> כו', כי הנה התורה נק' עוז כמ\"ש ה' עוז לעמו יתן<sup data-n=\"8770\">860</sup> כו' ואין עוז אלא תורה<sup data-n=\"8771\">861</sup> כו' וכמ\"ש ה' מלך גיאות כו' לבש ה' עוז שהוא עוז דתוה\"ק<sup data-n=\"8772\">862</sup> כו', והענין הוא כידוע בזהר דג' קשרי' הן<sup data-n=\"8773\">863</sup> ישראל מתקשראן באוריי' ואוריי' בקוב\"ה והיינו ס\"ר נש\"י<sup data-n=\"8774\">864</sup> ששרשם בי\"ה בחי' פנימי' דאו\"א כו' שהוא ע[ו]לה במקור פנימי' דחו\"ב שלמעלה דתוה\"ק, כי כמו דאוריי' סתים וגליא כך ישראל סתי\"ם וגליא וקודב\"ה סתי\"ם וגליא, ונמצא בחי' סתים דאוריי' שנק' זמרת י\"ה הנ\"ל הוא בחי' ממוצע לקשר ולחבר לנש\"י כמו שהן בשרשם במח' הקדומה בבחי' סתים שנק' סדכ\"ס דלמחת\"ב כלל, וע\"כ גם בבחי' גליא הן ג' קשרי' כא' דנש\"י שבגופי' למטה מתקשראן באותיות התו' הנגלות לנו לשמור ולעשות ואורייתא בקוב\"ה שבא בגילוי ביחוד דהוי' ואלקי'",[["8758","848","<b>אתוון אתגליפו</b>: ראה זהר שם טו, ב."],["8759","849","<b>אב\"ן א' ב\"ן</b>: נסמן לעיל פ' בא קטו, ג."],["8760","850","<b>אבן הראש\"ה</b>: זכרי' ד, ז [ושם: האבן — ראה לעיל שם בהערה]."],["8761","851","<b>כי בי\"ה ה' צור עולמים</b>: ישעי' כו, ד."],["8762","852","<b>עלמין דאתכסיין. . דאתגליין</b>: נסמן לעיל פ' שמות לג, א."],["8763","853","<b>אם בחוקתי. . חקיקת אותיות</b>: ראה ד\"ה זה וביאורו במאמרי אדה\"ז תקס\"ד ע' קז ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">לקו\"ת בחוקותי מה, א</a> ואילך."],["8764","854","<b>זאת חוקת התורה</b>: ראה גם לעיל פ' שמות לב, ב. וש\"נ."],["8765","855","<b>כמו</b>: ו: ליתא."],["8766","856","<b>חרות על הלוחות</b>: תשא לב, טז. ראה בהערות שלפנ\"ז."],["8767","857","<b>די'</b>: או: שנאחדים."],["8768","858","<b>אדו\"ן עוזינ\"ו צור</b>: ברכת יוצר."],["8769","859","<b>בצור ירוממני</b>: תהלים כז, ה."],["8770","860","<b>ה' עוז לעמו יתן</b>: תהלים כט, יא."],["8771","861","<b>ואין עוז אלא תורה</b>: ראה ספרי ברכה לג, ב. מכילתא דרשב\"י יתרו פי\"ט, טז. מאמרי אדה\"א ויקרא ח\"א ע' שלח־ בראשית ע' קלח ובהנסמן בהנ\"ל."],["8772","862","<b>לבש ה' עוז. . דתוה\"ק</b>: ראה גם לקמן פ' תצוה שלא, ד. שע\"ת יב, ב. מאמרי אדה\"א שמות ח\"ב ע' תקלו."],["8773","863","<b>דג' קשרי' הן</b>: נסמן לעיל פ' שמות ב, ד."],["8774","864","<b>ס\"ר נש\"י</b>: ראה בא יב, לז. <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך. תק\"ע ע' קד. מאמרי אדה\"א במדבר ח\"א ע' כה ואילך. ויקרא ח\"א ע' שפח. וש\"נ. בראשית ע' רכא. וש\"נ."]]],[2300541051,"במצות מעשיות שנק' מצות הוי' ממש, וזהו הנסתרות לה' אלקינו שהן י\"ה דש' הוי' שהוא בחי' סתים דאוריי' שנק' נסתרו\"ת כנ\"ל בפנימי' דחו\"ב ש\"מ שנש\"י קשורים שם כמו שהן למעלה בעצמו' א\"ס שנק' סדכ\"ס כו' והנגלות כו' הן בחי' [ו\"ה] דתו\"מ דשם הוי' דוקא<sup data-n=\"8775\">865</sup> שבא בגילוי למטה באו\"כ שנק' צדק\"ה ומשפט כנ\"ל, ומבואר למעלה דבחי' ו\"ה הנגלות דתו\"מ יותר עליון בשרשו מתו\"מ הרוחניי' בשרשם בחו\"ב ש\"מ שנק' נסתרות משום דנתחב\"ס דוקא וסוף מעשה דוקא עבמ\"ת כו', ולפי\"ז הרי עיקר בחי' התלבשות המקיף העליון יותר דתורה הוא בירידתו למטה יותר והוא בתו\"מ הנגלות לנו כו' שזהו הטעם שנק' עוז כמ\"ש ה' עוז לעמו יתן לעמו דוקא שהוא העוז שלבש ה' בעוז דתורה כשלבש בגיאות דמל' דא\"ס להיות מל' [מ]כ\"ע כמ\"ש בי מלכים ימלוכו כנ\"ל וד\"ל.\n<b>וזהו</b> שא' ב' דברים עזי וזמרת י\"ה עזי הוא בחי' שם העצם דעוז שכל כח ועוז דכל המקיפי' העליונים מקבלים משם והוא שנק' עזי (בקמ\"ץ ולא בשורק כעוזי שאינו אלא פועל יוצא להיות לעוז למטה, ובזה יתורץ קושיא דרש\"י וד\"ל), והיינו עוז דתורה שלמטה דוקא ששרשה בעצם התוקף ועוז דבחי' גבו' דעצמו' המאציל שנק' שגיא כח<sup data-n=\"8776\">866</sup> או ורב כח כו' כת\"א תקפי בעצם התוקף כו' כקול דמ\"ת דכתי' <span data-k=\"pg\">524</span> ּ קול ה' בכח<sup data-n=\"8777\">867</sup> כו', והוא בחי' הגבו' והכח בעצם כמו שהוא בעצמות ופנימי' דא\"ס ב\"ה שהוא מיוחד לנש\"י דוקא ונק' עזי מטעם הנ\"ל דנש\"י מתקשרא' באוריי' הנגלית למטה שנק' עוז באמת כמ\"ש ה' עו\"ז לעמו יתן עו\"ז שלו ממש מטעם <sup data-n=\"8778\">868</sup>הנ\"ל וע\"כ א' עזי ממש וד\"ל. ואח\"כ א' וזמר\"ת י\"ה שהן בחי' הנסתרות לה' אלקינו שהוא בחי' סתים דאוריי' כמו שהיא בבחי' חו\"ב ש\"מ שנחצבו מעצמות חכמתו ית' שגם שהן<sup data-n=\"8779\">*869</sup> בחי' ממוצע לקשר ולחבר לנש\"י למעלה כנ\"ל, וז\"ש לבש ה' עוז (ונק' עו\"ז לאלקי'<sup data-n=\"8780\">869</sup> ליתן כח למטה להיות כח בשם אלקי' דבחי' ח\"ת לברר בירורי' דעה\"ד דח\"ע אתמשך בח\"ת כידוע במ\"ש חכמות בחוץ<sup data-n=\"8781\">870</sup> כו' (כמו חגר\"ה בעו\"ז מתנ\"י'<sup data-n=\"8782\">871</sup> כו'), וזהו שנק' זמר\"ת י\"ה שיורדים ג\"כ למטה בבחי' מקיף דוקא להיות דוחה ומגרש ולבער לחיצוני' בבחי' גבורות דשמאל דוחה כלשון זמי\"ר עריצי\"ם להכרית יניקת החיצוני' משרשם למעלה ולמטה (כידוע בענין הזמרה בנגינות וטעמים דאוריי' שהן בבחי' מקיף דח\"ע שמזה דוקא יגרשו ויכרתו יניקות החיצונים כמ\"ש זמירו\"ת היו לי חוקי\"ך כנ\"ל וד\"ל).",[["8775","865","<b>דוקא</b>: ו: ליתא."],["8776","866","<b>שגיא כח</b>: איוב לז, כג."],["8777","867","<b>קול ה' בכח</b>: תהלים כט, ד."],["8778","868","<b>הנ\"ל</b>: בתו\"ח באים כאן עוה\"פ התיבות: דנש\"י. . מטעם הנ\"ל."],["8779","*869","<b>שגם שהן</b>: א: שגם הן. בגו: שזהו."],["8780","869","<b>עו\"ז לאלקי'</b>: נסמן לעיל פ' שמות י, א הערה 443."],["8781","870","<b>דח\"ע. . חכמות בחוץ</b>: נסמן לעיל פ' שמות שם."],["8782","871","<b>חגר\"ה בעו\"ז מתנ\"י'</b>: משלי לא, יז."]]],[2300541054,"<b>וזהו</b> עזי וזמר\"ת י\"ה ע\"י ב' דברים הללו דוקא שהוא עזי וזמרת י\"ה שהן הנסתרות והנגלות שבתו\"מ הי' לי לישועה לי דוקא כו', דהנה א' ה' איש מלחמה כו' וארז\"ל שטענה מדה\"ד מה נשתנו אלו מאלו כי גם בנ\"י לא קיבלו התו\"מ עדיין ולמה אלו יטבעו ואלו יצולו, ונצחם במלחמה דשם הוי' שהוא מ\"ש הוי' איש מלחמה ה' שמו וע\"כ מרכבות פרעה וחילו כו' והוא לפי שישראל עתידי' ומוכנים לקבלת התו\"מ שנק' מצות הוי' שזהו הוי' שמו ממש כו'. דהנה ידוע שכל עיקר התו\"מ הוא לאכללא שמאלא בימינא<sup data-n=\"8783\">872</sup> כו' שזהו להגביר כח החסדי' על כח הדין והגבורות להמתיק הדין בחסד דוקא דאע\"פ שהתורה כלולה מחו\"ג בשוה כמ\"ש מימינו א\"ש ד\"ת כו', אבל בחי' הגבורות דאש דקו השמאל נמתקו בחסדי' דימין, וכמו כל מצות הקרבנות להעלות עולה וזבח הוא להמתיק כח הדין שמלובש ברע דנפש החוטאת לכפר עליו ע\"י זריקת דם והקטרת חלב להיות לריח ניחוח להוי' דוקא כו', וכן הקטרת להעלות להמתיק גם י\"א ארורים<sup data-n=\"8784\">873</sup> דק\"נ שיהופכו לטוב וחסד כו' ע\"י הי\"א סממני' דקטרת<sup data-n=\"8785\">874</sup> שעולי' בריח הבושם כו', וכה\"ג בכל מצות ל\"ת דגם שהן מבחי' ה\"ג הכל להעלות ולהפוך הגבו' קשות שמקבלי' מקו השמאל לחסדי' כמו במצות פרה אדומה כידוע וגם בדיני טו\"ט ואו\"ה שזהו הכל להעלות הטוב מן הרע שנפל [שם] כו', וצריך לזה בחי' גבורה ותוקף גדול ביותר שזהו לאגברא ימינא על שמאלא<sup data-n=\"8786\">875</sup> שיהי' כח הדין שבקו השמאל נכלל בקו הימין ואז ממילא יפול הרע גמור הנשאר שאין לו בירור כי אין לרע יניקה רק מן הטוב כידוע, וכך הוא ע\"י המשכת החסדי' דרמ\"ח מ\"ע להמשיך תוס' אור החסד בשם הוי' דמ\"ע בגילוי אלקות שיאיר גם בחושך דק\"נ כמו גם בדברים גשמיי' דדצ\"ח דק\"נ, המותרי' כו', וע\"כ נק' התורה עו\"ז <span data-k=\"pg\">רסב</span> ּ ותוש\"י'<sup data-n=\"8787\">876</sup> שע\"י תוקף הגבורות שבחסד העליון דקדושה מחליש ומתיש כח הסט\"א דק\"נ, וכמו בגוף הגשמי שמחליש כח הרע שביצה\"ר לאכפייא לסט\"א ע\"י בחי' עוז דתורה ומצות דוקא, וז\"ש כי גב\"ר עלינ\"ו חסדו כו' שזהו בחי' חסד וצדק\"ה דמצות שנק' צדק\"ה ומשפט כנ\"ל באריכות וד\"ל, ולפי שקי\"ס הי' רק הכנה למ\"ת כנ\"ל ע\"כ א' ה' איש מלחמה כו' שהי' איש מלחמה לנצח למדה\"ד שטען מה נשתנו אלו מאלו דגם שלא קיבלו התו\"מ עדיין בפו\"מ, אבל האמינו בה' ובמשה עבדו בכללות והאמונה היא כללות כל המצות דתרי\"ג שהעמידן על א'<sup data-n=\"8788\">877</sup> שז\"ש וצדיק באמונתו יחי'<sup data-n=\"8789\">878</sup> (ובפרט שהיו בנ\"י במצרים בסומ\"ר לצאת מאפילה דנש\"ט דמצרים כידוע ששרש הל\"ת הוא בי\"ה<sup data-n=\"8790\">879</sup> דשם הוי' שנק' זמר\"ת י\"ה שזהו עיקר המגרש ודוחה לחיצוני' כנ\"ל).",[["8783","872","<b>התו\"מ הוא לאכללא שמאלא בימינא</b>: נסמן לעיל פ' בא קיח, ד."],["8784","873","<b>הקטרת. . י\"א ארורים</b>: נסמן לעיל פ' שמות ח, ג."],["8785","874","<b>הי\"א סממני' דקטרת</b>: ראה תשא ל, לד. כריתות ו, א."],["8786","875","<b>לאגברא ימינא על שמאלא</b>: ראה זהר וישלח קסה, ב. מקץ קצח, ב. וארא לב, סע\"א. יתרו סז, א. אמור צב, ב."],["8787","876","<b>נק' התורה עו\"ז ותוש\"י'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. לקמן פ' יתרו רנא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380099\" data-slug=\"likkutei-torah\" data-id=\"4001380099\">לקו\"ת ויקרא ו, ב</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תקעח. שמות ח\"ב ע' תקלו. נ\"ך ע' רסח. דרושי חתונה ח\"ב ע' תפה. ובהנסמן בהנ\"ל."],["8788","877","<b>והאמונה. . שהעמידן על א'</b>: מכות כד, א. ראה שה\"א ד, א. יא, א. לקמן פ' תצוה שמה, א."],["8789","878","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["8790","879","<b>ששרש הל\"ת הוא בי\"ה</b>: נסמן לעיל פ' בא קיד, א הערה 152."]]],[2300541057,"<b>וזהו</b> ימינך ה' נאדר\"י בכח<sup data-n=\"8791\">880</sup> שזהו גבו' שבחסד שנק' נאדר\"[י] בכח והוא עצם הכח ועוז דתורה כנ\"ל, ומבחי' גבו' וכח זה שבימין דוקא א' ימינ\"ך ה' תרע\"ץ אוי\"ב<sup data-n=\"8792\">881</sup> שהוא עיקר הכח לרעוץ ולהפיל האויב משום דהא בהא תליא כנ\"ל שנק' עוז [ותוקף כו'] ותושי' כו') וזהו ה' איש מלחמה בכח ועוז גדול דהוי' דתורה כמו שהוא למעלה לעמוד לנגד המנגד שהן בחי' גבורות קשות דקו השמאל להפילם ולהמתיקם, ומה שכפל פ\"ב<sup data-n=\"8793\">882</sup> הוי' שמו הנה זהו שם הוי' דתו\"מ כמו שבאי' למטה דוקא בסומ\"ר וע\"ט בפו\"מ לאכללא שמאלא בימינא להגביר החסד על הדין כמ\"ש כי גב\"ר עלינו חסדו כנ\"ל, לפי שתו\"מ הנגלות לנו הן עיקר שם הוי' שנק' הוי' שמו ממש, וה' איש מלחמה זהו למעלה בחי' הנסתרות להוי' אלקינו כו' (כדוגמא שירד הוי' על ה\"ס לומר אנכי בגילוי ממש כו' שהן ה\"ח וה\"ג דמ\"ע ול\"ת שאז א' שירדה שנאה לאוה\"ע<sup data-n=\"8794\">883</sup> כו'). וזהו עז\"י וזמר\"ת י\"ה עזי [ב]בחי' עוז דתורה שלמטה שהוא עוז עצמי לישראל כנ\"ל שזהו תוקף תגבורת כח החסד עליון בתו\"מ שלנו כנ\"ל, וגם בחי' זמר\"ת י\"ה שזהו שרש התו\"מ שלמעלה שהוא כח הדין שבחסד להיות כורת יניקת החיצונים כל' זמיר עריצים כו' וכמ\"ש ימינך ה' תרע\"ץ אוי\"ב כנ\"ל) מאמצעות שניהם שהכל א' דהא בהא תליא הי' לי לישועה לי דוקא להצילם מכח מדה\"ד שטען מה נשתנו כו' וכמ\"ש ה' איש כו' מרכבות פרעה כו' כנ\"ל וד\"ל.\n<b>וזהו</b> ויהי לי לישועה, כי הנה ידוע דכל ענין ישועה הוא לעזור ולהציל מן האויב העומד לנגד שלא הי' ביכולת[ו] לעמוד לנגדו וע\"י המושיע הוא שמתגבר בכחו ונושע על ידו, כמו ויקם משה ויושיען<sup data-n=\"8795\">884</sup>, וכן [א'] ויושע ה' ביום ההוא את ישראל מיד מצרים<sup data-n=\"8796\">885</sup> כו', וע\"כ א' כאן ויהי לי לישועה לעז[ו]ר ולהציל, והוא מפני שהוא עזי וזמרת י\"ה כלו' לפי שנמשך בחי' תוקף הכח והעוז דכח<sup data-n=\"8797\">886</sup> החסד דימין העליון כמו ותושע לו ימינ\"ו<sup data-n=\"8798\">887</sup> כו' כמ\"ש ימינך ה' נאדרי בכח<sup data-n=\"8799\">888</sup> כו' שזהו כאשר השמאל נכלל בימין דוקא שאז ניתוסף כח הימין יותר והוא ע\"י עו\"ז דתו\"מ למטה ולמעלה כנ\"ל דוקא עי\"ז ויהי לי לישוע\"ה להצילם מכח הדין כנ\"ל וד\"ל (וזהו ויהי לי לישועה<sup data-n=\"8800\">889</sup> ממילא ולא א' הי' לי כו' משום דהא בהא תליא דכאשר גובר החסד דימין בכח השמאל שנכלל בו אזי כח הדין שבשמאל הוא להפיל ולרעוץ לאויב דוקא וכמ\"ש ימינך ה' תרעץ אוי\"ב, אע\"פ שהימין הוא <span data-k=\"pg\">526</span> ּ בחי'<sup data-n=\"8801\">890</sup> החסד היפך הדין הקשה אבל מצד בחי' הדין הכלול בחסד הוא שנעשה בחי' דין קשה למנגד כו' (כמ\"ש במ\"א בענין צדק\"ה",[["8791","880","<b>ימינך ה' נאדר\"י בכח</b>: בשלח טו, ו."],["8792","881","<b>ימינ\"ך ה' תרע\"ץ אוי\"ב</b>: בשלח שם."],["8793","882","<b>פ\"ב</b>: ו: פעם ב'."],["8794","883","<b>שירדה שנאה לאוה\"ע</b>: שבת פט, סע\"א."],["8795","884","<b>ויקם משה ויושיען</b>: שמות ב, יז."],["8796","885","<b>ויושע. . מיד מצרים</b>: בשלח יד, ל."],["8797","886","<b>דכח</b>: ו: דבחי'."],["8798","887","<b>ותושע לו ימינ\"ו</b>: איוב מ, יד [ושם: כי תושיע לך ימינך — ראה בהנסמן בסמוך]. ראה גם מאמרי אדה\"א בראשית ע' רפא. מאמר ד\"ה דור לדור מכ\"ק אדה\"א קה\"ת תשנ\"ב ע' 24."],["8799","888","<b>בכח</b>: ו: ליתא."],["8800","889","<b>לישועה</b>: ו: ליתא."],["8801","890","<b>בחי'</b>: ו: ליתא."]]],[2300541060,"ותהל\"ה שהוא ענין שם הוי' בניקו\"ד אלקי\"ם ביו\"כ<sup data-n=\"8802\">891</sup> כו'), כמו האב שמצד אהבה וחמלת בנו כשעומד בצרה מפני אויבו הרודפו יבא לכלל דין וכעס להפיל לאויב כו' (וזהו שפרש\"י עזי וזמרת י\"ה עוז\"ו ונקמת\"ו של אלקינו כו', שמפני בחי' הגבורות דעוז\"ו עושה נקמתו באויב להכריתו כו').\n<b>והנה</b> יש לפרש עוד בפי' עזי ענין גבורות וצמצומים דהיינו ע\"י בחי' גבורו' וצמצומים דוקא הוא שנחצב ונזמרו אותיות די\"ה הנ\"ל מבחי' ההעלם לגילוי, כידוע דכל אור ושפע הבאה בדילוג הערך מגבוה לנמוך ביותר צ\"ל ע\"י בחי' צמצומי' גדולים להסתיר ולהעלים אור העצמות, וזהו הנק' ג\"כ בשם גבורה והוא הנק' עז\"י עוז וגבורות דצמצומי' הללו, שזהו ג\"כ בחי' גבורה [ו]גדולה מה שיוכל לבא לבחי' צמצום גדול בעצמו בתחלה כדי שיוכל להיות גילוי אור די\"ה מן ההעלם דעצמות, כידוע דעצמות אוא\"ס הוא אור פשוט בתכלית ומובדל בערך מהיות גם מקור למקור למציאו' ע\"ס דאצי' וכמ\"ש אנת הוא חד<sup data-n=\"8803\">892</sup> ולא בחושבן חושבן<sup data-n=\"8804\">893</sup> י\"ס כו' וכן אמר אנת עילאה<sup data-n=\"8805\">894</sup> כו' למת\"ב כלל אפי' מח' דח\"ע הקדומה דתורה כו' וכדי שיקרא בשם חכים באות יו\"ד ומבין באות ה' שזהו שרש דתושב\"כ ושבע\"פ כנ\"ל הוצרך לבא בבחי' גבורות וצמצומי' תחלה. וזהו שנק' עזי, ע\"י בחי' עוז דגבורות וצמצומים הוא שבא לצמצום די\"ה שנק' זמרת י\"ה שיבאו מן ההעלם לגילוי, והוא מפני אהבה וחסד העצמי לישראל צמצם א\"ע בזה כמ\"ש ה' חפץ למען צדקו יגדיל תורה כו' כנ\"ל, ונק' גבו' שבחסד שבא הצמצום הזה רק מחמת החסד העצמי להחיות רוח שפלים דנשמות ישראל<sup data-n=\"8806\">895</sup> בגופים שיחיו מחיי עולם הא\"ס עצמו כו' כנ\"ל באורך וד\"ל. וזהו ויהי לי לישועה לי דוקא שזהו גורם בחי' ההבדלה והבירור בין ישראל למצרים להיות לי דוקא לישועה ולא למצרים אע\"פ שטענה מדה\"ד מה נשתנו אלו מאלו כו', לפי שע\"י בחי' גבורות וצמצום הזה דוקא שהי' רק בשביל אהבה וחסד לנש\"י להיותם בבחי' פנימי' ועצמיות ע\"כ<sup data-n=\"8807\">896</sup> עי\"ז הי' ההבדלה ובירור שלא יומשך בחי' פנימית האור דתו\"מ רק לנש\"י בלבד כמ\"ש יאר ה' פניו אליך<sup data-n=\"8808\">897</sup> אליך דוקא כנ\"ל, והוא ענין הבירור והבדלה שהי' ע\"י בחי' גבו' וצמצומים שלא ילך השפע הפנימי' רק לסט' דקדושה לבד ולא לבחי' החיצוני' ואחוריי' שהוא בחי' המותרות כנ\"ל שזהו ענין משפט למעלה כו', וזהו ויהי לי לישועה לי דוקא מצד בחי' ההבדלה ובירור בין הפנימי' וחיצוני' שזהו שנעשה דוקא ע\"י בחי' גבורות וצמצומי' דעז\"י וזמר\"ת י\"ה שאע\"פ שבאים ע\"י צמצום גדול כנ\"ל, אבל ע\"י בחי' גבו' וצמצום זה הוא שהבדיל לסט' דקדושה בלבד כו' וד\"ל (וכנ\"ל דמצד עצם הרוממות דא\"ס שלמעלה ממקור כל ההשתל'",[["8802","891","<b>שם הוי' בניקו\"ד אלקי\"ם ביו\"כ</b>: ראה מאמרי אדה\"ז תקס\"ו ע' שנ ואילך. ע' שס. נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380926\" data-slug=\"likkutei-torah\" data-id=\"4001380926\">לקו\"ת נצבים נא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380932\" data-slug=\"likkutei-torah\" data-id=\"4001380932\">נג, ב</a>."],["8803","892","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["8804","893","<b>חושבן</b>: ו: ליתא."],["8805","894","<b>אנת עילאה</b>: ת\"ז שם. ראה גם לקמן פ' פקודי תנד, א."],["8806","895","<b>דנשמות ישראל</b>: ו: לנשמות."],["8807","896","<b>ע\"כ</b>: ו: ליתא."],["8808","897","<b>אליך</b>: ו: ליתא."]]],[2300541063,"הי' מאיר גם בחושך כמו באור משום דקמי' כחשיכ\"ה כאור\"ה כו' וע\"כ ביקש משה שלא תשרה שכינה כו' רק ע\"י בחי' הבדלה זו דוקא א' ונפלינו כו' וזהו עז\"י וזמר\"ת י\"ה כנ\"ל וד\"ל).\n<b>זה</b> אלי ואנוהו כו'. הנה פסוק זה קאי אדסמיך לי' שא' עז\"י וזמר\"ת י\"ה כו', שבתחלת <span data-k=\"pg\">רסג</span> ּ החציבה הנ\"ל נחצב רק ב' אותיות די\"ה דשם הוי' שזהו וזמרת י\"ה כנ\"ל, והיינו בחי' הנסתרות שבתורה שאין זה רק בחי' הגילוי מן ההעלם דנקוד'<sup data-n=\"8809\">898</sup> די[ו\"ד] שהוא בבחי' העלם ויצא [לחוץ] לגילוי (כמו גילוי סוד ה' דסתים דאורייתא שיתגלה בימוהמ\"ש וכה\"ג), ואח\"כ נמשך ונתגלה עוד למטה בחי' אותיות דו\"ה דשם הוי' שהן בחי' הנגלות שבתו\"מ כמ\"ש והנגלות לנו ולבנינו<sup data-n=\"8810\">899</sup> כו' והיינו ו\"ה, [ד]וי\"ו הוא התורה הנגלית לנו וה\"א הוא המצוה כמ\"ש והתורה והמצוה אשר כתבתי להורתם<sup data-n=\"8811\">900</sup> כו', וזהו ואנוהו שהן אותיות ו\"ה הנרמז בתיבה זו דואנוהו (כמשי\"ת), שבכללות היינו שם הוי' בשלימותו. אך בתחלה א' וזמרת י\"ה ואח\"כ ו\"ה במ\"ש ואנוה\"ו (ומבואר למעלה שיש יתרון מעלה בתו\"מ הנגלות יותר מן הנסתרות לפי שנתחב\"ס דוקא שהוא לעשות צדק\"ה ומשפ\"ט כו' ע\"כ כאן אמר זה אל\"י לנוכח שהוא בחי' הגילוי דעצמות אוא\"ס ממש למטה כמו שהוא למעלה כו' כמו שיהי' בעוה\"ב כמשי\"ת). והנה מ\"ש זה אלי לנוכח ממש זהו כדוגמא שיהי' התגלות עצמו' א\"ס ב\"ה ממש בעוה\"ב דוקא (כמ\"ש שם נשמחה בו ממש כנ\"ל) לפי שבקי\"ס הי' ההארה והגילוי מעין הגילוי דעוה\"ב שא' ואמר ביום ההוא הנה אלקינו זה לנוכח שכל א' מראה באצבעו<sup data-n=\"8812\">901</sup> ואו' הנה אלקינו זה כו' וע\"כ א' זה אלי לנוכח וע\"כ ארז\"ל דראתה שפחה על הים מה שלא ראה יחזקאל כו'.\n<b>וביאור</b> הענין ומה שייך גילוי זה למ\"ש ואנוה\"ו בבחי' ו\"ה דשם הוי' דוקא כנ\"ל, הנה יש להקדים תחלה ביאור מ\"ש בסיפא דהאי קרא הנה אלקינו זה קוינו לו כו', דהנה ארז\"ל עמ\"ש אשר אנכי מצוך היום היום לעשותם<sup data-n=\"8813\">902</sup> ולמחר לקבל שכרם דשכר מצוה בהאי עלמא ליכא<sup data-n=\"8814\">903</sup> רק היום לעשותם בלבד כו', ויש להבין מהו ענין לעשותם דמשמע לעשות את המצות שיהיו נקראים מצות הוי' למעלה שזה תלוי בישראל למטה דוקא וכמ\"ש ועשיתם את כל מצותי<sup data-n=\"8815\">904</sup> כו' ובלתי מעשה המצות למטה לא נק' מצות הוי' למעלה כלל, והלא מבואר בזהר דרמ\"ח פקודי' הן נק' רמ\"ח אברים דמלכא למעלה כנ\"ל וזהו שנק' מצות\"י ממש וא\"כ מה צריך לעשות אותם למטה. אך מבואר למעלה דע\"י אתעדל\"ת במצות גשמיות שישראל עושי' למטה עושים הם למעלה בחי' המצות העליונות שיאיר גילוי אוא\"ס",[["8809","898","<b>דנקוד'</b>: ו: דוקא."],["8810","899","<b>והנגלות לנו ולבנינו</b>: נצבים כט, כח."],["8811","900","<b>והתורה והמצוה. . להורתם</b>: משפטים כד, יב. ראה גם לקמן פ' פקודי תנג, ב. וש\"נ."],["8812","901","<b>שכל א' מראה באצבעו</b>: תענית בסופה."],["8813","902","<b>אשר. . היום לעשותם</b>: נסמן לעיל פ' שמות ו, ד הערה 298."],["8814","903","<b>דשכר מצוה בהאי עלמא ליכא</b>: קדושין לט, ב. ראה מאמרי אדה\"א שמות ח\"ב ע' שטז. וש\"נ. קונטרסים ע' שיא ואילך."],["8815","904","<b>ועשיתם את כל מצותי</b>: שלח טו, מ."]]],[2300541066,"ברמ\"ח אברי' דמלכא בתוס' אור מן ההעלם דעצמו' כו', וז\"ש ועשיתם אותם אתם כתיב כאלו עשאוני. וזהו שא' היום לעשותם למעלה כו' שזהו דוקא בבחי' ו\"ה דשם הוי' הנגלות לנו ולבנינו לשמור ולעשות כו' מטעם דסוף מעשה דוקא עבמח\"ת, וע\"כ א' זה אל\"י כו' לנוכח מפני שבזה דוקא מתגלה מבחי' מהו\"ע ית' ממש כמו בעוה\"ב ממש כנ\"ל וד\"ל. וביאור הדברים הנה מבואר למעלה בשרש המצות שהן רק להמשיך אורות בכלים מבחי' המקיפי' העליונים שנק' לבושים כמו מצות תפילין בחי' מקיף דשם הוי' שבד' מוחי' שבראש כו' וכן במצות ציצית כו' וכידוע דאין המקיפי' שורים כ\"א על הכלים דוקא לפי ששרש הכלים מן המקיפי' שלמעלה מן האו\"פ כו', וידוע דראשית גילוי האו\"פ הוא בנקוד' די' דחכ' שמאין תמצא מן העלם המקיף דכתר, אבל בחי' הכלים שרשם מבחי' המקיף דכתר דוקא שלמעלה מן נקוד' די' דחכ' כו'.\n<b>וביאור</b> הענין הנה ידוע <span data-k=\"pg\">528</span> ּ בענין ג' מדרגות דנקוד' ספי' פרצוף<sup data-n=\"8816\">906</sup> שזהו<sup data-n=\"8817\">905</sup> ג' מדרגות דנקודה קו שטח<sup data-n=\"8818\">907</sup> דבחי' נקוד' הוא בחי' הצמצום וההעלם בהעדר התפשטות רק נקודה א' לבד כמו שהחכ' מאין תמצא [רק] כנקודה א' ואחר הצמצום דנקודה מתפשט ובא לבחי' גילוי מן ההעלם אין זה עדיין רק גילוי ההעלם לבד, אבל אין בחי' כלי לאור זה עדיין שיוגבל בו ויהי' ניכר במציאות יש ממש, אבל בחי' קו הוא בחי' ההמשכה שבאה מלמעלה למטה מן המשפיע למקבל אחר גילוי ההעלם שבמשפיע עצמו כמו הקו שיורד ונמשך מלמעלה למטה, והוא שיעשה בנין השטח שע\"י הקו יעשו בציור אות בג' קוין כאות הבי\"ת שיש בו ג' קוין למעלה ולמטה ובאמצע, וכן בבנין שטח אותיות אחרי' זולתו שכולם נבנין ע\"י הקו דוקא כמו קו המודד בנין הכלים שיצייר אותו במדת הקו לאורך ורוחב [ותוך] כו' וגם באות יו\"ד יצוייר בתמונה ע\"פ הקו כמו קוץ העליון וקוץ התחתון שבו וקו העושה התפשטות נקוד' די' עצמו כו', וזהו יתרון מעלה לקו על הנקודה שבנקודה לא יהי' ממנה בחי' השטח שהוא הכלי לאורך ורוחב ותוך כו' וע\"י הקו יעשו ממנו השטח, כי גוף השטח נעשה מן הקוין המצויירי' באופן מיוחד לכאן ולכאן עד שמחמת ריבוי אופני ציור והמשכת הקוין מזה נעשה ריבוי אופני הכלים שנק' שטח כשינוי אופני האותיות מא'",[["8816","906","<b>דנקוד' ספי' פרצוף</b>: ראה שעה\"י קכד, א ובהערה 4."],["8817","905","<b>ג'. . שזהו</b>: ו: ליתא."],["8818","907","<b>דנקודה קו שטח</b>: ראה גם שעה\"י קכ, א. מאמרי אדה\"א דרושי חתונה ח\"א ע' קכו ואילך. וש\"נ. לעיל קנ, ג. לקמן פ' תצוה שסז, א. ויקהל תמב, א."]]],[2300541068,"עד תי\"ו וכה\"ג, ולפי ששרש הכלים בבחי' מקיף דוקא כנ\"ל ע\"כ בהכרח לומר שבחי' הקו העושה השטח כנ\"ל שרשו למעלה מן הנקודה. וזהו ענין נקוד' ספי' פרצוף, דספי' זהו כשנמשך הנקודה למטה ונחלק לי' כו' שאז יוכל להיות בחי' התכללות רבות עד שמזה נעשה בחי' הכלים שנק' פרצוף וד\"ל (כמו אור וחיות הנפש בגוף שמתפשט מאין דחכמה ליש בריבוי אופנים שונים להיות מתמזג בריבוי כלים שונים שהן רמ\"ח אברים שנק' פרצוף אדם חיצוני ששרשו למעלה מאדם פנימי<sup data-n=\"8819\">908</sup> כמ\"ש במ\"א).",[["8819","908","<b>אדם חיצוני. . פנימי</b>: ראה לעיל קנט, ב."]]],[2300540072,"<b>חג הפסח ה' תקפ\"ו לפ\"ק לובאויטש</b>\n<span data-k=\"pg\">רסד</span> ּ<b>תפול</b> עליהם אימתה ופחד<sup data-n=\"8820\">1</sup> בגדול<sup data-n=\"8821\">2</sup> כו' עד יעבור<sup data-n=\"8822\">3</sup> עמך הוי' עד יעבור כו', הנה כל הפסוק הזה מדבר לע\"ל שהרי מדבר בלשון עתיד דוקא כמו תפול [עליהם] כו' עד יעבור כו' וכל יו\"ד להבא משמע<sup data-n=\"8823\">4</sup>, וענין תפול עליהם אימתה בה\"א היד[ו]ע[, הענין] הוא לפי שעכשיו אין ההארה בעולמות רק מבחי' מל' דאצי' ה' אחרונה<sup data-n=\"8824\">5</sup> דשם הוי' שמלובש ומוסתר בשם אלקי' כמו ה' מלך גיאות לבש<sup data-n=\"8825\">6</sup> כו' כידוע, עד שבע\"ש<sup data-n=\"8826\">7</sup> דנוגה מוסתר האור האלקי בהעלם ולבוש שק כמ\"ש מלך אלקי' על גוים<sup data-n=\"8827\">8</sup> כו', אבל לע\"ל יתגלה בעולמות מבחי' מל' דא\"ס עצמו כמ\"ש ה' ימלוך לע\"ו<sup data-n=\"8828\">9</sup> (שנק' מלך המרומם לבדו מאז<sup data-n=\"8829\">10</sup> כו' מלך [הקדוש] ש[ז]הו בחי' ההתנשאו' דמדת מל' ית' העצמי' שמצד עצמו ממש, שמעין זה הי' בקי\"ס שמפני זה נעשה מבחי' [ה]העלם גילוי כמשי\"ת), ע\"כ א' תפול עליהם ל[שון] עתיד אימתה דמל' דא\"ס כמ\"ש ממקומך תופיע ותמלוך<sup data-n=\"8830\">11</sup> כו' (וכמו בכל ר\"ה ור\"ה שאומרים המלך הקדוש<sup data-n=\"8831\">12</sup> מבחי' סדכ\"ס<sup data-n=\"8832\">13</sup> דלמחתב\"כ<sup data-n=\"8833\">14</sup>, שע\"כ א[ו]מר ובכן תן פחדך כו' ושמך נורא<sup data-n=\"8834\">15</sup> על כל<sup data-n=\"8835\">16</sup> כו' כמו שיהי' לע\"ל שיהי' פחד ה'<sup data-n=\"8836\">17</sup> על כל הברואים הגשמי', וכך [גם] עכשיו מאיר לפרקים כמו בפרות שנשאו [את] ארון אלקים שאמרו שירה<sup data-n=\"8837\">18</sup> [כ]מרכבה עליונה דפני שור<sup data-n=\"8838\">19</sup> כו', וגם למלכים נתגלה האור הגדול מזה ונתבטלו ממציאותם כמו לנבוכדנאצר<sup data-n=\"8839\">20</sup> וסנחריב<sup data-n=\"8840\">21</sup> וכה\"ג וכמ\"ש ירא[ו] מה'<sup data-n=\"8841\">22</sup> כו' מי לא ייראך מלך הגוים<sup data-n=\"8842\">23</sup> כו'). וזהו תפול עליהם אימתה ופחד כו'",[["8820","1","<b>תפול עליהם אימתה ופחד</b>: מיוסד על ד\"ה זה שנדפס במאמרי אדה\"א ויקרא ח\"א ע' רג. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["8821","2","<b>בגדול</b>: ויז: ליתא."],["8822","3","<b>תפול עליהם. . עד יעבור</b>: בשלח טו, טז."],["8823","4","<b>יו\"ד להבא משמע</b>: נסמן לעיל קנ, א."],["8824","5","<b>מל'. . ה' אחרונה</b>: נסמן לעיל קנח, א."],["8825","6","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["8826","7","<b>שבע\"ש</b>: נסמן לעיל פ' שמות לז, ג."],["8827","8","<b>מלך אלקי' על גוים</b>: תהלים מז, ט."],["8828","9","<b>ה' ימלוך לע\"ו</b>: בשלח טו, יח."],["8829","10","<b>מלך המרומם לבדו מאז</b>: ע\"פ ברכת יוצר."],["8830","11","<b>ממקומך תופיע ותמלוך</b>: נוסח הקדושה לשויו\"ט [בדילוג — ראה גם לקמן פ' תצוה שנב, א. מאמרי אדה\"א בראשית ע' תכח. וש\"נ]."],["8831","12","<b>ור\"ה שאומרים המלך הקדוש</b>: שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב, ס\"א."],["8832","13","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["8833","14","<b>דלמחתב\"כ</b>: ראה ת\"ז בהקדמה (יז, א)."],["8834","15","<b>ובכן תן פחדך. . נורא</b>: תפלת העמידה לימים נוראים."],["8835","16","<b>על כל</b>: ויז: ליתא."],["8836","17","<b>לע\"ל שיהי' פחד ה'</b>: ראה גם לעיל קסא, ד. לקמן רכה, ד. פ' ויקהל שצט, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקכג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380964\" data-slug=\"likkutei-torah\" data-id=\"4001380964\">לקו\"ת ר\"ה סא, ב</a>. שע\"ת ח, א. מאמרי אדה\"א הנחות תקע\"ז ע' קסח. וש\"נ."],["8837","18","<b>בפרות שנשאו. . שאמרו שירה</b>: נסמן לעיל פ' וארא עד, א."],["8838","19","<b>[כ]מרכבה. . דפני שור</b>: יחזקאל א, י."],["8839","20","<b>ונתבטלו. . לנבוכדנאצר</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תצה־ דרושי חתונה ח\"ב ע' תי ובהנסמן בהנ\"ל."],["8840","21","<b>ונתבטלו. . וסנחריב</b>: ראה להלן קצג, ד. וש\"נ."],["8841","22","<b>ירא[ו] מה'</b>: תהלים לג, ח."],["8842","23","<b>מי לא ייראך מלך הגוים</b>: ירמי' י, ז."]]],[2300540110,"[כמו] <b>ובאו</b> במערות צורים<sup data-n=\"8843\">24</sup> מפני פחד ה' כו' וכמ\"ש ושמך נורא על כל מה שבראת כו', בגדול זרועך [ש]זהו בימות המשיח ידמו כאבן בבחי' דומם לבד מצד עוצם בחי' הביטול שיהי' אז בכללו'<sup data-n=\"8844\">25</sup> העולמות מצד גילוי אור דמל' דא\"ס עצמו שע\"כ גם מה שיהי' בבחי' אדם ידמו כאבן כמו שמש בגבעון דום<sup data-n=\"8845\">26</sup> שנתבטל במציאות ונעשה כמו דומם ממש וכה\"ג וד\"ל.\n<b>והנה</b> מטעם זה יהי' ג\"כ העברה שני' דלע\"ל בגאולה האחרונה ביתרון מעלה [הרבה] מבקי\"ס בגאולה הראשונה, והיינו העברה שיהי' עוד במשיח<sup data-n=\"8846\">28</sup> בקיבוץ גליות בנהר פרת<sup data-n=\"8847\">27</sup> כמו שעברו בי\"ס כמ\"ש בישעי' (מ\"ב<sup data-n=\"8848\">29</sup> ) והחרים ה' את לשון ים מצרים והניף ידו<sup data-n=\"8849\">30</sup> על הנהר כו' והכהו לז' נחלים והיתה מסלה לשאר עמו כאשר הי' בעלותן<sup data-n=\"8850\">31</sup> מאמ\"צ כו', [ו]כמ\"ש הפך ים [ליבשה]<sup data-n=\"8851\">32</sup> הפך לשעבר משמע<sup data-n=\"8852\">33</sup> דקאי על קי\"ס ביצ\"מ שכבר הפך ים ליבשה ומ\"ש בנהר יעברו ברגל בלשון עתיד יעברו לע\"ל, וכן שם נשמחה בו<sup data-n=\"8853\">34</sup> לשון להבא דקאי על לע\"ל בהעברה שני' בנהר פרת כמ\"ש והניף ידו על הנהר כו'. ומה שהי' בקי\"ס בי\"ב גזרים נגד י\"ב שבטים<sup data-n=\"8854\">35</sup> ובנהר דלע\"ל הכה[ו] לז' נחלים<sup data-n=\"8855\">36</sup> כו' שהן בחי' ז' מדות שמתחלקי' מבינה עילאה שנק' נהר<sup data-n=\"8856\">37</sup>, שבקי\"ס הי' הבקיעה רק מבחי' מל'<sup data-n=\"8857\">38</sup> שנק' סופא דכ\"ד<sup data-n=\"8858\">39</sup> בה\"א אחרונה כו' ולע\"ל יהי' הבקיעה בנהר דבינה שזהו בחי' ה' עילאה דשם הוי'<sup data-n=\"8859\">40</sup> (כמשי\"ת). והנה ידוע דהנס [ד]לע\"ל בהעברה שני' בנהר פרת יהי' גדול הרבה מנס דקי\"ס ביתר שאת ויתר עז<sup data-n=\"8860\">41</sup> עד שנס דקי\"ס יהי' לע\"ל רק בבחי' טפל, וכמ\"ש חז\"ל ביצ\"מ דכתי' למען תזכור<sup data-n=\"8861\">42</sup> את יום צאתך מאמ\"צ כל ימי חייך אף בעוה\"ב דהיינו שיהי' זכרון ליצ\"מ בדרך טפל ודוגמא בעלמא לנסים דלע\"ל וכמ\"ש כימי צאתך מאמ\"צ למטה באותות ומופתים גדולים אראנו נפלאות<sup data-n=\"8862\">43</sup> למעלה לע\"ל דהיינו נפלאות [לשון] רבים שהן בחי' סדכ\"ס ממש למעלה כמ\"ש נפלאותיך ומחשבותיך<sup data-n=\"8863\">44</sup> כו' (שזהו עליות המדריגות <span data-k=\"pg\">530</span> ּ בהעלם אחר העלם בעילוי אחר עילוי בעצמות אוא\"ס ב\"ה שנק' סדכ\"ס דלמתב\"כ והוא בחי' ההתנשאות שמצד עצמותו כו' וד\"ל<sup data-n=\"8864\">45</sup> )",[["8843","24","<b>ובאו במערות צורים</b>: ישעי' ב, יט [בדילוג]."],["8844","25","<b>בכללו'</b>: ויז: בכל."],["8845","26","<b>שמש בגבעון דום</b>: נסמן לעיל פ' שמות ל, ב."],["8846","28","<b>עוד במשיח</b>: ויז: ע\"י משיח."],["8847","27","<b>העברה שני'. . בנהר פרת</b>: נסמן לעיל פ' שמות מ, ד."],["8848","29","<b>(מ\"ב)</b>: ויז: יב. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380147\" data-slug=\"likkutei-torah\" data-id=\"4001380147\">לקו\"ת צו יז, ד</a>. וצ\"ל: יא."],["8849","30","<b>והחרים ה'. . והניף ידו</b>: שם פסוק טו."],["8850","31","<b>והיתה מסלה. . בעלותן </b>[ויז: בעלותו]: שם פסוק טז [בדילוג — ושם: ביום עלותו]."],["8851","32","<b>הפך ים [ליבשה]</b>: תהלים סו, ו. ראה גם לעיל קלט, א. וש\"נ."],["8852","33","<b>לשעבר משמע</b>: ויז: לשון עבר."],["8853","34","<b>בנהר יעברו ברגל. . שם נשמחה בו</b>: המשך הכתוב הפך ים ליבשה."],["8854","35","<b>בי\"ב גזרים נגד י\"ב שבטים</b>: נסמן לעיל קנח, א."],["8855","36","<b>ובנהר. . לז' נחלים</b>: נסמן לעיל שם."],["8856","37","<b>מבינה. . נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["8857","38","<b>שבקי\"ס. . מבחי' </b>[ויז: בבחי']<b> מל'</b>: ראה גם לעיל קנח, א. וש\"נ."],["8858","39","<b>מל' שנק' סופא דכ\"ד</b>: נסמן לעיל פ' בא פח, ג."],["8859","40","<b>דבינה. . ה'. . דשם הוי'</b>: נסמן לעיל יב, ד הערה 581."],["8860","41","<b>ביתר שאת ויתר עז</b>: ע\"פ ויחי מט, ג."],["8861","42","<b>חז\"ל </b>[ויז: רז\"ל]<b>. . למען תזכור</b>: נסמן לעיל קיא, ד."],["8862","43","<b>כימי צאתך מאמ\"צ. . אראנו נפלאות</b>: מיכה ז, טו."],["8863","44","<b>נפלאותיך ומחשבותיך</b>: תהלים מ, ו."],["8864","45","<b>עצמותו כו' וד\"ל</b>: ו: עצמו הנ\"ל. יז: עצמות הנ\"ל וד\"ל."]]],[2300540148,"(וכידוע דגם בעוה\"ב ילכו מחיל אל חיל<sup data-n=\"8865\">46</sup> בלי שיעור למעלה כלל וכמ\"ש גם עתה וקדושים בכ\"י יהללוך סלה בלי הפסק<sup data-n=\"8866\">47</sup> כלל כמו נשמת האבות<sup data-n=\"8867\">48</sup> ונשמת משה<sup data-n=\"8868\">49</sup> ואהרן וכה\"ג וכמ\"ש במ\"א וד\"ל<sup data-n=\"8869\">50</sup> ). אך זהו בבחי' העליות למעלה בעילוי אחר עילוי עד אין מספר<sup data-n=\"8870\">51</sup> למעלה לפי שא[ו]\"ס למעלה עד אין קץ<sup data-n=\"8871\">52</sup> וע\"כ [נק'] נפלאות לשון רבים, אך לע\"ל [א'] אראנו נפלאות דבחי' נפלאו'<sup data-n=\"8872\">53</sup> הללו כמו שהן למעלה אראנו למטה כמו שהן למעלה ממש לפי שיהי' בחי' התגלות אוא\"ס למטה כמו למעלה ממש וכמ\"ש ואמר ביום ההוא<sup data-n=\"8873\">54</sup> הנה אלקינו זה לנוכח כו' אשר קוינו לו בעליות וירידות בבחי' קוין<sup data-n=\"8874\">55</sup> כו' וכמ\"ש במ\"א.\n<b>והנה</b> מ\"ש אראנו נפלאות<sup data-n=\"8875\">56</sup> ל' יחיד [דלא נודע] על מ[י] הוא אומר זה, ובזהר מפרש דקאי על בחי' ישראל דלעילא שנק' ישראל<sup data-n=\"8876\">58</sup> סבא<sup data-n=\"8877\">57</sup> (כי יש בחי' ישראל זוטא<sup data-n=\"8878\">59</sup> כמשי\"ת), והטעם לזה הוא כי ביצ\"מ אמר וירא ישראל<sup data-n=\"8879\">60</sup> את היד הגדולה אשר עשה ה' במצרים הרי ישראל שלמטה ראה את אשר עשה ה' במצרים בטבעם בי\"ס למטה וכך אמר כימי צאתך כו' אראנו <sup data-n=\"8880\">61</sup>כו' פי' לישראל זה כמו שהוא למעלה שנק' ישראל סבא בחי' נפלאות סדכ\"ס שלמעלה כנ\"ל לפי שלמעלה<sup data-n=\"8881\">62</sup> יהי' הנס במקום [ו]מדרגה עליונה ביותר הרבה מנס דקי\"ס ע\"כ א' אראנו נפלאות לישראל סבא בגילוי מן ההעלם דבחי' סדכ\"ס עצמו כנ\"ל וד\"ל (ואע\"פ שאמר וירא ישראל את היד הגדולה שהוא בחי' א\"ס [למטה מטה שיורד] למטה עד אין קץ ותכלית<sup data-n=\"8882\">63</sup> אבל לע\"ל אראנו לישראל זה למעלה באוא\"ס שבהעלם העצמי שנק' סדכ\"ס שאין לו שיעור למעלה ויראנו בגילוי למטה דוקא כנ\"ל). וזהו שא' עד יעבור לשון להבא דקאי לע\"ל, ואמר ב\"פ עד יעבור [ו]פעם הב' לא הזכיר שם הוי' כלל [אלא] עד יעבור סתם [ש]למעלה משם הוי' (וכמו ביו\"כ כתי'<sup data-n=\"8883\">65</sup> כי ביום הזה יכפר<sup data-n=\"8884\">66</sup> עליכם<sup data-n=\"8885\">67</sup> סתם) כו'<sup data-n=\"8886\">68</sup> זהו ב' מדריגות<sup data-n=\"8887\">69</sup> דימוהמ\"ש ועוה\"ב<sup data-n=\"8888\">64</sup> כמ\"ש אהי' אשר<sup data-n=\"8889\">71</sup> אהי'<sup data-n=\"8890\">70</sup> אנא זמין לאתגלאה<sup data-n=\"8891\">72</sup> [ב]ימוהמ\"ש אנא זמין לאתגלאה<sup data-n=\"8892\">73</sup> בעוה\"ב כמ\"ש יחיינו מיומים<sup data-n=\"8893\">74</sup> בימוהמ\"ש ביום השלישי יקימנו בעוה\"ב<sup data-n=\"8894\">75</sup> ונחי' לפניו ממש חיי עולם הנצחים דאצי'<sup data-n=\"8895\">76</sup> ממש. וזהו",[["8865","46","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["8866","47","<b>וקדושים. . סלה בלי הפסק</b>: ברכת אתה קדוש. עירובין נד, א."],["8867","48","<b>וקדושים. . נשמת האבות</b>: נסמן לעיל פ' שמות ד, ג."],["8868","49","<b>ונשמת משה</b>: ויז: ומשה."],["8869","50","<b>וד\"ל</b>: ו: ליתא."],["8870","51","<b>מספר</b>: ויז: שיעור."],["8871","52","<b>שא[ו]\"ס למעלה עד אין קץ</b>: נסמן לעיל פ' שמות ד, ד."],["8872","53","<b>דבחי' נפלאו'</b>: ויז: ליתא."],["8873","54","<b>ואמר ביום ההוא</b>: ישעי' כה, ט."],["8874","55","<b>קוינו. . קוין</b>: ראה מאמרי אדה\"א שמות ח\"א ע' טו. ויקרא ח\"א ע' קיח. הנחות תקע\"ז ע' סג ובהנסמן בהנ\"ל."],["8875","56","<b>נפלאות</b>: ו: ליתא."],["8876","58","<b>ישראל סבא</b>: ראה ב\"ר פע\"ד, ח. זהר ויחי רלג, א. רלו, א. ועוד."],["8877","57","<b>אראנו. . ישראל סבא</b>: נסמן לעיל פ' שמות כא, א."],["8878","59","<b>ישראל זוטא</b>: ראה זהר ויקהל רטז, א."],["8879","60","<b>וירא ישראל</b>: בשלח יד, לא."],["8880","61","<b>כו'</b>: ויז: ליתא."],["8881","62","<b>שלמעלה</b>: שם: שלע\"ל."],["8882","63","<b>קץ ותכלית</b>: שם: תכלית."],["8883","65","<b>כתי'</b>: ויז: שא'."],["8884","66","<b>כי ביום הזה יכפר</b>: אחרי טז, ל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a>. מאמרי אדה\"א דברים ח\"ג ע' א'ה. וש\"נ."],["8885","67","<b>עליכם</b>: ויז: ליתא."],["8886","68","<b>כו'</b>: ויז: כי."],["8887","69","<b>ב' מדריגות</b>: תוקן ע\"פ: ויז. ובתו\"ח: מדרגת."],["8888","64","<b>ב\"פ עד יעבור. . דימוהמ\"ש ועוה\"ב</b>: ראה גם לעיל פ' שמות א, ב. וש\"נ."],["8889","71","<b>אהי' אשר אהי'. . [ב]ימוה\"ש. . בעוה\"ב</b>: ראה לעיל פ' שמות א, ב ובהערה 17."],["8890","70","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["8891","72","<b>אנא זמין. . לאולדא. . לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."],["8892","73","<b>לאתגלאה</b>: ויז: לאולדא."],["8893","74","<b>יחיינו מיומים</b>: הושע ו, ב."],["8894","75","<b>בעוה\"ב</b>: ו: ליתא."],["8895","76","<b>דאצי'</b>: ויז: דא\"ס."]]],[2300540185,"שאמר כאן עד יעבור לע\"ל בימוהמ\"ש שבזה יש שם הוי' [ד]תומ\"צ בתשלום הבירורים דעה\"ד כו', אבל <sup data-n=\"8896\">77</sup>לע\"ל עד יעבור הב' קאי בעוה\"ב שלמעלה מהבירורים דתומ\"צ בשם הוי'<sup data-n=\"8897\">78</sup> דחכ' כידוע ע\"כ אמר סתם עד יעבור (והעברה זו קאי בהעברה שני' בנהר פרת שא' הוא דמעיקרא<sup data-n=\"8898\">80</sup> דוקא שזהו לעבור בנהר הגדול שיוצא מעדן [לעדן] עצמו כמ\"ש במ\"א, אבל העברה דעד יעבור הא' קאי בל' נהר<sup data-n=\"8899\">81</sup> מצרים שהוא נהר נילוס<sup data-n=\"8900\">79</sup> לבד כמ\"ש בנחל מצרים עד הנהר הגדול נהר פרת<sup data-n=\"8901\">82</sup> כו' דמיירי לאחר כיבוש כל העמים אף הקיני והקניזי והקדמוני כו' וזה יהי' בסוף ימוהמ\"ש כשיכינו עצמם לבוא באור<sup data-n=\"8902\">83</sup> החיים [ד]עוה\"ב שהוא כמו בחי' ג\"ע<sup data-n=\"8903\">84</sup> כמ\"ש במ\"א).\n(ב) <b>והנה</b> י\"ל עוד בפרטיות ענין [ד]קי\"ס [ב]מ\"ש ויסע מלאך [ה]אלקי'<sup data-n=\"8904\">85</sup> ההולך לפני מחנה ישראל וילך מאחריהם ויסע עמוד הענן [מפניהם כו'] ויבא בין מחנה מצרים<sup data-n=\"8905\">86</sup> ובין מחנה ישראל ויהי הענן והחשך ויאר את הלילה ולא קרב זא\"ז כל הלילה ויט משה את ידו על הים ויולך<sup data-n=\"8906\">87</sup> ה' את הים ברוח קדים עזה כל הלילה כו' ויבקעו המים כו' שזהו עיקר קי\"ס מה ש[נ]בקעו המים ע\"י רוח קדים עזה כל הלילה כו', וי\"ל למה הוצרך <span data-k=\"pg\">רסה</span> ּ לכל אלה תחלה שיסע מלאך האלקי' ועמוד הענן ויעמדו מאחריהם ויבא בין כו', ומה שהי' הענן והחשך ע\"י עמידת מלאך האלקי' ו[עמוד] הענן בין מחנה כו' דוקא כמובן מפשט הכתוב. ועוד דמשמע מזה דעיקר התועלת מעמידת המלאך והענן הוא רק להבדיל ולעשות מחיצה בין ישראל למצרים שלא יקרבו זה [א]ל זה כו' [ו]הרי כשאמר ויהי הענן והחשך ויאר כו' משמע ד[ה]ענן והחשך עצמו הוא ש[י]איר את הלילה וא\"כ הרי הי' אור ג\"כ [ל]מצרים ולמה לא קרב זה אל זה כל הלילה כו'. ועוד דמשמע דמחמת ג' דברים אלה דויסע ויבא ויט כו' הי' סיבת קי\"ס ובאמת לא הי' רק מחמת רוח קדים עזה שבקעו המים כו'.\n<b>הנה</b><sup data-n=\"8907\">88</sup> מתחלה י\"ל במהות ועצם דקי\"ס איך הי', דהנה לכאורה מובן מפשט הכתוב ויבאו בנ\"י בתוך הים<sup data-n=\"8908\">89</sup> ביבשה והמים להם חומה מימינם ומשמאלם<sup data-n=\"8909\">90</sup> כו', וירדפו מצרים אחריהם<sup data-n=\"8910\">91</sup> כל סוס פרעה כו', הרי שהי' בקיעת הים מעצמו שנבקע<sup data-n=\"8911\">92</sup> ונעשה יבשה בתוך הים במסילה רחבה והלכו בנ\"י ביבשה זו בתוך המי<sup data-n=\"8912\">93</sup> הים כו'. וזהו שא' הפך ים ליבשה דהיינו מה שנהפך מים עצמו להיות בחי' יבשה והוא המסילה שנעשה בים עצמו כמ\"ש",[["8896","77","<b>לע\"ל</b>: ויז: ליתא."],["8897","78","<b>עד יעבור הב'. . שלמעלה. . הוי'</b>: ראה לעיל א, ב. וש\"נ."],["8898","80","<b>פרת. . הוא דמעיקרא</b>: נסמן לעיל א, ב."],["8899","81","<b>בל' נהר</b>: ויז: בלשון ים."],["8900","79","<b>עד יעבור. . בנהר פרת. . דעד יעבור הא'. . נילוס</b>: ראה לעיל פ' שמות כג, א. מאמרי אדה\"א דברים ח\"א ס\"ע טו ואילך. ויקרא ח\"א ע' רכ."],["8901","82","<b>בנחל </b>[ויז: מנחל]<b> מצרים. . פרת</b>: מלכים-ב כד, ז [בהוספת התיבות: ”הנהר הגדול\"]."],["8902","83","<b>באור</b>: ויז: בארץ."],["8903","84","<b>ג\"ע</b>: שם: געה\"ע."],["8904","85","<b>ויסע מלאך [ה]אלקי'</b>: בשלח יד, יט."],["8905","86","<b>ויבא בין מחנה מצרים</b>: בשלח יד, כ."],["8906","87","<b>ויט משה את ידו. . ויולך</b>: שם שם, כא."],["8907","88","<b>הנה</b>: ד: נסמן כאן ס\"ב. ס\"ג להלן על יד הערה 145."],["8908","89","<b>ויבאו בנ\"י בתוך הים</b>: בשלח יד, כב."],["8909","90","<b>מימינם ומשמאלם</b>: ויז: ליתא."],["8910","91","<b>וירדפו מצרים אחריהם</b>: בשלח שם, כג [בדילוג]."],["8911","92","<b>שנבקע</b>: ויז: שנהפך."],["8912","93","<b>המי</b>: שם: ליתא."]]],[2300540222,"הנותן בים דרך<sup data-n=\"8913\">94</sup> ובמים עזים נתיבה כו' והוא שא' לע\"ל והיתה מסילה לשאר עמו<sup data-n=\"8914\">95</sup> [כו'] כאשר היתה כו', אבל באמת מאחר ד[ז]ה שא' ויבאו בנ\"י כו' דקאי אדסמיך לי' דוקא שא' ויבקעו המים, דלשון בקיעה אינו רק כמו בקיעה וסדק קצר ולא ענין הפ[ו]ך מים ליבשה, דעל הבקיעה לבד לא שייך לשון היפ[ו]ך ממהות למהות מאחר שאינו אלא [בחי'] בקיעה בעלמא לבד כו', ואע\"פ שא' הכתוב<sup data-n=\"8915\">96</sup> והמים להם חומה מימינם ומשמאלם<sup data-n=\"8916\">97</sup> כו' הרי [הי'] הפסק גדול בים ש[י]עברו בו והמים להם כחומה [מימינם ומשמאלם] כו' הנה גם זה לא הי' בענין היפ[ו]ך הים עצמו ליבשה כו' אלא שנגזר המים לגזרים לבד כמ\"ש לגוזר י\"ס לגזרים<sup data-n=\"8917\">98</sup> כו' ולא שהים נהפך ליבשה כו', וא\"כ לכאורה איך א' הפך ים ליבשה דמשמע שמהות הים עצמו נהפך למהות יבשה כו'. אך הענין הוא דבקי\"ס היו ב' דברים<sup data-n=\"8918\">99</sup>, א' מה שנעשה גוף הים עצמו בחי' דומם ממש כיבשה וארץ, שהרי א' הכתוב והמים להם חומה כחומה של אבנים ממש שהוא בחי' דומם ממש וא' נצבו כמו נד כו' קפאו<sup data-n=\"8919\">100</sup> תהומות כו' [ו]כמ\"ש בזהר דאגלידו מיא<sup data-n=\"8920\">101</sup> שנעשה כמו קרח וכפור קשה כאבן דומם וזהו נצבו כו', וזה הי' מיד אחר הבקיעה שנבקעו ונגלדו ונעשו קרח מימין ומשמאל כו', אך עדיין לא הי' מסילה ממש למטה. והב' הוא [ה]דרך והמסילה דיבשה שנעשה בים להיות להם ל[מ]עבר ברגליהם ממש, וזה הי' מחמת הבקיעה שנבקעו המים מלמעלה עד למטה ביבשה וארץ שמתחת למי הים שהלכו שם ביבשה בתוך הים כו' (וזה הי' מהרוח קדים שהוליך את הים ועש[ה]ו לחרבה ואח\"כ א' ויבקעו המים, ולכאו' סותר סיפא לרישא דברישא א' וישם את הים לחרבה ממש לפי שהרוח הי' מן המזרח ואח\"כ [א'] ויבקעו המים, אלא שחזר הרוח מזרחית והוכפל להיותו נושב מן הצפון אל דרום ומדרום אל צפון [כ]ב' הפכי' בנושא א' והרוח חזק הרבה מן המים עד שבכחו להעמיד את המים כחומה ממש וגלי הים יוכיחו כו', ולכך <span data-k=\"pg\">532</span> ּ היו המים להם חומה ממש מימינם ומשמאלם אחר שנבקעו המים מן הרוח הקדים בחי' ת\"ת שכולל חו\"ג<sup data-n=\"8921\">102</sup> צפון ודרום).\n<b>והנה</b> עפ[כ]\"ז יובן ג\"כ ב[ענין] קי\"ס למעלה דכמו שנהפך ים ליבשה למטה בב' ענינים כנ\"ל, [כ]ך הוא למעלה כידוע בשרש בחי' ים [סוף] למעלה זהו בחי' המל'<sup data-n=\"8922\">103</sup> שהוא מדה אחרונה דאצי' שנק' סופא דכ\"ד וכתי' כל הנחלים הולכים אל הים<sup data-n=\"8923\">104</sup> כו' שהן בחי' המדות העליונות דאצי' שנמשכים לבחי' המל' (והים איננו מלא כמ\"ש במ\"א), וידוע דיש בבחי' המל' ב'",[["8913","94","<b>הנותן בים דרך</b>: ישעי' מג, טז."],["8914","95","<b>והיתה מסילה לשאר עמו</b>: ישעי' יא, טז."],["8915","96","<b>הכתוב</b>: ויז: ליתא."],["8916","97","<b>ומשמאלם</b>: שם: ליתא."],["8917","98","<b>לגוזר י\"ס לגזרים</b>: תהלים קלו, יג."],["8918","99","<b>דבקי\"ס היו ב' דברים</b>: ראה גם מאמרי אדה\"א ויקרא כאן ע' רד. וש\"נ. לקמן קצא, ג."],["8919","100","<b>נצבו. . קפאו</b>: בשלח טו, ח."],["8920","101","<b>דאגלידו מיא</b>: ראה זהר בשלח נ, ריש ע\"ב."],["8921","102","<b>ת\"ת שכולל חו\"ג</b>: נסמן לעיל פ' בא פט, א."],["8922","103","<b>ים [סוף]. . מל'</b>: זהר (רע\"מ) פינחס רנו, ב."],["8923","104","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז. ראה גם מאמר ד\"ה דור לדור [מכ\"ק אדה\"א קה\"ת תשנ\"ב] ע' 11. מאמרי אדה\"א שמות ח\"ב ע' תסב."]]],[2300540254,"מדרגות העלם וגילוי (אותיות המח' שנק' לא\"ה ואותיות הדבור שנק' רח\"ל<sup data-n=\"8924\">105</sup> ) עלמא דאתכסיי' ועלמא<sup data-n=\"8925\">107</sup> דאתגלייא<sup data-n=\"8926\">106</sup> כו', וארז\"ל דכל מה שיש בים<sup data-n=\"8927\">108</sup> יש ביבשה וכל מה שביבשה יש בים כו' כי כל הברואים ש[יש] ביבשה יש כנגד[ו] בים, וזהו בחי' אותיות הדבור העליוני' דעש\"מ שא' לארץ תוצא הארץ<sup data-n=\"8928\">109</sup> וכל מע\"ב הכל הי' מן העפר<sup data-n=\"8929\">110</sup> דארץ אפיקת תולדין<sup data-n=\"8930\">111</sup> כו' כמ\"ש יקוו המים<sup data-n=\"8931\">112</sup> כו' ותראה היבשה, כי תחלה הי' היבשה מובלע בים [כמו] שגילוי הדבור נכלל בהעלם [ה]מח' ואח\"כ א' יקוו המים שלא יכסה הים על היבשה ותראה היבשה שהוא עולם הדבור ה' אחרונה ה' מוצאות הפה כמ\"ש ואתה מחי'<sup data-n=\"8932\">113</sup> כו' כידוע. וא\"כ הרי מובן שכמו שבקי\"ס הי' גילוי ההעלם דים שנעשה יבשה, כך הי' למעלה [ש]בחי' ההעלם דמל' דאצי' שנק' ים העליון בחי' עלמא דאתכסי' בכלל שנק' עלמא סתימאה כו' ששם יש כל הברואים שיש ביבשה בעולם הדבור בארץ שיצא ממנה כל נפש חי' כו' שזהו בחי' פני ארי' ושור וכה\"ג יש הכל בעולם המח' שנק' ים, הוא עצמו שנעשה בבחי' גילוי כמו המח' שנעשה בבחי' דבור (וזהו כמו שקפאו תהומות ונצבו כחומה בבחי' דומם כנ\"ל), שזהו ג\"כ ענין מה שנהפך החשך לאור כמ\"ש ויהי הענן והחשך<sup data-n=\"8933\">114</sup> ויאר את הלילה דבחי' ההעלם דענן וחשך עצמו הוא שנעשה בבחי' גילוי כמו אור, שזה הי' קודם הבקיעה שנבקעו המים מן הרוח הקדים שהלכו בנ\"י כו' כי המלאך והענן עמדו מאחריהם ויבא בין כו' קודם שבאו בנ\"י בתוך הים כו' (כמשי\"ת), והב' הוא ענין הבקיעה של פרסא העליונה שנבקע ונקרע דהיינו במסך המפסיק בין אצי' לבריאה<sup data-n=\"8934\">115</sup> נעשה בקיעה וקריעה עד שנעשה גילוי אור האצי' שבהעלם דים העליון בבחי' בריאה ממש (שזהו כמו שנעשה דרך ומסילה ביבשה בתוך הים כו' כנ\"ל), שזהו כמו רוה\"ק וגילוי אלקו'<sup data-n=\"8935\">116</sup> בנביאי' וצדיקי' בעוה\"ז כמו באצי' ממש, וכיוסף הצדיק שהי' טרוד בכתבי דחושבנא<sup data-n=\"8936\">117</sup> ולא הי' [זה] הפסק וביטול למדריגתו באצי' כו' כמ\"ש במ\"א ([ו]כמ\"ש בזהר ע\"פ וידגו לרוב בקרב הארץ<sup data-n=\"8937\">118</sup> דבחי' נוני ימא אזלא ביבשתא כו' דנשמות דים עילאה עלמא דאתכסי' בא[י'] למטה להיות בבחי' בריאה לנשמו' דעלמא דאתגלי' בבחי' יבשה כנ\"ל). וזהו בבחי' דילוג שלא כפי סדר ההשתל' מריש כ\"ד עד סוף כ\"ד מעילה לעלול<sup data-n=\"8938\">119</sup> שאין ההעלם עצמו נעשה גילוי וצ\"ל הילוך [בעוה\"ז] האורות ושפע מעליון לתחתון ע\"י בחי' הפרסא המפסיק דוקא שזהו המסך שבין אצי' לבריאה ומבריאה ליצי' עד עולם העשי' כמשי\"ת וד\"ל.",[["8924","105","<b>אותיות המח' שנק' לא\"ה. . רח\"ל</b>: ראה לעיל פ' שמות יח, רע\"ב. וש\"נ."],["8925","107","<b>עלמא דאתכסיי' ועלמא דאתגלייא</b>: נסמן לעיל לג, א."],["8926","106","<b>המח'. . הדבור. . עלמא דאתכסיי' ועלמא דאתגלייא</b>: נסמן לעיל קמג, ד."],["8927","108","<b>דכל מה שיש בים</b>: נסמן לעיל פ' שמות יח, ג."],["8928","109","<b>תוצא הארץ</b>: בראשית א, כד."],["8929","110","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["8930","111","<b>דארץ אפיקת תולדין</b>: ראה זהר בהקדמה יב, א. בראשית מו, ב."],["8931","112","<b>יקוו המים</b>: בראשית א, ט."],["8932","113","<b>ואתה מחי'</b>: נחמי' ט, ו. ראה שער היחוד והאמונה פ\"ב."],["8933","114","<b>ויהי הענן והחשך</b>: נסמן לעיל קמג, ג."],["8934","115","<b>במסך המפסיק בין אצי' לבריאה</b>: נסמן לעיל צו, ד. (וראה לקמן קפט, א ובהערה 221)."],["8935","116","<b>אלקו'</b>: יז: אליהו. ראה גם לעיל פ' בא צח, א הערה 80."],["8936","117","<b>וכיוסף הצדיק. . בכתבי דחושבנא</b>: ראה ת\"א וישב לט, יא. לקמן קצה, א. מאמרי אדה\"א ויקרא ח\"א ע' רסה־ דברים ח\"ד ע' א'קסו־ נ\"ך ע' קצ ובהנסמן בהנ\"ל. שע\"ת ו, ב ובהערה 20."],["8937","118","<b>וידגו לרוב בקרב הארץ</b>: ויחי מח, טז. ראה זהר בלק קפז, ב ובביאוה\"ז לשם (קמט, א). מאמרי אדה\"א דברים ח\"ג ע' א'כד. וש\"נ."],["8938","119","<b>מעילה לעלול</b>: נסמן לעיל קמג, ד."]]],[2300540285,"<span data-k=\"pg\">רסו</span> ּ<b>(ג)</b> והנה להבין כל [ה]ענינים הנ\"ל, י\"ל הקדמה א' כ[ו]ללת לכללות [כל] סדר ההשתל' מראש לסוף, שא\"א להיות כל ההשתלשלו' עו\"ע בפרט ובכלל אם לא ע\"י ג' בחי' ומדרגות, שהן שנים שהן ד', והוא שנק' יש מאין<sup data-n=\"8939\">120</sup> ואין ויש<sup data-n=\"8940\">121</sup>, יש<sup data-n=\"8941\">122</sup> הראשון מן המשפיע שהוא בחי' יש האמיתי שהוא העילה ויש הב' הוא בחי' המקבל [שנק' עלול] בחי' יש מוגבל, ובחי' האין הוא הממוצע המחבר ומקשר ליש העליון ביש התחתון שנק' עו\"ע ובלעדי בחי' האין הזה א\"א שיומשך מיש דעילה ביש דעלול<sup data-n=\"8942\">123</sup> מצד ריחוק הערך ביניהם כו', וכציור אות א' יו\"ד בראשו ויו\"ד בסופו ומתחברים ע\"י בחי'<sup data-n=\"8943\">124</sup> [ה]קו האמצעי כו' או כקוצו של יו\"ד בראש היו\"ד וקוץ התחתון והיו\"ד באמצע שהוא החכ' שמאין תמצא (וכמשי\"ת). ובדרך פרט הן [הנה] ד' מדרגות שהן שתים בכלל א' מלמעלה למטה שנק' מיש לאין שזהו מיש [ה]אמיתי [ל]אין, והב' מאין ליש שזהו מאין ליש המוגבל [הנ\"ל], שנמצא יש באין הזה ב' מדרגות א' שהוא נמצא מיש האמיתי בבחי' אין לבד והב' אשר הוא אין ליש התחתון המוגבל, שהן ב' מדרגות בכלל אין ויש או יש ואין, רק שהוא בב' אופנים מלמעלה למטה מיש לאין ומלמטה למעלה לגבי המקבלי' מאין ליש (כמ\"ש במ\"א בענין אל דעות<sup data-n=\"8944\">125</sup> ב' דעות ד\"ע וד\"ת כמשי\"ת וד\"ל).\n<b>והנה</b> בחי' האמצעי מכ\"ז הוא בחי' ג' מדרגות דיש ואין ויש רק שאין זה נחלק לב'<sup data-n=\"8945\">126</sup> כו', וביאור הענין הזה הנה ידוע שיש לזה כמה משלים [ב]כמה ענינים שנראה לעין כל אשר יאמר עליו כי הוא זה שלא ימלט מג' אלה הנ\"ל, והמשל הפשוט יותר בענין הזה הוא מענין נביעת המעיינו' מן התהום אשר מתחת לארץ והמעיינות נובעים בארץ בנחלים רבים, שהמעיינות שנובעים מן התהום הן יוצאי' ונמשכי' [הם] בבחי' [ה]העלם ו[ה]הסתר וצמצום בגידי הארץ דארעא חלחולי מחלחלא<sup data-n=\"8946\">127</sup> כו', ונק' בחי' אין שלא נודע במציאות והתהום הוא בבחי' יש ומקור האמיתי, וא\"כ ה\"ז המשכה מיש לאין שהוא מן התהום [ש]נק' יש האמיתי והנביעה ממנו הוא בבחי' אין דכלא חשיב לגבי עצמות [התהום] ואח\"כ הרי מן הנביעה של המעיינות הללו נמשכים בנהרות ונחלים רבים שהנחלים<sup data-n=\"8947\">128</sup> שהנהר הוא בבחי' התפשטות גדולה [ורחבה] מלא על כל גדותיה כו' הרי הנהר נק' בשם בחי' יש הב' הנ\"ל שהוא יש מוגבל [כי] אין לנהר ערך לתהום בחי' יש האמיתי שהוא בלתי מוגבל והנהר מקבל רק מנביעת המעיין",[["8939","120","<b>מאין</b>: ויז: ליתא."],["8940","121","<b>יש ואין ויש</b>: ראה גם ש\"א סב, ב. מאמרי אדה\"א ויקרא ח\"א כאן ע' רה. ע' קכה. המשך והחרים תרל\"א ע' לג ואילך. וככה תרל\"ז ע' קצ ואילך. ע' קצו ואילך. סה\"מ תרמ\"ד ע' רב ואילך. תרנ\"ג ע' קסו ואילך."],["8941","122","<b>ויש, יש</b>: תוקן ע\"פ: ויז. ובתו\"ח כאן: מיש."],["8942","123","<b>דעילה ביש דעלול</b>: תוקן ע\"פ: ויז. ובתו\"ח: מיש."],["8943","124","<b>בחי'</b>: ויז: ליתא."],["8944","125","<b>אל דעות</b>: שמואל-א ב, ג. ראה גם ש\"א סב, ב ובהנסמן במ\"מ לשם."],["8945","126","<b>שאין זה נחלק לב'</b>: נסמן לעיל פ' וארא נ, ד."],["8946","127","<b>דארעא חלחולי מחלחלא</b>: חגיגה כב, א."],["8947","128","<b>שהנחלים</b>: ויז: ליתא."]]],[2300540313,"טיפין טיפין מן בחי' ההעלם ו[ה]אין זה נק' מאין ליש כידוע וא\"כ הרי בחי' ההעלם והאין דמעיינות הוא [בחי'] הממוצע המחבר ומקשר לבחי' יש דתהום להתמשך<sup data-n=\"8948\">129</sup> בנהר שהוא יש המוגבל דמקבל, אבל בלעדי המעיינות שנמשכי' מן התהום בגידין מצומצמים בהעלם א\"א הי' שיומשך מן התהום לנהר כו' (כי א\"א להיות שיומשך מיש ליש כ\"א ע\"י בחי' אין המחברם וכן<sup data-n=\"8949\">130</sup> המעיינות כנ\"ל, ובחי' אין זה נחלק לב' מדרגות [ה]א' מעיינות שנשארו בבחי' העלם סתום לגמרי ונק' מעיינות תהום רבה שלא יומשכו בנחלים והיינו למעלה [מ]בחי' המעיין שנובע בגילוי מן ההעלם בנחלים ע\"פ הארץ שאינו רק בחי' אין של היש המוגבל וד\"ל) (וכמו רזין דאורייתא שנק' רזא דרזין<sup data-n=\"8950\">131</sup> שנשאר סוד סתום ונק' מעייינות תהום רבה שלא יתגלה רק בימוהמ\"ש <span data-k=\"pg\">534</span> ּ דכתי' ישכיל עבדי<sup data-n=\"8951\">132</sup> כו' ונק' חכם חרשים<sup data-n=\"8952\">133</sup>, ועכשיו אין נגלה רק ממעין החכ' שנמשך לבינה מאין ליש, (וזהו סוד הוי' דחכ' ליריאיו<sup data-n=\"8953\">134</sup> כמו בגה\"ע כו'<sup data-n=\"8954\">135</sup> ובת\"ר לחיי נח נפתחו<sup data-n=\"8955\">136</sup> מבועין דחכ' הסתו[מי'] כו' שזהו<sup data-n=\"8956\">137</sup> בחי' ד\"ע שמיש האמיתי לאין דחכ' הנעלמה ובעוה\"ב יהי' התגלות מיש האמיתי ליש ממש<sup data-n=\"8957\">138</sup> (כמשי\"ת), וזהו [כ]אות [ד]א' אאלפך חכ'<sup data-n=\"8958\">139</sup> ביו\"ד שעל גבה והוא\"ו [הוא] בחי' אין דחכ' שבמדות שנמשך לדבור מאין ליש ביו\"ד התחתון, וכן באות היו\"ד [מ]ח\"ע דקוצו של יו\"ד<sup data-n=\"8959\">140</sup> לקוץ התחתון להאיר בבינה בהשגה בגילוי שנק' יש מוגבל<sup data-n=\"8960\">141</sup>.\n<b>והנה</b> יש עוד משל בזה רוחני יותר והוא מה שאנו רואים שלא יוכל להיות התהוות יש מיש כ\"א יש מאין ואין זה מיש כו' שהוא בחי' הממוצע כנ\"ל, כמו הצמיחה [ד]צומח מכח הצומח שבארץ מרוחניות לגשמיות הרי מהות הכח הצומח שמצמיח כל צמח הוא מבחי' יש האמיתי מקור<sup data-n=\"8961\">142</sup> לכל צומח שיצמח בארץ תבואות או פירות האילן ועשבים וכה\"ג וגוף הצומח נק' יש מוגבל במהות ואיכות במישוש וראות, ואמנם כח [ה]רוחני שמצמיחו תמיד נעלם הוא מן הראות ואינ[ו] נתפס במישוש ונק' בחי' אין של היש זה דעשב או פרי זה, ובחי' אין רוחני זה נמשך מכח הצומח הכללי שהוא מקור הראשון בחי' יש האמיתי בלתי מוגבל ומתחלק לחלקי' כלל ([ו]נמצא יש באין זה שנמשך מכח הצומח הכללי<sup data-n=\"8962\">143</sup> ב' מדרגות א' מיש לאין והב' מאין ליש כנ\"ל במעינות תהום רבה<sup data-n=\"8963\">144</sup>, ודרך כלל הן ג' מדרגות לבד יש ואין ויש שא\"א שיומשך מכח הצומח עצמו לממשות דצומח ביש גמור בלתי ממוצע שהוא בחי' אין הרוחני שמצמיח צמיחה גשמי' מן הרוחני' [ד]כח הצומח ההיולי בעצם כו' וד\"ל.",[["8948","129","<b>להתמשך</b>: ו: ליתא."],["8949","130","<b>וכן</b>: ו: והן. יז: עם."],["8950","131","<b>רזא דרזין</b>: ראה זהר בראשית מא, א."],["8951","132","<b>ישכיל עבדי</b>: נסמן לעיל ה, ג."],["8952","133","<b>ונק' חכם חרשים</b>: ראה לעיל פ' שמות כג, א הערה 952."],["8953","134","<b>סוד הוי'. . ליריאיו</b>: תהלים כה, יד."],["8954","135","<b>כו'</b>: אוצ\"ל: כו')."],["8955","136","<b>ובת\"ר לחיי נח נפתחו</b>: ראה נח ז, יא. זהר וירא קיז, א. ראה גם בענין ת\"ר לחיי נח לקמן רא, א. מאמרי אדה\"א בראשית ע' יז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670189\" data-slug=\"torat-chaim\" data-id=\"2300670189\">תו\"ח נח סא, ב</a> ובהערה 21. שעה\"י קט, א ובהערה 13."],["8956","137","<b>שזהו</b>: תוקן ע\"פ: ויז. ובתו\"ח: שהי'."],["8957","138","<b>מיש האמיתי ליש ממש</b>: ראה לעיל קנט, ב. וש\"נ."],["8958","139","<b>אאלפך חכ'</b>: נסמן לעיל טו, ב."],["8959","140","<b>דקוצו של יו\"ד</b>: תוקן ע\"פ: ויז: ובתו\"ח: מקוצו."],["8960","141","<b>מוגבל</b>: אוצ\"ל: מוגבל)."],["8961","142","<b>מבחי'. . מקור</b>: ויז: בחי' מקור האמיתי."],["8962","143","<b>הכללי</b>: תוקן ע\"פ: ויז. ובתו\"ח: הא'."],["8963","144","<b>רבה</b>: ויז: ליתא."]]],[2300540338,"<b>והנה</b><sup data-n=\"8964\">145</sup> המשל האמיתי לכל זה יותר בדוגמא<sup data-n=\"8965\">146</sup> הוא הידוע במשל נפש האדם שמחי' לגוף ע\"י הדם דוקא כמ\"ש כי הדם הוא הנפש<sup data-n=\"8966\">147</sup> כו', שבודאי אור עצמו' הנפש שהוא בחי' יחידה (שכלולה מכל כחות הרוחנים שלה כמו כח הרצון והתענוג וכח השכל וכח המדות ומחדו\"מ<sup data-n=\"8967\">148</sup> כנ\"ל<sup data-n=\"8968\">149</sup> הוא אור פשוט מאד ומתלבש באברי הגוף ממש להחיותם ממש בחיות מוגבל<sup data-n=\"8969\">150</sup> בכל אבר לפי מזגו כו', והרי אין ערך כלל וכלל לחיות מורגש זה שבעין ואזן ויד ורגל אף בראי' ושמיעה [והילוך ותנועה הרוחני'] לגבי בחי' העצמיות הנפש שנק' יחידה שהוא עצ[ם ה]רוחני' של הנפש שהוא מקור היולי כללי ואי[נו] נתפס במורגש החיות בחיות האברים לא מיני' כו', וזהו בחי' יש האמיתי שבנפש עצמ[ה] שא\"א שיומשך להיות בבחי' יש בחיות גשמי בדם שבגוף ואברים אם לא ע\"י בחי' ממוצע דוקא והוא בחי' אין [ה]רוחני המחברם יחד כו', והיינו מה שנמשך [רק] הארה אחת פשוטה מעצמות הנפש להיות מקור חיים כללי' לכל הגוף מראשו לסופו כמו מן המוחין שבראש עד צפורן שברגל בשוה, וכח [ו]הארה זאת [ה]פשוטה היא שנק' אין דכלא חשיבא לגבי עצמיות אור הנפש ([כ]רוחני[ות] דכח הצומח שמל[ו]בש בגוף דבר הצומח שנחלק לב' מדרגות כנ\"ל) וזהו שנק' מיש לאין כנ\"ל שהוא למעלה הרבה מאין הב' שנק' אין של היש הב' המוגבל ונפרד כו', והוא מה שבחי' הארה הפשוטה הזאת שמאירה [ב]בחי' אין והעלם גדול (שהן העורקי' הרוחני' [ש]אין בהם דם כלל שמאיר בהם [מ]בחי' הצלם דנפש שזהו מיש לאין כנ\"ל) באה [להיות] במורגש האור והחיות להיות מזה המשכה מאין ליש כמו מה שבא בגילוי מן ההעלם השכל [דכח] בכלי המוחין דחו\"ב ומא[ו]ר הראי' [הרוחני'] בכלי העין וכה\"ג בכל האברים שהן במורגש ונראה וידוע שהוא חיותם, <span data-k=\"pg\">רסז</span> ּ וכמו כח התנועה שביד ורגל וכח ההרגשה שזהו בגידי ההרגשה ו[ה]תנועה שנמשך מדם הוא הנפש מרוחני' לגשמי' ממש והוא [ענין] אדם א' דם<sup data-n=\"8970\">151</sup> כמו מחכ' שנק' אין לבינה שנק' יש<sup data-n=\"8971\">152</sup> כידוע בענין הדפק שביד שהוא בחי' אחוריים דאבא<sup data-n=\"8972\">153</sup> כו', וכן מרוח החיצוני'<sup data-n=\"8973\">154</sup> שבלב בחלל היינו<sup data-n=\"8974\">155</sup> [ב]בחי' אין והעלם שמקבל מאין דחכ' שבמוח קר<sup data-n=\"8975\">156</sup> ולא<sup data-n=\"8976\">157</sup> להיות במורגש בחיות הדם באברים וזהו דפיקא דלבא וכך הוא בחו\"ב שבראש בכלל<sup data-n=\"8977\">158</sup> וד\"ל.\n<b>(ואמנם</b> הרי מובן מכ\"ז דבחי' הארה א' זאת הפשוטה שנק' אין של [ה]יש האמיתי (כמעיינות תהום הנ\"ל) ה[י]א עצמ[ה] שבאה להיות בחי' אין של היש המוגבל בכלים ואברים בדם הוא",[["8964","145","<b>והנה</b>: ד: נסמן כאן ס\"ג. ס\"ב נסמן לעיל על יד הערה 88."],["8965","146","<b>בדוגמא</b>: ויז: ברוחניות."],["8966","147","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["8967","148","<b>ומחדו\"מ כנ\"ל</b>: ויז: ומחשבה ודיבור כו'."],["8968","149","<b>כנ\"ל</b>: אוצ\"ל: כנ\"ל)."],["8969","150","<b>מוגבל</b>: שם: מורגש."],["8970","151","<b>אדם א' דם</b>: נסמן לעיל פ' וארא עב, ד."],["8971","152","<b>מחכ' שנק' אין לבינה שנק' יש</b>: ראה מאמרי אדה\"א בראשית ע' א ואילך. וש\"נ."],["8972","153","<b>הדפק. . אחוריים דאבא</b>: ראה טעה\"מ — להאריז\"ל — פ' וירא."],["8973","154","<b>החיצוני'</b>: ויז: החיים."],["8974","155","<b>היינו</b>: שם: הימיני."],["8975","156","<b>דחכ' שבמוח קר ולח</b>: נסמן לעיל פ' שמות כז, ג."],["8976","157","<b>ולא</b>: ויז: ולח."],["8977","158","<b>בכלל</b>: שם: עצמו כו'."]]],[2300540361,"הנפש כו', וכמו שאנו רואים בחוש שבחי' הארה זאת כלולה מב' מדרגות דבחי' אין הנ\"ל בחי' אין הנעלם ואין המורגש, והוא מה שמרגיש האדם א\"ע [במורגש] בכללותו מראשו לרגלו כא'<sup data-n=\"8978\">159</sup> בשוה ומשוה מקור הרוחני' דמוחין עד<sup data-n=\"8979\">160</sup> צפרני הרגל שזהו בחי' אין ה[נ]עלם שבא מיש העצמי דיחידה שבנפש, [ועכ\"ז] הרי יש בה עצמה בחי' הרגשה עכ\"פ מרוחני' לגשמי' מאין ליש במורגש בפרטי כל התחלקות של חיות האברים שבמוח ולב ואברים כו' וד\"ל (וכמו\"כ הוא מלמטה למעלה בבחי' או\"ח, כמו שמבואר למעלה [ב]ב' משלים הנ\"ל בצומח וחי דאדם מלמעלה למטה בבחי' או\"י, כמו כח הצומח להצמיח מאין ליש ובחי' המשכה מרוחני' החיות לגשמי', כך הוא בהיפך כמו בזריעת החטה בארץ שא\"א שיצמיח ממנה מאין ליש מכח הצומח אם לא שתרקב<sup data-n=\"8980\">161</sup> הישות שלה והי' לבחי' אין שנק' ביטול היש לאין ואח\"כ נמשך מאין ליש בב' מדרגות דאין ויש כנ\"ל, וכן בנפש האדם בהילוך [וסיבוב] הדם מלמטה למעלה ע\"י ביטול וכליון שעולה בחלל השמאלי מיש לאין ונכלל ברוח החיים שבחלל הימיני כנ\"ל עי\"ז חוזר ונמשך המשכה חדשה מאין דחכ' שבמוח ללב<sup data-n=\"8981\">162</sup> ומלב לאברים שזהו ב' דפיקות<sup data-n=\"8982\">163</sup> דרו\"ש שבלב בכלל (כמ\"ש במ\"א).\n<b>וכך</b> הוא גם<sup data-n=\"8983\">164</sup> בשפע הרוחני' דח\"ע<sup data-n=\"8984\">165</sup> בחי' הנשמ' וחי'<sup data-n=\"8985\">166</sup> הגוף כמו בפרנסה שיש בזה ב' אופני' באו\"י ואו\"ח הנ\"ל א' [מ]העלם עצמות הנפש<sup data-n=\"8986\">167</sup> מיש לאין ומאין ליש בירידה מלמעלה למטה במוח ולב וכן בברכה גשמי' בפרנסה מהעלם דח\"ע בחי' מקור [ה]ברכות שנמשך מיש לאין ומאין ליש עד שנעשה ברכה ושפע [ב]הצלחה גשמי' בדרך כללי<sup data-n=\"8987\">168</sup> הטבע, ובהיפוך ג\"כ באו\"ח מלמטה למעלה בביטול היש לאין ברקבון הזריעה בארץ בביטול היש לאין ובהילוך הדמים מלמטה למעלה כו', כך הוא פיזור הנפש במו\"מ לומר נואש בנפשו ממש ואח\"כ באמצעו' ביטול היש לאין האלקי חוזר ונמשך מיש לאין [מ]רוחני' דחסד לגשמי[ות] הברכה כו' וד\"ל (וכך הוא בכל בחי' השתלשלו' השפע מעו\"ע שזהו מיש לאין תחלה ואח\"כ מאין ליש ע\"ד הנ\"ל במשלים דצח\"מ כמו גם בכח השכל ששופע [מ]מקור החכ' מאין ליש בהשגה חדשה [בב'] בחי' אין הנ\"ל דוקא כמו הברקת אור השכל החדש מאין דחכ' ליש דבינה וזהו אין של היש, אבל בחי' אין זה דחכ' בבינה כל\"ח<sup data-n=\"8988\">169</sup> לגבי עצם [כח] המשכיל ההיולי כמו שהוא טרם ש[מ]שפיע שכל חדש מן ההעלם לגילוי שזהו מיש האמיתי לאין כו', וכן מלמטה למעלה ביגיעת המוח מאד עד שנתבטל היש [ד]השגה הראשונה לגמרי [ל]אין <span data-k=\"pg\">536</span> ּ דחכ' כמו שה[י'] קודם שהאיר מן ההעלם לגילוי כמו השתיקה בוקע בקרומ[א כו'] מלמטה למעלה ועי\"ז נמשך ממקור החכ' שכל חדש לגמרי מאין",[["8978","159","<b>שמרגיש האדם א\"ע. . כא'</b>: ראה גם לעיל קסו, ג. וש\"נ."],["8979","160","<b>עד</b>: שם: עם."],["8980","161","<b>החטה. . שיצמיח. . שתרקב</b>: נסמן לעיל ב, ג."],["8981","162","<b>שבמוח ללב</b>: ויז: ברוח שבלב."],["8982","163","<b>ב' דפיקות</b>: ראה גם לעיל קד, סע\"ב ואילך. לקמן פ' תצוה שמח, ב."],["8983","164","<b>גם</b>: ויז: ליתא."],["8984","165","<b>דח\"ע</b>: שם: דחסד עליון."],["8985","166","<b>בחי'. . וחי'</b>: שם: בחיי. . וחיי."],["8986","167","<b>הנפש</b>: שם: הנשמה."],["8987","168","<b>כללי</b>: שם: כלי."],["8988","169","<b>כל\"ח</b>: שם: הוא כלא חשיב."]]],[2300540382,"ליש (וכך הוא בכל ההשתלשלו' דעו\"ע בכל פרטי הברואי' העליונים וכמ\"ש וצבא השמים<sup data-n=\"8989\">170</sup> כו' שהחומר [ד]גלגל בטל מיש לאין ונמשך הצורה בחומר מחדש מאין ליש כמו ברו\"ש דלב האדם וכך הוא עד רום המעלות וד\"ל, וכן [ב]בחי' רו\"ש הכללי בכללות החיות האלקי בכללות העולמות שמחי' מאין ליש בע\"ג כמו ואתה מחי' את כולם<sup data-n=\"8990\">171</sup> שנק' ממכ\"ע בחיות הנפש בגוף ממש [ש]בודאי יש [בזה] ב' בחי' אין הנ\"ל [ו]ב' בחי' יש הנ\"ל דבחי' החיות האלקי בתוך כ\"ע כמו הנפש שבדם שזהו מאין ליש מוגבל כמלאכי' שנק' אברים דשכינתא<sup data-n=\"8991\">172</sup> כו' כמו עיני ה'<sup data-n=\"8992\">173</sup> כו' וזהו אדם א' דם, ואמנם בחי' אין זה הבא בגילוי מאין ליש אע\"פ שהוא מקור לחיות העולמות אין לו ערך לבחי' האין הנעלם שזהו כמו שנמשך מיש האמיתי לאין כדמיון הארה א' הפשוטה שמתפשטת בגוף בראש ורגל בשוה, וז\"ש את השמים ואת הארץ אני מלא<sup data-n=\"8993\">174</sup> בהשוואה א' ממש בלי חילוק מדרגות כלל מראש לסוף כו' [וד\"ל].\n<b>ושרש</b><sup data-n=\"8994\">175</sup> הענין בכלל יובן ממע\"ב שכולם בחכ' עשית<sup data-n=\"8995\">176</sup> כמ\"ש בראשית ברא אלקי'<sup data-n=\"8996\">177</sup> בחו\"ב<sup data-n=\"8997\">178</sup> שהחכ' מאין תמצא היינו מאין דכתר ליש שזהו מה שכולם בחכ' עשית בבינה<sup data-n=\"8998\">179</sup> שהוא שם אלקי' [עילאה] דמע\"ב כמ\"ש בזהר דבראשית ברא אלקי' דאבא אמר לאימא<sup data-n=\"8999\">180</sup> שזהו מאין ליש דבינה כו', ונמצא החכ' שנק' אין הוא בחי' הממוצע הנ\"ל בין עצמות אוא\"ס לעולמות הנבראים ביש מוגבל ממש כו', והיינו שיש בבחי' אין [זה] דחכ' ב' מדרגות א' בהעלם דאין כמו שהוא בכתר שנמשך מיש האמיתי לאין שלמעלה מהיות מקור לבינה [ב]מע\"ב, והב' [כ]שנק' אין ליש דבינה במע\"ב כנ\"ל (והוא ההפרש שבין חול לשבת כידוע, וע\"י בחי' ביטול היש לאין במל' דאצי' מכל מע\"ב בכלל ובפרט בכל נבראים כנ\"ל חוזר ונמשך אור חדש בשבת מאין הנעלם דחכ' כנ\"ל (אך זהו עכשיו דוקא שהשתלשלו' הוא ע\"י ממוצע [ד]חכ' מאין כו' אבל לע\"ל יהי' בבחי' יש [מיש] האמיתי כמו בעוה\"ב (כמשי\"ת) וד\"ל).\n(ד) <b>והנה</b> כל המבואר למעלה בענין ג' בחי' דיש ואין ויש שהוא בכל ההשתלשלו' דעו\"ע בכלל ו[ב]פרט כנ\"ל עיקר המכוון בזה הוא שע\"י בחי' אין זה הממוצע (כאשר הוא נחלק לב' בחי' אין דוקא [כנ\"ל]) בין [ה]עילה לעלול הוא שמפריד ביניהם ויכול להיות בחי' התחלקות העלול מן העילה במ[ה]ות יש ודבר בפ\"ע, אבל אם לא בחי' האין הזה הממוצע הנ\"ל לא הי' אפשר להיות התחלקות מציא[ו]ת העלול במהות יש מוגבל בפ\"ע כלל כי הרי הי' דבוק תמיד<sup data-n=\"9000\">181</sup> ונכלל בעילתו כטבע",[["8989","170","<b>וכמ\"ש </b>[ויז: כמו]<b> וצבא השמים</b>: נחמי' ט, ו."],["8990","171","<b>ואתה מחי' את כולם</b>: נחמי' שם."],["8991","172","<b>כמלאכי' שנק' אברים דשכינתא</b>: ראה פרדס (שער ההיכלות) שכ\"ד, פי\"א."],["8992","173","<b>כמלאכי' שנק'. . עיני ה'</b>: עקב יא, יב. ראה ת\"ז ת\"ע (קלא, א)."],["8993","174","<b>את השמים. . אני מלא</b>: ירמי' כג, כד. ראה גם לעיל קסו, ג ובהערות 140-1."],["8994","175","<b>ושרש</b>: ד: נסמן כאן ס\"ד. ויותר לא צויין. ס\"ג נסמן לעיל על יד הערה 145."],["8995","176","<b>שכולם בחכ' עשית</b>: תהלים קד, כד."],["8996","177","<b>בראשית ברא אלקי' בחוכמתא</b>: בראשית א, א. וראה תרגום ירושלמי שם."],["8997","178","<b>בחו\"ב</b>: ויז: בחוכמתא."],["8998","179","<b>שכולם בחכ' עשית בבינה</b>: זהר תזריע מג, א."],["8999","180","<b>דאבא אמר לאימא</b>: נסמן לעיל פ' שמות יח, ד."],["9000","181","<b>תמיד</b>: ויז: ליתא."]]],[2300540402,"כל עלול ש[ב]עודנו במקורו בעילה לא ניכר במציאות יש [ודבר מה] כלל וכלל כידוע וד\"ל. וביאור ענין זה הנה יובן מכל המשלים הנ\"ל בענין ב' בחי' אין שמן העילה לעלול שנק' יש העליון ויש התחתון שא\"א להיות התהוות היש התחתון כ\"א באמצעות ב' בחי' האין הממוצע כנ\"ל, והטעם [הוא] בדרך קצרה לכל הנ\"ל [מפני] שא\"א להיות התהוות היש מיש כ\"א ע\"י ממוצע דבחי' [אין ב]ב' אופנים הנ\"ל, והעיקר הוא לפי שלא יוכל להיות התהוות היש במהות נבדל הערך לגמרי רק ע\"י ב' אופנים דאין הנ\"ל, הא' בחי' האין הא' שהוא בא מיש האמיתי שזהו מיש לאין <span data-k=\"pg\">רסח</span> ּ הרי פי' אין זה היינו שהוא כאין ואפס וכאילו איננו במציאות וכלא ממש חשיב לגבי העצם דיש האמיתי כו' שזהו בבחי' הביטול והצמצום בתכלית דהארה וזיו שבטל במאור ולא ניכר במציאות כלל, ולא שיהי' בחי' אין זה בחי' מהות ומציאות דבר מה להיות מקור לשלמטה ממנו כלל, להיותו קרוב מאד לגבי מקור העצמי אז יוכל שיתבטל<sup data-n=\"9001\">182</sup> [כ]אין ממש ולא יוכל להיות בחי' משפיע אף בהעלם עדיין כו'. אך בחי' אין [זה] עצמ[ו] כשנעשה בריחוק מקום מעט מן המקור העצמי אז יוכל להיות דוקא מקור משפיע למטה והוא לבחי' היש הב' המוגבל במציאות ולהיות נק' אין של היש. ופי' אין זה לא שכאין וכל\"ח, אלא אדרבה [הרי] הוא מקור ומשפיע עכ\"פ, רק מפני שהוא בבחי' ההעלם איננו נראה ומושג למטה במקבל כלל כי השפעתו הוא בבחי' ההעלם (כמעיינות שנמשכי' בהעלם לנחלים כמשי\"ת) נק' בשם אין ע\"ש בחי' ההעלם שאינו ניכר במציאות למטה, אבל בחי' העלם הזה הרי הוא בחי' שרש ומקור למה שיכול להיות ממנו דוקא התהוות בחי' יש גמור כנ\"ל וד\"ל. ולפ\"ז הרי מובן דאע\"פ דב' הפי' דאין הזה הממוצע בכלל הן כמו ב' הפכים, דאין הא' כאלו איננו וכל\"ח ואין הב' הוא שרש ומקור הנעלם עכ\"פ להיות יש כו', מ\"מ ב' בחי' אין הללו עולין לכוונה א' כי בחי' אין זה עצמו שה[י'] בבחי' ביטול המציאו' לגמרי הוא עצמו שנעשה בחי' מקור ושרש ליש המוגבל כו'. והענין הוא לפי שכל עיקר בחי' אין זה הנק' ממוצע בין יש העליון לתחתון אינו רק כדי שיוכל להיות התהוות יש מוגבל בשינוי המהות בפ\"ע מיש העליון העצמי, והיינו ע\"י שיתרחק התהוות מציאות היש שנק' עלול מן העילה כי בקירוב לעילה בטל הוא ונכלל בביטול גמור בעילה ולא יוכל להיות מציאות היש בפ\"ע כלל כנ\"ל. ויש בסיבת בחי' הריחוק הזה ב' דברים, הא' שתחלה יהי' הארה דבחי' האין הא' שזהו מיש לאין דכל\"ח שזהו מצד שהוא קרוב עדיין להעילה הרי הוא בטל במציאות כאלו אינו ממש כנ\"ל, והב' כאשר הארה זו עצמו שהיא בבחי' ביטול יהי' בריחוק מקום אח\"כ ויהי' נעשה בחי' מקור ושרש להיות בבחי' אין של היש שאז יוכל להיות מציאות יש ממש, אבל אם לא ב' סיבות אלה שהוא מיש לאין בתחלה ואח\"כ מאין בהעלם ליש א\"א שיהי' מהות יש גמור במוגבל מיש אמיתי כלל כנ\"ל וד\"ל.",[["9001","182","<b>אז יוכל שיתבטל</b>: שם: שמתבטל."]]],[2300540422,"(ה) <b>ויובן</b> דבר זה בביאור יותר ממה שאנו רואים [כן] בכל השפעה מעילה לעלול כמו השפעת שכל שמשפיע הרב לתלמידו שכדי שיוכל להיות התהוות השכל מקבלת<sup data-n=\"9002\">183</sup> התלמיד בכלי הגבלת שכלו המצומצם מהרב ששכלו רב ועצום ממש<sup data-n=\"9003\">184</sup> הרבה, א\"א כ\"א ע\"י ב' בחי' אין שביניהם ש[מ]פרידן ויכול להיות השפע לתלמיד בריחוק מקום כו' כנ\"ל, דהנה ודאי שכל וחכ' הרב גם באותו שכל קטן שרוצה להשפיע עמוק ורחב הוא מאד כפי ערך רוחב עצם חכמתו וע\"כ כשרוצה להשפיע צריך שיניח כל עצמות שכלו בזה ולא יאיר רק כמו נקודה א' ממנו והי' <span data-k=\"pg\">538</span> ּ צריך<sup data-n=\"9004\">185</sup> להביא אותו בשפע זאת דכלא ממש חשיב [מ]אחר שאינו רק בחי' הארה אחת מעצם אור [ה]שכל כמו שהוא אצלו ממש ברוחב חכמתו שזהו נק' מיש לאין כנ\"ל, [ו]אח\"כ בחי' הארה זו להיותה בקירוב אצלו שהוא בבחי' ביטול באין ממש נגדו כו'<sup data-n=\"9005\">186</sup> נמשך בריחוק מקום מעט והוא שמנקוד' זאת יומשך בהעלם להיות שפע שכל המושג לתלמיד ששומע ומבין השכל לפי כלי צמצום שכלו ג\"כ שזהו נק' מאין ליש ממש כנ\"ל. ונמצא שאם לא בחי' צמצום דנקוד' [זו] שנשאר מעצם השכל דמשפיע דכאין ממש הוא לא הי' יכול להיות שפע למקבל לפי ערכו כלל, וגם עוד זאת הוצרך שיהי' נמשך נקודה זו בריחוק מקום (שהוא מה שמשפיע לו<sup data-n=\"9006\">187</sup> עוד אותו אור השכל ולהורידו בענין ולשון אופן המצומצם בערך למטה שלא כמו שהוא בקירוב באותו ענין וערך הבנתו של המשפיע בעצמו (בל\"א אראפ גילאזין [או] נידריק אראפ[לייגין] כו') [מ]למעלה רק כ[ד]י הצריך לערך של המקבל שאז אינו בבחי' ביטול באין אדרבה נעשה בחי' מקור משפיע בהעלם לפי אופן השגת המקבל וא\"ל לא הי' יכול להיות צמצום השפע לפ\"ע המקבל שזהו מאין ליש מוגבל כנ\"ל, וב' צמצומי אין זה הממוצע הרי כא' באים [ממש].\n<b>ועוד</b> יובן זה גם בתלמיד עצמו כשמקבל השפעת השכל מרבו שיש בו ב' בחי' אין הנ\"ל, א' בחי' אין בביטול המציאות [ממש], והוא בשעה שעומד ושומע השכל מהרב שאור השכל ההוא כמו שיוצא מפורש ומבואר מפי הרב הוא עמוק ממנו ונעשה אז שכל התלמיד בבחי' ביטול וכיווץ גדול כאלו אינו במציאות ומהות בפ\"ע כלל, מצד עוצם ביטולו בתכלית לגבי השכל של הרב שגדול ועצום<sup data-n=\"9007\">188</sup> ממנו הרבה מאד נעלה ממנו, ואע\"פ שמשיגו בשמיעת אותו השכל ו[ה]סברא שמקבל על בורי', אבל מצד קירובו אל המשפיע נעשה כל השגתו בשכל זה כאין וכלא ממש להיותו בקירוב גמור להמשפיע דאז איננו קולט רק [בחי'] תמצית [ו]עומק המושג שלא יוכל להביא אף לעצמו בהשגה גמורה, וכ\"ש שלא יוכל להשפיע לזולתו משום [ד]איידי דטריד למבלע ולקבל [ל]עצמו תמצית ועומק הנעלם שבשכל זה לא פליט<sup data-n=\"9008\">189</sup> לזולתו, שזהו מצד ביטול העלול בעילתו א\"א שיהי' במציאת יש ודבר מה כלל וזהו בחי' אין שאינו במציאות כלל, אך בריחוק מקום כאשר נתרחק התלמיד מן הרב ויתחיל לעיין",[["9002","183","<b>השכל מקבלת</b>: שם: השגה וקבלת."],["9003","184","<b>ממש</b>: שם: ממנו."],["9004","185","<b>והי' צריך</b>: שם: הנצרך (רק)."],["9005","186","<b>כו'</b>: שם כנ\"ל."],["9006","187","<b>שמשפיע לו</b>: שם: שישפיל."],["9007","188","<b>ועצום</b>: ויז: ועמוק."],["9008","189","<b>[ד]איידי דטריד למבלע. . לא פליט</b>: נסמן לעיל פ' שמות מז, ג."]]],[2300540442,"ולהשיג במה ששמע בהסבר וטעם הדברים בפרטיות אז יוכל להיות בחי' משפיע גם לזולתו, כי אז אינו בביטול המציאות ויוכל להיות שכלו בחי' שרש ומקור אל המשפיע<sup data-n=\"9009\">190</sup> שמקבל זולתו שהשפע[ה] זו שמקבל ממנו נק' יש גמור, ומה שהתלמיד יוכל להשפיע נק' אין [ב]העלם ושרש של שפע זו (כנ\"ל בצמצום [שכל] של הרב לעצמו שנעשה מקור ושרש לקבלת התלמיד כנ\"ל).\n<b>וכך</b> יובן ג\"כ בכל המשלים הנ\"ל כמו במעיינות תהום שזהו שמן התהום נמשכו המעיינות באין ממש<sup data-n=\"9010\">191</sup> אז מצד קירובם אל התהום וא[מ]נם בריחוק מקום הרי נעשה מעיין הזה מקור ל[ה]נהר וא\"ל הי' ביטול המעיינות הסתומים בגידי הארץ ואח\"כ ריחוק מקום של <span data-k=\"pg\">רסט</span> ּ מעיין הנובע לא הי' אפשר להיות שיומשך נהר מן התהום עצמו כו'. וכך הוא במשל [ה]רוחני דצומח וחי בהם<sup data-n=\"9011\">*192</sup> שמן כח הצומח בעצם נמשך רק בחי' גילוי הארה בעלמא להצמיח צמח גשמי וכל\"ח, ואח\"כ בריחוק מקום [מ]תלבש להצמיח צמיחה גשמי' (וכמו גילוי התנועה <sup data-n=\"9012\">192</sup>בעצם שכל\"ח ואח\"כ מתרחק כמו בזריקה או פעולה במלאכה גשמי' שנתפשט מכח זה), וכך רוחני' וגשמי' החיות דאדם כנ\"ל<sup data-n=\"9013\">193</sup> שתחלה הי' רק גילוי הארה אחת בעלמא מצד עצמו' הנפש בביטול המציאות כו' ואח\"כ נעשה בחי' רוחני' החיות בגשמיות שהוא הדם באברים כו' שנק' אין של היש ממש (וכך יובן גם בנמשל למעלה ברוחני' וגשמי' דעו\"ע במל' דאצי' בבי\"ע שמחי' כל העולמות מאין ליש [דוקא], ואמנם תחלה הוא מיש לאין [ב]ביטול המציאות דכל\"ח ואח\"כ נתרחק להיות בבחי' אין ליש ממש, וכמו שהחכ' מאין ליש תמצא שתחלה הי' כאין ממש דאפי' אור צח<sup data-n=\"9014\">194</sup> כו' מצד קירוב העלול בעילה כנ\"ל, ואח\"כ בריחוק מקום דוקא הוא שנעשה החכ' מאין ליש דבינה בהשגה ממש [כ]ענין אדם א' ד\"ם כנ\"ל באריכות).\n<b>והנה</b> אחר כל הנ\"ל יובן ג\"כ ענין בחי' חשך ואור שזהו בחי' העלם וגילוי בכלל [ש]זהו כללות ענין קי\"ס שמבחי' ההעלם דים עצמו נעשה בחי' יבשה בגילוי כנ\"ל שהוא בחי' התהוות מאין [ליש] מבחי' <sup data-n=\"9015\">195</sup>הנ\"ל כמו שה[י'] הכל מן הארץ כמ\"ש תוצא הארץ כו'. [ד]הנה כתי' והארץ היתה תהו<sup data-n=\"9016\">196</sup> ובהו וחשך כו' ואח\"כ א' ויאמר אלקי' יהי אור<sup data-n=\"9017\">197</sup> דהאור נברא מאין ליש וקדם לו החשך תחלה שהוא בחי' ההעלם <sup data-n=\"9018\">198</sup>שהוא קדם לגילוי כו' [ו]כמארז\"ל כברייתו ש\"ע ברישא חשוכא<sup data-n=\"9019\">199</sup> [והדר",[["9009","190","<b>המשפיע</b>: יז: השפע."],["9010","191","<b>באין ממש</b>: ויז: כאין יחשב."],["9011","*192","<b>בהם</b>: ויז: ליתא."],["9012","192","<b>בעצם</b>: תוקן ע\"פ: ויז: ובתו\"ח: מכח החי בעצם)."],["9013","193","<b>דאדם כנ\"ל</b>: תוקן ע\"פ: ויז. ובתו\"ח דאע\"פ."],["9014","194","<b>דאפי' אור צח</b>: נסמן לעיל פ' שמות יב, ב."],["9015","195","<b>הנ\"ל</b>: ויז: המל'."],["9016","196","<b>והארץ היתה תהו</b>: בראשית א, ב."],["9017","197","<b>ויאמר אלקי' יהי אור</b>: בראשית א, ג."],["9018","198","<b>שהוא</b>: ויז: שחשך."],["9019","199","<b>כברייתו ש\"ע ברישא חשוכא</b>: שבת עז, ב (כגי' רש\"י)."]]],[2300540462,"נהורא] כו'. וביאור הענין בפרט יובן עפ\"י כל הנ\"ל בב' מדרגות דאין הנ\"ל, דבחי' אין הא' הוא כמו שנמשך מיש לאין בבחי' ביטול כאין וכלא כו' זהו בחי' החשך וההעלם שבלתי יוכל לבא בגילוי כלל וכמו ישת חשך סתרו<sup data-n=\"9020\">200</sup> ממש ונק' סדכ\"ס דלמחתב\"כ (וכמו בחי' ההתנשאו' שמצד עצמו שנק' מלך הקדוש שעולה ונכלל בעצמו' א\"ס והיראה שנמשך מזה נק' יראת הרוממות שהוא אוצר של י\"ש<sup data-n=\"9021\">201</sup> העליון הגנוז ונעלם לגמרי, והוא בחי' יראה עילאה דאין הא' דחכ'<sup data-n=\"9022\">202</sup> חכ' שבכתר עצמו שנק' ירא בושת<sup data-n=\"9023\">203</sup> בביטול המציאות לגמרי [ב]בחי' מ\"ה וביטול העצמי דמשה<sup data-n=\"9024\">204</sup> כו', וז\"ש דאפי' אור צח ומצוחצח (שהוא אור דח\"ס שנעשה מקור לחכ' שמאין תמצא ליש כו') אוכם הוא לגבי עה\"ע מצד קירובו בעילה כנ\"ל, ואוכם זה נק' חשך סתרו ונק' ערפל אשר שם [ה]אלקי'<sup data-n=\"9025\">205</sup> בבחי' צמצום ואין ממש (כמו בחי' רזא דרזין כנ\"ל שנק' [מעין] סתום וחתום לגמרי כו'), אך [ב]בחי' ריחוק מקום מעה\"ע עצמו אז הוא שיוכל להיות בחי' ההעלם דחכ' (שנק' שכל הנעלם מכל רעיון<sup data-n=\"9026\">206</sup> שכל מוצנע<sup data-n=\"9027\">*207</sup> ומופלא<sup data-n=\"9028\">207</sup> כו') בבחי' גילוי גמור<sup data-n=\"9029\">208</sup> והוא התהוות מציא[ו]ת [ה]אור דחכ' מאין שזהו [ב]בחי' אין הב' הנ\"ל אין של היש כו', וז\"ש יהי אור אחר החשך וההעלם (והוא מ\"ש הן יראת ה' היא חכ'<sup data-n=\"9030\">209</sup> בגילוי הנראה<sup data-n=\"9031\">210</sup> מן ההעלם דירא[ת] בושת הנ\"ל והיא יראה עילאה בחי' ביטול לגמרי<sup data-n=\"9032\">211</sup>, ולמעלה הוא מל' דא\"ס שמ[ת]צמצם להיות מלך על כל ההשתל' ממכ\"ע<sup data-n=\"9033\">212</sup> כו', <span data-k=\"pg\">540</span> ּ וכן יובן [ב]מל' דאצי' בבי\"ע שהיא הממוצע המחבר לאצי' בבי\"ע (כמו מן התהום לנהר מיש האמיתי ליש מוגבל כו') שזהו ע\"י ב' בחי' אין הנ\"ל<sup data-n=\"9034\">213</sup> דוקא דהיינו [אין] הא' כמו שהמל' בבחי' קירוב באצי' ([כ]ענין כתר מל' שעז\"נ לעולם [ה'] דברך נצב בשמים<sup data-n=\"9035\">214</sup> ברזא דרזא<sup data-n=\"9036\">215</sup> [כ]כח הבל הדבור שאחוז וקשור בהבל הלב שבטל ונכלל שם כאלו אינו במציאות שנק' חשך והעלם<sup data-n=\"9037\">216</sup> שבלתי יכול להיות מקור ושרש לעולמות כלל, כי המל' בטל ונכלל באצי' (כביטול הדבור בשכל ומדות) כו' משום דע\"ס דאצי' איהו וחיוהי וגרמוהי חד<sup data-n=\"9038\">217</sup> בבחי' א\"ס, וגם מדת ההתנשאו' דמל' כלול שם וכאין ממש חשיב שם וכמשל התלמיד הנ\"ל בקירובו למשפיע דטר[י]ד ל[מ]בלע ואיננו במציאות כלל לא פליט כו' (וכמו לבנה בקירובה לשמש שאין בה אור כלל כי מתבטלת [ב]פני השמש וכמ\"ש במ\"א כו'<sup data-n=\"9039\">218</sup> ) (כמשי\"ת), שמחמת ביטול והתכללות דמל' [ב]אצי' עצמו א\"א להיות בחי' מקור לנבראים ואיידי דטריד <sup data-n=\"9040\">219</sup>כלל לא פליט כו' להיות ממדה זו בחי' [ד]התנשאות על בע\"ג כו' והוא בחי' אין הא' שנק' חשך והעלם [לגמרי ו]כברייתו ש\"ע ברישא",[["9020","200","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["9021","201","<b>אוצר של י\"ש</b>: ראה לקמן רכד, ד ואילך. וש\"נ."],["9022","202","<b>דחכ'</b>: ויז: דח\"ס."],["9023","203","<b>ירא בושת</b>: נסמן לעיל יב, ב."],["9024","204","<b>וביטול העצמי דמשה</b>: ראה הנסמן לעיל פ' שמות מג, א הערה 6."],["9025","205","<b>ערפל אשר שם [ה]אלקי'</b>: נסמן להלן הערה 381."],["9026","206","<b>שכל הנעלם מכל רעיון</b>: נסמן לעיל פ' שמות מז, ג."],["9027","*207","<b>שכל מוצנע</b>: ראה גם לקמן רכד, א ובהנסמן לשם."],["9028","207","<b>שכל. . ומופלא</b>: נסמן לעיל פ' שמות לג, א."],["9029","208","<b>גמור</b>: ויז: אור."],["9030","209","<b>הן יראת ה' היא חכ'</b>: איוב כח, כח. ראה גם לעיל קב, ד."],["9031","210","<b>הנראה</b>: שם: היראה."],["9032","211","<b>לגמרי</b>: אוצ\"ל: לגמרי)."],["9033","212","<b>ממכ\"ע</b>: ויז: מלכות כ\"ע."],["9034","213","<b>הנ\"ל</b>: שם: ליתא."],["9035","214","<b>לעולם [ה'] דברך נצב בשמים</b>: תהלים קיט, פט. ראה מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["9036","215","<b>ברזא דרזא</b>: ויז: בחז\"א דז\"א."],["9037","216","<b>והעלם</b>: שם: סתרו וסתר עליון."],["9038","217","<b>איהו וחיוהי וגרמוהי חד</b>: נסמן לעיל פ' בא צו, ד."],["9039","218","<b>וכמ\"ש במ\"א כו'</b>: ויז: וכשרגא בטיהרא."],["9040","219","<b>כלל</b>: שם: כו'."]]],[2300540481,"חשוכא כו' וכמ\"ש והארץ תהו ובהו<sup data-n=\"9041\">220</sup> כו', ואח\"כ נמשך בצמצום והוא בריחוק מקום מאצי' עצמו והוא ע\"י בחי' הפרסא המפסיק בין אצי' לבריאה<sup data-n=\"9042\">221</sup> [וכמשי\"ת], אז יורד בחי' המל' להיות מקור ושרש לעולמות בבחי' אין הב' שהוא אין של היש בהעלם עדיין והוא מה שמל' דאצי' נעשה בחי' כתר וע\"י לנבראים כנ\"ל<sup data-n=\"9043\">222</sup> שזהו כל התהוות יש מאין בעלמא דאתגלייא בחכ' שבדבור שמאין תמצא לבחי' יש להיות כולם בחכ' עשית בבחי' יש גמור כנ\"ל וד\"ל. ונמצא שאם לא ע\"י [ב'] בחי' אין אלה אין הנעלם ואין הבא ליש ע\"י ריחוק מקום לא הי' אפשר להיות [ה]משכות [ה]בריא' בע\"ג מבחי' אור האצי' שהוא בלתי בע\"ג כו' וכמובן ממשל הב'<sup data-n=\"9044\">223</sup> הנ\"ל, וכך הוא ממש עד רום המעלות גם במל' דא\"ס שהוא הממוצע המחבר עצמו' אוא\"ס בקו\"ח כללי' המקור [ד]אבי\"ע וכמ\"ש אני ראשון ואני אחרון<sup data-n=\"9045\">224</sup> כידוע וכו' וד\"ל.\n(וא\"ו) <b>וזהו</b> תפול עליהם אימתה כו' דקאי לע\"ל כו' שיתגלה מבחי' ההעלם דמל' דא\"ס שלפני הצמצום הראשון שזהו בחי' חשך סתרו שזהו כמו [ש]מיש האמיתי לאין (בחי' ד\"ע כנ\"ל) ולא כמו עכשיו שהוא מאין ליש שהאין האלקי מוסתר כו' והיש גמור נגלה במציאות ע\"כ הם בבחי' פירוד לפרקים כו', וזהו שהראו לנבוכדנצר ואמ' כל דיירי ארעא כלא חשיבין<sup data-n=\"9046\">225</sup> ממש שזהו כמו [ד]קמי' ממש דכלא חשיב, ומעין זה הי' בקי\"ס ממש שהי' בחי' גילוי ההעלם דבחי' אין כו' שזהו מ\"ש<sup data-n=\"9047\">226</sup> כלא חשיבי בבחי' ביטול אמיתי מצד קירובו ליש האמיתי כו' [ד]אפי' אור צח אוכם הוא לגבי עה\"ע ונק' יראה בושת בחי' יר\"ע וכך יהי' לע\"ל כו', וז\"ש זה אלי<sup data-n=\"9048\">227</sup> לנוכח כו' וע\"כ ראתה שפחה על הים<sup data-n=\"9049\">228</sup> כו' (כמשי\"ת). וזהו ויהי נועם ה' עלינו<sup data-n=\"9050\">229</sup> דקאי לע\"ל [ש]יתגלה מעצמות התענוג הפשוט שנק' שעשוע[י] המלך בעצמותו<sup data-n=\"9051\">230</sup> ולא מוסתר בהעלם וחשך סתרו, והוא ע\"י שיוציא חמה מנרתקה<sup data-n=\"9052\">231</sup> שהוא שם אלקי' מעל שם הוי' ונגלה כבוד ה'<sup data-n=\"9053\">232</sup> וראו כ\"ב כו', ואמנם עכשיו נק' יושב בסתר עליון<sup data-n=\"9054\">233</sup> פי' סתר עליון [ז]הו בחי' אין <span data-k=\"pg\">ער</span> ּ הא' שהוא בחי' ההעלם והסתר דמל' בבחי' האצי' שלא ניכר שם לבחי' מציאות אור כלל כשרגא בטיהרא וכלבנה בפני השמש וכמו דאור צח ומצוחצח<sup data-n=\"9055\">234</sup> אוכם הוא כו'. ואמנם כמו המקיף דצ\"ל מוכתר<sup data-n=\"9056\">235</sup> על האדם הרי הצל [ה]זה בחי' מקיף ומגן [ומחסה] לאדם כמו בצל דצלם אדם אשר יהלך איש שמקיף לד\"א שלו ומאיר בו לפרקים מן ההעלם לגילוי וזהו בחי' אין הב' אין של היש שהוא בחי' שרש ומקור ליש המוגבל והוא",[["9041","220","<b>ובהו</b>: שם: ליתא."],["9042","221","<b>הפרסא. . אצי' לבריאה</b>: ראה ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"א. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי [כ, ב בדפי הספר]. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא (וראה לעיל קפו, ג ובהערה 115)."],["9043","222","<b>כנ\"ל</b>: ויז: בע\"ג כו'."],["9044","223","<b>ממשל הב'</b>: שם: ממשלים."],["9045","224","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["9046","225","<b>כל דיירי ארעא כלא חשיבין</b>: דניאל ד, לב [ושם: וכל. . כלה]."],["9047","226","<b>שזהו מ\"ש</b>: ויז: דזהו כמו שהוא."],["9048","227","<b>זה אלי</b>: בשלח טו, ב."],["9049","228","<b>ראתה שפחה על הים</b>: נסמן לעיל קלט, א."],["9050","229","<b>ויהי נועם ה' </b>[יז: ניתוסף: אלקינו]<b> עלינו</b>: תהלים צ, יז."],["9051","230","<b>שעשוע[י] המלך בעצמותו</b>: נסמן לעיל פ' בא צב, ד."],["9052","231","<b>שיוציא חמה מנרתקה</b>: נסמן לעיל פ' שמות לט, ב."],["9053","232","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["9054","233","<b>יושב בסתר עליון</b>: תהלים צא, יא."],["9055","234","<b>ומצוחצח</b>: ויז: ליתא."],["9056","235","<b>מוכתר</b>: שם: (ש)מסתיר."]]],[2300540499,"מל' דאצי' שהיא כתר לבריאה כנ\"ל שזהו צל שדי שאמר לעולמו די<sup data-n=\"9057\">236</sup> כו', וזהו יושב בסתר עליון בבחי' אין הא' כמו קמי' ממש כו' ואח\"כ נמשך להיות בבחי' צל שדי יתלונן שהוא בחי' מקיף דנר\"נ דבריאה ויצי' כו' כמ\"ש אומר לה' מחסי<sup data-n=\"9058\">237</sup> כו' כמו אך בצלם<sup data-n=\"9059\">238</sup> כו' וד\"ל.\n<b>והנה</b> מבואר מכל הנ\"ל בב' מדרגות דב' בחי' אין (שהוא בחי' ד\"ע וד\"ת כמ\"ש כי אל דעות הוי' כנ\"ל כמ\"ש במ\"א) דבחי' אין הא' הגם דכלא וכאין ממש יחשב לגבי עצמו' היש האמיתי ונק' חשך והעלם גמור שהוא בחי' העדר ההשפעה לגמרי לגבי המקבלים שלמטה כמו איידי דטריד למבלע כו' כנ\"ל במשל דתלמיד לפני רבו <sup data-n=\"9060\">239</sup>כנ\"ל, עכ\"ז הרי [הוא] גבוה ונעלה במדרגה הרבה מבחי' אין הב' שנק' בשם מקור ושרש ליש שהוא בחי' מקור ושרש לבע\"ג<sup data-n=\"9061\">240</sup> עכ\"פ, כי מה שהוא בבחי' ביטול והתכללות לגבי העילה שלו הוא יותר גבוה ממה שנק' משפיע [כ]שהוא בריחוק מקום כו' דהגם שאינו עדיין רק שרש ומקור להשגת המקבל להביא מן ההעלם לגילוי, מ\"מ הרי אין [אור ו]השפע זאת בא[ה] רק בצמצום גדול רק לפ\"ע כלי המקבל כמו התלמיד דלא קאים אדעתי' דרבי'<sup data-n=\"9062\">241</sup> עד מ' שנין לפי שעצם שכל הרב לא יוכל התלמיד לקבל [ו]המשפיע והרב<sup data-n=\"9063\">242</sup> לא יוכל להשפיע כל עצם שכלו להתלמיד רק לפ\"ע הכלי של קבלת התלמיד לבד כו', ו[כך] גם בזה [הגם] שנעשה מקור למקבל הרי אינו רק לפ\"ע כלי המקבל לבד ואין [ל]זה ערך כלל לגבי בחי' שכל עצמותו כמו שהי' מקבל מעילה שלו אע\"פ שה[י'] בתכלית ביטול [ה]מציאות בבחי' חשך כנ\"ל, אדרבה כל מה שהי' בביטול יותר שזהו מצד קירובו יותר אל העילה שלו כו' זהו הגבה למעלה יותר ממה שנעשה בחי' משפיע בריחוק מקום למקבל [הי]מנו כו' כמ\"ש הוי זנב לאריות<sup data-n=\"9064\">243</sup> ואל תהי ראש לשועלים, הרי מה שנק' מקבל וטפל לגבי העליון ממנו כו' הוא גבוה הרבה ממה שהוא ראש לשועלים קטנים [ממנו] כי הרי הוא בכל עומק שכלו הפנימי כמו שהוא ממש מתבטל ונכלל לגבי המשפיע שלו שלא יוכל להביא עומק זה לכלל השפעה כלל לגבי המקבלים הימנו אף בהיותו בריחוק מקום מן המשפיע וד\"ל. ודוגמא לדבר זה כמו יהושע שה[י'] תלמיד משה נער לא ימיש מתוך האהל<sup data-n=\"9065\">244</sup> דמשה, [ד]ודאי [מה] שהי' יהושע בטל ונכלל בפני משה פני חמה<sup data-n=\"9066\">245</sup> כו' בהיותו אתו עמו במחיצ[תו] הי' גבוה הרבה במעלה הרבה יותר ממה שהי' אח\"כ ראש לישראל אחרי הפרדו ממשה",[["9057","236","<b>שדי שאמר לעולמו די</b>: ראה חגיגה יב, א. וראה גם לעיל פ' וארא סב, ד."],["9058","237","<b>אומר לה' מחסי</b>: תהלים צא, ב."],["9059","238","<b>אך בצלם</b>: תהלים לט, ז."],["9060","239","<b>כנ\"ל</b>: ויז: כו'."],["9061","240","<b>בחי'. . לבע\"ג</b>: שם: (ב)בחי' אור ושפע."],["9062","241","<b>דלא קאים אדעתי' דרבי'</b>: נסמן לקמן ריז, ג."],["9063","242","<b>והרב</b>: ויז: ליתא."],["9064","243","<b>הוי זנב לאריות</b>: אבות פ\"ד, מט\"ו. ראה גם מאמרי אדה\"א נ\"ך ע' כד. דרושי חתונה ח\"ב ע' תרו. מאמרי אדמו\"ר ה”צמח צדק\" תרי\"ד ע' כג ואילך. לקמן פ' תצוה שכ, א."],["9065","244","<b>נער לא ימיש מתוך האהל</b>: תשא לג, יא. ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרכב. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרו. מאמרי אדמו\"ר ה”צמח צדק\" תרי\"ד ע' כג ואילך. לקמן שכ, א."],["9066","245","<b>בפני משה פני חמה</b>: בבא בתרא עה, סע\"א."]]],[2300540517,"כו' (וכמו הלבנה בקירובה אל השמש שכל אור השמש בעצמו מאיר עליו אף שהוא בבחי' חשך אז, זהו יותר [נ]עלה מהארת אור הלבנה שמאיר לארץ שנק' הארה דהארה מעצם אור השמש לבד כו' כידוע) וכשר לפני המלך אף שהוא בביטול גדול לפני[ו] יותר עליון הוא <span data-k=\"pg\">542</span> ּ מכמו שיהי' ראש ושר למדינה בריחוק[ו מאור פני מלך] וכענין הוי זנב לאריות כו'. וממילא יובן מזה בדרך כלל בכל עו\"ע שכל עלול נק' עילה לגבי העלול שמקבל ממנו ונק' עלול לגבי העילה שלו, [ד]בודאי מה שהוא בבחי'<sup data-n=\"9067\">246</sup> מקבל בקירוב מעילתו אף שהוא בביטול במציאות ממש כו' זהו מעלה ומדרגה שלו הרבה יותר ממה שהוא נעשה בחי' ראש ומשפיע לעלול שלו בריחוק מהעילה שלו כו'.\n<b>וזהו</b> שאנו אומרים [אמת] ואמונה כל זאת וקיים עלינו<sup data-n=\"9068\">247</sup> והול\"ל וקיימת עלינו בלשון נוק' אחר שא' ואמונה כל זאת כו' לשון נקבה, אך לפי שבחי' מל' שנק' אמונה היא תחלה בחי' מקבל מאמת דאיהו אמת ואיהי אמונה<sup data-n=\"9069\">248</sup> (שזהו ע\"ס דז\"א ונוק'<sup data-n=\"9070\">249</sup> אמת דתו' כו' ובחי' מל' בחי' מקבל מהאמת הזה ונק' אמונה, וזהו כללות התרי\"ג מצות<sup data-n=\"9071\">250</sup> שהעמידן על אחת<sup data-n=\"9072\">251</sup> שהיא אמונה, ולמעלה יותר זהו בחי' מל' דא\"ס שנק' אמונה רבה כו' <sup data-n=\"9073\">252</sup>בחי' שמי' רבא<sup data-n=\"9074\">253</sup> כו' שהוא כלי קיבול [ל]אמיתת מהו\"ע ית' ממש דלמתב\"כ וכנ\"ל, ואח\"כ נעשה המל' כתר ועתיק לבריאה שהוא בחי' אין הב' של היש כו', וזהו וקיים עלינו לשון דכר, דבחי' נוק' [ד]תחלה למעלה מבחי' ד[כ]ר זה כו', אדרבה כל מה שיש ביכולת המל' להיות ראש לשועלים<sup data-n=\"9075\">254</sup> [ב]בי\"ע אינו רק ממה שהי' תחלה בבחי' נוק' בביטול המציאות (שזהו בחי' ד\"ע שנק' חשך שלמעלה וקודם לאור כברייתו ש\"ע כו' כנ\"ל). וזהו כי אל דעות הוי'<sup data-n=\"9076\">255</sup> ד\"ע וד\"ת ולא ולו נתכנו עלילות<sup data-n=\"9077\">256</sup>, [ד]מצד בחי' ד\"ע שמיש לאין שהוא אין הא' ולא בא' דאם צדקת<sup data-n=\"9078\">257</sup> כו' להיות[ו] למעלה מבחי' מקור להשפיע לעולמות כנ\"ל, ומצד בחי' ד\"ת שנק' מקור לבריאה אין של היש ולו נתכנו בוי\"ו, וב' הדעות סובל ב' הפכים<sup data-n=\"9079\">258</sup> כא' דשניהם שוין לגבי בחי' העצמו' דא\"ס ממש וד\"ל (וזהו ג\"כ מארז\"ל ע\"פ עקב ענוה יראת ה'<sup data-n=\"9080\">259</sup> דמה שעשתה יראה שהוא בחי' המל'<sup data-n=\"9081\">260</sup> על עם נפרד עטרה לראשה בבחי' כתר מל' (שזהו בחי' אין הב' דמל' דאצי' נעשה ראש לשועלי' בבי\"ע כנ\"ל), עשתה ענוה עקב לסוליתה שהוא בחי' המל' כמו שהיא בטלה במקורה במח' דבינה שנק' עקב ענוה בחי' אותיות [ה]מח' כו' בביטול חשך [ו]העלם כנ\"ל, זהו אין הא'",[["9067","246","<b>בבחי'</b>: ויז: ליתא."],["9068","247","[אמת]<b>. . וקיים עלינו</b>: תפלת ערבית (ברכת אמת ואמונה). ראה מאמרי אדה\"א נ\"ך ע' כג. וש\"נ. שה\"א ק, א. לקמן פ' תצוה שכ, א."],["9069","248","<b>דאיהו אמת ואיהי אמונה</b>: נסמן לעיל פ' שמות י, ד."],["9070","249","<b>ונוק'</b>: ויז: נק' אמת והוא."],["9071","250","<b>התרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטילייא מערכת שש מאות (צפת תשנ\"ב ע' 208). מכתב כ\"ד מ\"ח ה'תש\"י נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך־ אג\"ק שלו ח\"ג ע' ריג."],["9072","251","<b>שהעמידן על אחת</b>: מכות כד, א."],["9073","252","<b>בחי'</b>: בגדוזחטייאיביגטוטזיז: בגיט' (!). אהיד: כבפנים."],["9074","253","<b>רבא</b>: בדהוחיאיגטזיז: רבה."],["9075","254","<b>המל' להיות ראש לשועלים</b>: נסמן לעיל פ' וארא נד, ב."],["9076","255","<b>הוי'</b>: ויז: ליתא."],["9077","256","<b>ולא ולו נתכנו עלילות</b>: שמואל-א ב, ג. ראה זהר (אד\"ז) האזינו רצב, סע\"ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370305\" data-slug=\"torah-or\" data-id=\"3901370305\">תו\"א יתרו סח, ב</a>. מאמרי אדה\"ז תקס\"ו ע' רח. לקמן פ' יתרו רסא, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670476\" data-slug=\"torat-chaim\" data-id=\"2300670476\">תו\"ח לך פח, ד</a> ובהנסמן במ\"מ לשם."],["9078","257","<b>דאם צדקת</b>: איוב לה, ז."],["9079","258","<b>ב' הפכים</b>: ויז: ליתא."],["9080","259","<b>עקב ענוה יראת ה'</b>: נסמן לעיל פ' שמות יח, ג."],["9081","260","<b>יראה. . המל'</b>: ראה ת\"ז בהקדמה (ו, א)."]]],[2300540535,"בחי' יר\"ע יראה בושת כנ\"ל שזהו כמו דקמי' כלא כו' הוא למעלה מעטרה דכתר מל' בבי\"ע מטעם הנ\"ל).\n<b>והנה</b> כמו שמבואר למעלה [בדרך כלל] בסדר ההשתל' דעו\"ע במל' דאצי' בבי\"ע ועד בחי' מל' דא\"ס בקו\"ח כו', כך יובן ג\"כ בדרך פרט בכל השתלשלו' הפרצופי' כו' מעליון לתחתון שצ\"ל ע\"י ג' בחי' דיש ואין [ויש] הנ\"ל שע\"י בחי' האין הממוצע הוא שיפריד ביניהם ויכול להיות מציאות היש שלמטה כמו מן השכל וחכ' לבינה בהשגה שצריך להיות ב' בחי' אין, [ה]א' נקודה דחכ' טרם שמתפשט בהשגה שנק' שמן שצף ע\"ג היין<sup data-n=\"9082\">261</sup>, והב' אין דחכ' שנמשך בבינה ונק' תרין ריעין<sup data-n=\"9083\">262</sup> והוא קוץ התחתון דיו\"ד שנמשך לבינה, ונקודה דיו\"ד דחכ' נק' אוכם לגבי עה\"ע שהוא הכתר והוא בחי' הרצון עצמו שלמעלה מן הטעם דהטעם לרצון כאין וכל\"ח (וכנראה מענין השוחד שימצא טעם לזכות שזהו רק הארה בעלמא מבחי'<sup data-n=\"9084\">263</sup> הרצון עצמ[ו] כו'<sup data-n=\"9085\">264</sup> (וכך גם טעם כמוס לרצון העליון שבמצות שנק' <span data-k=\"pg\">רעא</span> ּ רז[א] דרזין בחי' האין [הא'] דח\"ס [כנ\"ל] כל\"ח לגבי עה\"ע דרצון עצמו שבמצות כו' שהוא העוה\"ב [ש]אחר ימוהמ\"ש וד\"ל). וזהו שא' אפי' אור צח כו', וכן יש גבוה מעל גבוה כו' דגם בחי' אור הכת\"ר שהוא בחי' ע\"י וא\"א<sup data-n=\"9086\">265</sup> שלמעלה מבחי' ח\"ס דא\"א הנ\"ל גם הוא בחי' מקבל מלמעלה הימנו שהוא בחי' מל' דא\"ק בכלל ונק' אור מצוחצח תרין צחצחות בא' שהוא<sup data-n=\"9087\">266</sup> בחי' ע\"י וא\"א כו', שזהו בחי' הרצון ותענוג הפשוט שבלתי מורכב בחכ' כלל אפי' בטעם כמוס כו' גם זה אוכם הוא בבחי' חשך והעלם לנגד<sup data-n=\"9088\">267</sup> עה\"ע מל' דא\"ק שנעשה כתר לע\"י<sup data-n=\"9089\">268</sup> בכלל, וכן עד מל' דא\"ס בקו\"ח שע\"ז אמר יהי אור קדמאה<sup data-n=\"9090\">269</sup> כו' ממש שהוא ה[ארת] אור דקו\"ח שגם הוא אוכם לגבי עה\"ע כו', שזהו ב' מדרגות דחשך ואור הנ\"ל שהן ב' בחי' דאין הנ\"ל שזולת זה לא הי' באפשרי להיות כל עיקר ושרש ההשתל' דעו\"ע בכלל כי הי' כל עלול נכלל ובטל בעילתו עד עה\"ע כו' וד\"ל.\n(ז) <b>והנה</b> יש להקדים עוד ענין א' והוא בענין בחי' אין הנ\"ל הממוצע לחבר אור העליון בתחתון שהוא כלול מב' בחי' אין דוקא כנ\"ל, דלכאורה הנה הן ב' הפכים ממש ואיך יכול להיות דבר מהיפוכו דוקא דהיינו [מ]בחי' אין וביטול כלא ממש יהפך למהות היפוכו דוקא שהוא להיות מקור לשפע יש דוקא (כמו שהמל' באצי' בחי' אין ממש ולמטה בבי\"ע נק' מטרוניתא",[["9082","261","<b>שמן שצף ע\"ג היין</b>: נסמן לעיל פ' בא קכ, ג."],["9083","262","<b>דחכ'. . בבינה ונק' תרין ריעין</b>: נסמן לעיל קכ, א."],["9084","263","<b>מבחי' ויז</b>: מכח."],["9085","264","<b>כו'</b>: אוצ\"ל: כו')."],["9086","265","<b>הכת\"ר. . ע\"י וא\"א</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א."],["9087","266","<b>בא' שהוא</b>: ויז: ליתא."],["9088","267","<b>לנגד</b>: שם: (ל)קדם."],["9089","268","<b>מל' דא\"ק שנעשה כתר לע\"י</b>: נסמן לעיל פ' שמות ה, ב."],["9090","269","<b>יהי אור קדמאה</b>: בראשית א, ג. ראה זהר בראשית ל, ב. תרומה קסז, א."]]],[2300540553,"אימא תתאה<sup data-n=\"9091\">270</sup> כו' כנ\"ל בענין אמת ואמונה כל זאת כו') (וכדוד מ\"י שהי' בבחי' כח<sup data-n=\"9092\">272</sup> הביטול בתכלית למל' דאצי' שהי' מרכבה<sup data-n=\"9093\">271</sup> לשם והי' מלך על ישראל בהתנשאו' על עם דוקא<sup data-n=\"9094\">273</sup> כדוגמא דבחי' מל' [ה]עליון שכלול מב' הפכים דב' בחי' אין הנ\"ל). אך הענין הוא דצ\"ל תנאי עוד בזה והוא במה שהעלול צ\"ל בריחוק מקום מן העילה כו' כמ\"ש למעלה וא\"ל לא יוכל להתהפך מבחי' אין וביטול כזה להיות ראש ומשפיע למקבלים הימנו כו', וענין בחי' ריחוק מקום הזה היינו ענין ובחי' הפרסא המפסקת בין אצי' לבריאה כידוע שכדי שיהי' הפרסא והבדלה בריחוק מקום לבחי' אין הב' של היש דנבראי' בע\"ג מבחי' אין הא' בחי' ביטול במציאות בחי' חשך סתרו הנ\"ל הנה זהו ע\"י בחי' הפרסא המבדלת ביניהם, דלפני בחי' הפרסא הזאת שם המל' בבחי' אין הא' שנק' חשך ואחר ההעלם מחיצה זו שנק' פרסא הוא שנעשה המל' כתר לבריאה כמ\"ש בע\"ח דהמל' בוקעת המסך<sup data-n=\"9095\">274</sup> ונעשה ע\"י לבריאה כו', וזהו ענין ההבדלה שנעשה בין האור והחשך כמארז\"ל בתחלה היו האור והחשך משתמשים [בערבוביא<sup data-n=\"9096\">275</sup> ואח\"כ הבדיל ביניהם וכמ\"ש ויבדל אלקי'<sup data-n=\"9097\">276</sup> בין האור ובין החשך כו' דמשמע שקודם ההבדלה הזאת הי' אור וחשך משתמשים יחד] בערבוביא כו', וזהו פלא לכאורה איך יוכלו ב' הפכים דאור וחשך להיות משתמשים כא' דאם יש אור אין חשך ובמקום חשך אין אור כו', הענין הוא דזה עצמו שמתחלק ולא יאיר [אור] במקום חשך זהו נעשה אחר ההבדלה דוקא כמו שאנו אומרי' בתפלת ערבית גולל אור<sup data-n=\"9098\">277</sup> מפני חשך דמשמע שהי' אור תחלה אלא שגללו מפני החשך ונכלל בחשך וכן גולל חשך מפני אור הבא אחריו כו' וד\"ל. וביאור דבר זה היינו ענין<sup data-n=\"9099\">278</sup> ההבדלה דפרסא הנ\"ל בין חשך שהוא בחי' ההעלם דבחי' אין הא' הנ\"ל כמו שהוא<sup data-n=\"9100\">279</sup> דאוכם הוא לגבי עה\"ע [כ]נ\"ל שבלתי יכול להתגלות<sup data-n=\"9101\">280</sup> לעולם וכח\"ס שנק' רז[א] דרזין <span data-k=\"pg\">544</span> ּ וכמעיינות תהום (כמשי\"ת) והי' בחי' אור שהוא אין הב' מה שיוכל לבא בגילוי מאין ליש בטל ונכלל<sup data-n=\"9102\">281</sup> בהעלם זה ושניהם כא' משתמשין יחד [כ]ענין הנ\"ל בב' דעות ד\"ע וד\"ת שסובלם יחד וא[י]נם ב' הפכים הם כלי<sup data-n=\"9103\">282</sup> לגבי יש האמיתי עצמו כו'). אך כדי שיובדל ויופרש בחי' אור זה שנק' אין של היש מאין הנעלם דחשך סתרו הי' צ\"ל ע\"י בחי' הבדלה שנק' פרסא דוקא וא\"ל הי' החשך והאור משתמשין יחד כו' ולא הי' נמשך להיות שרש ומקור ליש מוגבל דנבראי' וכמ\"ש ויבדל אלקי' כו' (וענין פרסא זו ית' בסמוך).",[["9091","270","<b>שהמל'. . מטרוניתא אימא תתאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא רפנ\"ב. ש\"א טו, ב</a> ובהנסמן במ\"מ לשם."],["9092","272","<b>כח</b>: ויז: ליתא."],["9093","271","<b>וכדוד מ\"י. . למל'. . מרכבה</b>: נסמן לעיל פ' וארא עה, א."],["9094","273","<b>דוקא</b>: שם: ליתא."],["9095","274","<b>דהמל' בוקעת המסך</b>: נסמן לעיל פ' וארא ס, ב."],["9096","275","<b>בתחלה היו האור והחשך משתמשים [בערבוביא</b>: ראה רש\"י בראשית א, ד."],["9097","276","<b>ויבדל אלקי'</b>: בראשית א, ד."],["9098","277","<b>בתפלת ערבית גולל אור</b>: בברכות ק\"ש. ברכות יא, ב."],["9099","278","<b>ענין</b>: ויז: ליתא."],["9100","279","<b>כמו שהוא</b>: שם: ליתא."],["9101","280","<b>להתגלות</b>: שם: להגלל."],["9102","281","<b>בטל ונכלל</b>: שם: נכלל."],["9103","282","<b>הם כלי</b>: שם: כלל."]]],[2300540570,"<b>וביאור</b> הענין הנה מובן [מענין] משל [הנ\"ל ב]מעיינות תהום שנובעי' מן התהום דרך בקיעה בגידי הארץ כנ\"ל הרי כדור הארץ עצמה היא המפסקת בין התהום שנק' יש האמיתי<sup data-n=\"9104\">283</sup> ומקורו ובין המעיינות שנובעים בנהרות בגילוי ע\"פ הארץ כנ\"ל שנק' אי\"ן לי\"ש המוגבל דנהר, שהרי תחלת וראשית הנביעות דמעיינות תהום מתחת לארץ הרי הוא בבחי' ביטול במציאות כלא ממש חשיב לגבי התהום עצמו ונביעתו היא רק דרך גידים מצומצמים בהעלם גדול מאד, אך בהגיע הבקיעה שלהם עד למעלה בארץ שם הם באים בגילוי מן ההעלם דעפר הארץ (בבחי' מים חיים<sup data-n=\"9105\">284</sup> דוקא שלא הי' זה במי התהום עצמן כמ\"ש במ\"א) שזהו כמו שבוקע האור דשמש דרך מסך [ו]פרסא [בלבוש ארוך וטוב] עד שהבקיעה של האור [ה]זה שבוקע במסך זה עושה שינוי המהות לגמרי באור זה ונק' אור של תולדה מפני שמתחדש מן העלמת המסך דוקא כו' וד\"ל (וזהו לרוקע הארץ על המים<sup data-n=\"9106\">285</sup> שהן מי התהום כמ\"ש כי על ימים יסדה<sup data-n=\"9107\">286</sup> והיינו במאמר שא' יקוו המים כו' ולמקוה המים קרא ימים<sup data-n=\"9108\">287</sup> כנ\"ל ותחלה הי' למעלה מן הארץ ומעורבים<sup data-n=\"9109\">288</sup> במים עליונים קודם [ה]הבדלה שהבדיל בין מ\"ע למ\"ת (כמ\"ש במ\"א). וגם<sup data-n=\"9110\">289</sup> הוא כמשל הב' הנ\"ל מצומח וחי [ד]אדם שהארת האור וחיות נשתנה בשינוי המהות מרוחניות בעצם הנפש לחיות גשמי בדם כו' ע\"י לבוש ומסך שנק' חשמ\"ל, והוא בחי' צ\"ל מצלם כמו צל ימינו<sup data-n=\"9111\">290</sup> שנק' מזלא כו' שהוא מה שמאיר בהעלם דעורקי' שאין בהם דם<sup data-n=\"9112\">291</sup> שזהו [כמו] מעיינות תהום הנ\"ל שנכללים בארץ עצמ[ה] כו' בגידי הארץ כו', וכן בעשב הצומח ע\"י המזל שמכהו<sup data-n=\"9113\">292</sup> ואומר לו גדל בשינוי המהות מרוחני' דכח הצומח בעצם כו', ואם לא בחי' המזל הזה אין חיבור וקשר להיות שינוי המהות כ\"כ מרוחני' לגשמי' כמו ע\"י מזל דאדם שנק' צל במקיף ולבוש בהעלם כו', שזהו כמו בחי' פרסא הנ\"ל שנעשה מלבוש דחשמ\"ל המקיף כו' וד\"ל<sup data-n=\"9114\">293</sup>, וכמו סר צלם מעליהם<sup data-n=\"9115\">294</sup> [כו']. ונמצא דגם שע\"י המסך נגרע מהות האור מרוחני' לגשמי' אבל יש [בו] בשרשו מעלה יתירה והוא מה שיחודש בו האור לגמרי (וכמו בחי' מים חיים שנעשה ע\"י בחי' עובי כדור הארץ [דוקא] כנ\"ל, וכן בנשמה בגוף שנזרע מאור הזרוע לצ\"ע שנעשה בריאה מאין ליש יש לה שרש עליון למעלה מכמו שהיתה באור שלפני הצמצום דמסך כמ\"ש במ\"א ע\"פ לרוקע הארץ<sup data-n=\"9116\">295</sup> כו' וכמ\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"9117\">296</sup> כו', ובפרט בעלי' דאו\"ח בביטול היש לאין מלמטה (וכמו בזריעה שנזרעה<sup data-n=\"9118\">297</sup> בארץ וחוזר וצומח בחידוש יש",[["9104","283","<b>האמיתי</b>: שם: העצמי."],["9105","284","<b>מים חיים</b>: ראה גם מאמרי אדה\"א קונטרסים ס\"ע שצח ואילך. וש\"נ."],["9106","285","<b>לרוקע הארץ על המים</b>: תהלים קלו, ו. ראה גם מאמרי אדה\"א קונטרסים ע' שצז."],["9107","286","<b>כי על ימים יסדה</b>: תהלים כד, ב [ושם: כי הוא — וכ\"ה ביז]."],["9108","287","<b>ולמקוה המים קרא ימים</b>: בראשית א, י."],["9109","288","<b>ותחלה הי' למעלה מן הארץ ומעורבים</b>: ראה ב\"ר פ\"ה, ב. שה\"א נג, ב. וש\"נ. סז, א."],["9110","289","<b>וגם</b>: ויז: (וכך."],["9111","290","<b>צל ימינו</b>: איוב ח, ט."],["9112","291","<b>דעורקי' שאין בהם דם</b>: ראה ע\"ח (שער פני' וחי') ש\"מ, די\"ב. וראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תנב. וש\"נ. דברים ח\"ג ע' תתקיז. הנחות תקע\"ז ע' עא."],["9113","292","<b>בעשב. . המזל שמכהו</b>: נסמן לעיל פ' וארא ס, ב הערה 34."],["9114","293","<b>כו' וד\"ל</b>: ויז: ליתא."],["9115","294","<b>סר צלם מעליהם</b>: שלח יד, ט."],["9116","295","<b>לרוקע הארץ</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קעד. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תקלד ואילך."],["9117","296","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["9118","297","<b>שנזרעה</b>: ויז: שנרקבה."]]],[2300540586,"מאין בתוס' מרובה יותר מן הזריעה עצמה) שזהו ע\"י בקיעת המסך מלמטה למעלה לפי שעולה דרך המסך דוקא, כמו בשבת <span data-k=\"pg\">ערב</span> ּ שעולים הנשמות<sup data-n=\"9119\">298</sup> ומלאכים מבריאה לאצי' לפי שיש במסך עצמו מלמעלה מב' בחי' אין הללו דוקא וע\"כ בטלים ונכללים<sup data-n=\"9120\">299</sup> כו' (וכמו שיש במשל שרש למעלה יותר מגוף אור עומק השכל<sup data-n=\"9121\">300</sup> ממקורו כו' וכמשי\"ת וד\"ל).\n(ח) <b>והנה</b> ע\"ד הנ\"ל במשל התהום והארץ המפסקת כו' וכה\"ג כך יש בחי' פרסא מפסיק בין כל עולם עליון לתחתון הימנו (ובציור אדם דאצי' או אדם דבריאה כו' יש ג' מיני פרסא בכלל א' בחי' קרומא דאוירא<sup data-n=\"9122\">301</sup> כו' שהוא [ה]מפסיק בין כתר לחכ' שבראש והוא מ\"ש והבדילה הפרוכת כו' בין הקדש ובין קה\"ק<sup data-n=\"9123\">302</sup> דכ' כמאמר<sup data-n=\"9124\">303</sup> דאפי' אור צח כו', והוא עצם נקודת הרצון ו[ה]תענוג שלמעלה גם מטעם כמוס לרצון כו' כנ\"ל שנק' גולגלתא והקרומא הוא הקרום שבין גולגלתא למו\"ס שמו\"ס הוא מקור להמצאת שכל בגילוי והקרום הוא הפרסא המפסיק בריחוק מקום מן הכתר ובקיעת הקרום הזה הוא מה שיש מקור ליש דחו\"ב כו'. והפרסא הב' הוא מיצר הגרון<sup data-n=\"9125\">304</sup> שזהו מה שנתעלם אור המוחין דחו\"ב שבראש בפרסא זו במיצר הגרון ויוכל להיות מן השכל והשגה מקור להתפעלות המדות שזהו ג\"כ שינוי המהות משכל למדות מעילה לעלול שא\"א כ\"א בריחוק מקום שהוא מיצר הגרון שבו וע\"י מאיר אור למדות [ש]למטה בלב כו'. וכך הוא עוד למטה יותר מן המדות שבלב [כ]אהוי\"ר לנה\"י שזהו ג\"כ בא בדילוג מעליון לתחתון בשינוי המהות כמו מן המדות הרוחני' שבלב בחו\"ג לדון מזה למעשה בפו\"מ שהוא ע\"י בחי' הפרסא הג' שהוא חצר<sup data-n=\"9126\">305</sup> המפסיק<sup data-n=\"9127\">306</sup> הכבד כו' המפסיק בין אברי הנשימה לאברי המזון כידוע וכמ\"ש בזהר דקרומא פסיק במעוהי דב\"נ<sup data-n=\"9128\">307</sup> כנ\"ל<sup data-n=\"9129\">308</sup> (ויש עוד למטה בכליות יועצות ובירכי'<sup data-n=\"9130\">309</sup> שנק' נו\"ה כו' שזהו מנו\"ה לגוף גילוי השפע ביסוד). והוא פרסא שבין אצי' לבריאה ומבריאה ליצי' ומיצי' לעשי' (כידוע שזהו מחדו\"מ<sup data-n=\"9131\">310</sup> שיש הפסק בין מח' לדבור ע\"פ מיצר הגרון שהוא הקול וכן מדבור למעשה בפו\"מ לומר בעקימת שפתיו כו' דהויא מעשה שבדבור<sup data-n=\"9132\">311</sup> ), וכך הוא עד רום המעלות ג\"כ בבי\"ע שבאצי'<sup data-n=\"9133\">312</sup> בפרט ובכלל עד מל' דא\"ס ([כ]א\"ק שנק' אדם דבריאה וע\"י וא\"א נק' אדם דיצי' וז\"א נק' אדם דעשי'<sup data-n=\"9134\">313</sup> ), ולמעלה מעלה [גם] במל' דא\"ס יש בחי' פרסא רק שאינה בבחי' לבוש מסך ממש כמו בין אצי' לבריאה אלא הי'",[["9119","298","<b>בשבת שעולים הנשמות</b>: נסמן לעיל פ' שמות לה, ב. לקמן קצו, ד."],["9120","299","<b>בטלים ונכללים</b>: ויז: יוכל להפרידם."],["9121","300","<b>במשל שרש. . יותר מגוף. . השכל</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' שצג. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תתקכב ואילך. וש\"נ."],["9122","301","<b>קרומא דאוירא</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' ח. וש\"נ. לקמן פ' תצוה שסא, ג. שעז, ג."],["9123","302","<b>והבדילה. . ובין קה\"ק</b>: תרומה כו, לג. ראה מאמרי אדה\"א בראשית ע' לט־ שמות ח\"א ע' מב ובהנסמן בהנ\"ל."],["9124","303","<b>דכ' כמאמר</b>: ו: דכתוב במ\"א. יז: דכתר כמאמר."],["9125","304","<b>מיצר הגרון</b>: נסמן לעיל קסו, א."],["9126","305","<b>חצר. . הכבד</b>: נסמן לעיל שם."],["9127","306","<b>המפסיק</b>: ויז: ליתא."],["9128","307","<b>דקרומא פסיק במעוהי דב\"נ</b>: ראה זהר בראשית לב, ב."],["9129","308","<b>כנ\"ל</b>: ו: כו'. יז: ליתא."],["9130","309","<b>ובירכי'</b>: שם: וב' ירכין."],["9131","310","<b>ומבריאה ליצי'. . לעשי'. . מחדו\"מ</b>: נסמן לעיל קמד, ב."],["9132","311","<b>בעקימת שפתיו. . מעשה שבדבור</b>: נסמן לעיל ה, א."],["9133","312","<b>ג\"כ </b>[ויז: גם]<b> בבי\"ע שבאצי'</b>: נסמן לעיל קמה, ב."],["9134","313","<b>[כ]א\"ק. . אדם דעשי'</b>: נסמן לעיל קמה, ג הערה 68."]]],[2300540602,"בחי' מקו\"פ וחלל ריקן כו' כמ\"ש בע\"ח<sup data-n=\"9135\">314</sup> (ועכ\"ז נק' בחי' חשך סתרו<sup data-n=\"9136\">315</sup> והוא בחי' חשמ\"ל העליון<sup data-n=\"9137\">316</sup> ), לפי שגם מה שאחר הצמצום הראשון הזה (שצמצם אור הראשון [ו]נכלל בעצמות ולא נשאר רק רושם כו' שהוא נקודה דיו\"ד בקו\"ח בצורת וי\"ו<sup data-n=\"9138\">317</sup> כו') הוא שנמשך בקו\"ח, הרי קו\"ח זה אינו רק להיות מקור למקור למציאות ע\"ס דאצי' שהוא כמו להיות חכ[י]ם ומבין כו' דאע\"פ שנאצלו [מ]עצמות המאציל כו' הרי איהו וחיוהי חד<sup data-n=\"9139\">318</sup> בבחי' יחוד אמיתי בעצמו' א\"ס ממש כשלהבת הקשורה בגחלת<sup data-n=\"9140\">319</sup> כמ\"ש בס\"י ונק' ע\"ס בלי מה בלי מהות<sup data-n=\"9141\">320</sup> כו' וכמ\"ש חכים ולא בחכ' ידיעא<sup data-n=\"9142\">321</sup> כו' עד ולאו מכא\"מ כלל, ע\"כ לא שייך בזה ענין ובחי' פרסא ממש בצמצום הראשון (רק בבחי' מקו\"פ וחלל כו' שאין [זה] רק הסתלקות האור במאור), משא\"כ מאצי' לבריא' שזהו להיות חכ' דבריאה<sup data-n=\"9143\">322</sup> מוגבלת מאין ליש ממש מאצי' שהוא בלתי בע\"ג כו' שאין ערך <span data-k=\"pg\">546</span> ּ כלל ביניהם, אע\"פ שנעשה המל' רק בחי' שרש ומקור לנבראים בע\"ג הוצרך להיות ע\"י צמצום גמור דמסך ופרסא המפסיק בלבוש גמור שהוא בחי' ריחוק מאצי' שהוא בחי' אין הב' להפרד מאין הא' כנ\"ל וא\"ל לא הי' בחי' המל' מקור לבריאה כי הי' נכלל באצי' כנ\"ל וד\"ל.\n<b>והנה</b> מובן מכ\"ז עכ\"פ שבלתי בחי' הפרסא שמפסיק בין עליון לתחתון (כמו מן הרצון לשכל ומשכל למדות ומן המדות למח' וממח' לדו\"מ [כ]נ\"ל) הי' כל עלול נכלל בעילתו וחוזר הכל לקדמותו, ואמנם [יש להבין] מהיכן נעשה בחי' הפרסא זו<sup data-n=\"9144\">323</sup> להפסיק ולעשות בחי' ריחוק מקום כנ\"ל, הענין הוא דא\"א שיהי' הפסק הזה ע\"י בחי' אותיות לבד, שהרי זהו השתלשלו' דכל עו\"ע שמבחי' אותיות דעליון נעשה מקור לתחתון כמו מאותיות השכל נעשה מקור למדות שבלב ומאותיות והרהורים שבלב נמשך למח' ודבור כמו אותיות הדבור שמגלה [הכל] למקבל כמו שהוא במשפיע בלי שום העלם ולבוש והסתר כלל. אך האמת הוא דעיקר בחי' הפרסא נעשה מבחי' המקיף דוקא שזהו מלמעלה מן המשפיע ומקבל דהיינו מה שבלבוש והעלם דפרסא זו יתעל[ם] כל עיקר השפע מן המשפיע ואח\"כ יאיר אור השפע מתוך הלבוש והסתר הזה דוקא כנ\"ל שזהו נק' בחי' ריחוק מקום כו'. והענין הוא כמו ענין המשל שנעשה כמו חומר מלבוש לצורת אור השכל והסברא, והיינו דוקא כאשר אור השכל והסברא ההיא עמוק עמוק ביותר עד שא\"א לגלותה בכלי הדבור אף לחכם גדול ביותר אזי מוכרח להלביש[ה] במשלים מאחר",[["9135","314","<b>מקו\"פ וחלל ריקן. . בע\"ח</b>: ראה שם (דרוש עגו\"י) ש\"א, ענף ב."],["9136","315","<b>חשך סתרו</b>: נסמן לעיל פ' בא קכג, ג."],["9137","316","<b>חשמ\"ל העליון</b>: ראה גם לעיל פ' שמות א, ג הערה 43."],["9138","317","<b>בקו\"ח בצורת וי\"ו</b>: ראה גם לעיל קנה, ב. וש\"נ."],["9139","318","<b>איהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["9140","319","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["9141","320","<b>ע\"ס בלי מה בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["9142","321","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה גם לקמן פ' יתרו רסו, סע\"ד ואילך."],["9143","322","<b>חכ' דבריאה</b>: ויז: התהוות."],["9144","323","<b>הפרסא זו</b>: ו: הפרסא וממה נעשה. יז: פרסא זו וממה נעשית."]]],[2300540616,"שא\"א לגלות אור[ו] לזולתו מגודל עומקו, וכמו משלי שלמה [ש]איזן וחקר ותיקן משלים הרבה<sup data-n=\"9145\">324</sup> שהעיקר<sup data-n=\"9146\">325</sup> של משלים הללו היינו מצד עומק החכ' דשלמה שלא הי' יכול להביאם בגילוי הדבור כלל אף לחכמים גדולי המדע לכך הוצרך להלביש עומק החכ' [עילאה] במשלים<sup data-n=\"9147\">326</sup> וחידות כמו [להבין] משל ומליצה<sup data-n=\"9148\">327</sup> כו' (וכמו ג' מאות משלי [שועלים] דר\"מ<sup data-n=\"9149\">328</sup> כו' ובשלמה א' וידבר שלשת אלפים משל<sup data-n=\"9150\">329</sup> נגד ג' עולמות<sup data-n=\"9151\">330</sup> דבי\"ע שכל א' כלול מאלף הוצרך לעשות משלים להמשיך מח\"ע לחכ' שבמל'<sup data-n=\"9152\">331</sup> בבי\"ע להלביש לאור החכ' הקדומה בג' אלפים משל כו' וד\"ל).\n<b>והנה</b> המשל הוא נעשה מדברים וענינים זרים דמעלים ומסתיר לגמרי אור צורת השכל הרוחני ועמוק מאד עד שאינו נראה לעין הרואה במשלים רק דברים פשוטי' מענינים הנ\"ל<sup data-n=\"9153\">332</sup> וא\"כ אין נראה רק בחי' הלבוש המסת[י]ר בלבד, ואע\"פ שראה החכ'<sup data-n=\"9154\">333</sup> ומבין מדעתו ומשיג את הנמשל מן המשל הזה השגה זו כבר נתמעט אורה והוקטנה מצד שאינו משיג רק מתוך דמיון המשל לבד וה\"ז כמו שרואה דרך מסך ולבוש ע\"כ שמה שיראה ממנה הוא מעט מזעיר בשינוי המהות לגמרי מן האור המאיר להדי' כו' (ואמנם נעשה יתרון האור בחידוש גמור ונפלא יותר ע\"י הלבוש הזה כנ\"ל במשל המ\"ח שבארץ כו'). וראי' מח\"ע דתו' הקדומה שנק' משל הקדמוני<sup data-n=\"9155\">334</sup> כו' לפי שעומק דח\"ע לא יוכל לבא באותיות הדבור רק במשלים והוא שנתלבשה התורה למטה בעה\"ד טו\"ר<sup data-n=\"9156\">335</sup> בדברים גשמי' דוקא שזהו ממש כהלבשת אור השכל העמוק ביותר בענינים זרים דמשל כו' ועי\"ז נעשה יתרון אור חדש בתורה שלמטה יותר מח\"ע דתוה\"ק שנק' תורה אור אור קדמאה<sup data-n=\"9157\">336</sup> כמ\"ש עוטה אור כשלמה<sup data-n=\"9158\">337</sup> כמו בחי' טיהרא עילאה<sup data-n=\"9159\">338</sup> <span data-k=\"pg\">רעג</span> ּ זיהרא עילאה<sup data-n=\"9160\">339</sup> דכח\"ב<sup data-n=\"9161\">340</sup> או\"ר באלף<sup data-n=\"9162\">341</sup> כו'. והנה עד\"ז יובן ענין [ובחי'] לבוש הפרסא הנעשה בין כל עולם ועולם כמו מאצי' לבריאה שיוכל להיות מקור לבריאה כנ\"ל היינו ע\"י הסתר אור המל' בלבוש מסך באותיות וצרופי' דמשלים וכה\"ג (וזהו שא' בע\"ח דמחיצוני' בינה שנק' חשמ\"ל נעשה מלבוש לזו\"נ<sup data-n=\"9163\">342</sup> ומזה נעשה בחי' הפרסא ש[מ]תחתיהם להפסיק בין אצי' לבריאה כו'). וכמו\"כ יובן בכל בחי' הפרסא מריש כ\"ד מצמצום הראשון עד מל' דעשי' [ב]עוה\"ז הכל הוא ע\"ד דמיון מלבוש דמשל וכה\"ג ולא כמו גל של אבנים שבלתי מוסד הנ\"ל<sup data-n=\"9164\">343</sup> שלא נראה אור כלל, אבל באריגת המסך שנק' פרוכת אף שמסתיר יוכל לראות יותר כמו שרואה השכל מתוך לבוש המשל",[["9145","324","<b>[ש]איזן. . משלים הרבה</b>: קהלת יב, ט."],["9146","325","<b>שהעיקר</b>: ויז: שהענין."],["9147","326","<b>עומק החכ'. . במשלים</b>: ראה גם לעיל פ' בא צה, א ובהערה 401."],["9148","327","<b>[להבין] משל ומליצה</b>: משלי א, ו."],["9149","328","<b>ג' מאות משלי [שועלים] דר\"מ</b>: ראה סנהדרין לח, סע\"ב."],["9150","329","<b>וידבר שלשת אלפים משל</b>: נסמן לעיל פ' וארא פג, ב."],["9151","330","<b>עולמות</b>: ויז: מדריגות."],["9152","331","<b>לחכ' שבמל'</b>: ויז: בח\"ת דמל'."],["9153","332","<b>מענינים הנ\"ל</b>: ו: ועניני הבל. יז: מעניני השכל."],["9154","333","<b>שראה החכ'</b>: שם: שרואה החכ'."],["9155","334","<b>דתו'. . משל הקדמוני</b>: נסמן לעיל פ' שמות ח, ב."],["9156","335","<b>בעה\"ד טו\"ר</b>: ו: בעה\"ד כו'. יז: בעוה\"ז כו'."],["9157","336","<b>תורה אור אור קדמאה</b>: משלי ו, כג. ראה זהר תרומה קסו, ב. קסז, א. מאמרי אדה\"א בראשית ע' תה. במדבר ח\"א ע' קפא."],["9158","337","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["9159","338","<b>טיהרא עילאה</b>: ויז: ליתא."],["9160","339","<b>זיהרא עילאה</b>: נסמן לעיל פ' שמות ח, ב."],["9161","340","<b>דכח\"ב</b>: ו: דכתיב. יז: דכתנות. וראה להלן הערה 428."],["9162","341","<b>או\"ר באל\"ף</b>: נסמן לקמן הערה 427."],["9163","342","<b>בע\"ח. . חשמ\"ל. . לזו\"נ</b>: ראה שם (שער כללות דרושי אבי\"ע) שמ\"ב, פי\"ג. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670572\" data-slug=\"torat-chaim\" data-id=\"2300670572\">תו\"ח נח נח</a>, א."],["9164","343","<b>מוסד הנ\"ל</b>: ויז: מסודרים."]]],[2300540630,"(כמשי\"ת) , ואם לא בחי' הפרסא [ו]העלמות הנ\"ל בבחי' ריחוק מקום בין כל עו\"ע בכלל ובפרט הי' כל עילה נכלל ודבוק בעילתו ולא הי' יכול להיות שום השתלשלות מעילה לעלול כלל כי הרי<sup data-n=\"9165\">344</sup> הי' הכל חוזר לקדמותו שהוא לעילת כל העילות<sup data-n=\"9166\">345</sup> כנ\"ל<sup data-n=\"9167\">346</sup> וד\"ל.\n(ט) <b>והנה</b> מעתה אחר כל הקדמות הנ\"ל יובן ג\"כ שרש ענין [קי\"ס] הנ\"ל שהוא בבחי' מל' סופא דכ\"ד דאצי' ונק' כנישו דכל נהורין<sup data-n=\"9168\">347</sup> עילאין דאצי' כמו כל הנחלים הולכים אל הים כנ\"ל באורך. דהנה עיקר ענין קי\"ס העליון זהו כמו ענין בחי' בקיעת הפרסא למעלה דהיינו שיאיר אור האצי' בבריאה כמו שהוא [ממש ב]לא [לבוש והעלם כלל] ע\"י התלבשות במסך ופרסא זו, שהוא ע\"י סדר השתלשלו' דעו\"ע צ\"ל ע\"י בחי' לבוש והסתר דפרסא מטעם הנ\"ל, אבל למעלה מכפי סדר ההשתל' דעו\"ע בכלל ה\"ז כמו בחי' בקיעה במסך זה שלא יסתיר מסך ופרסא זו כלל ואז יאיר אור האצי' בבי\"ע<sup data-n=\"9169\">348</sup> כמו שהוא [ממש] בלי לבוש והעלם כלל (וע\"כ א' בקי\"ס זה אלי לנוכח כו' ראתה שפחה על הים כו' כמשי\"ת). וכמו עכשיו בכל שבת שבוקע המסך מאצי' לבריאה שזהו בחי' חסדים דשם הוי' מאירי' בשם אלקי' ואין שם אלקי' מצמצם ומסתיר כלל וכמו גילוי הנבואה בנביאים (וכמשי\"ת) והיינו ך\"ו כל\"ח<sup data-n=\"9170\">349</sup> [כידוע] וזהו ביום השבת, אבל בליל שבת הרי עולה באו\"ח ממטה למעלה כידוע בג' הבו<sup data-n=\"9171\">350</sup> כו' דמלאכי' דבי\"ע עולים באצי' שהוא בקיעת המסך מלמטה למעלה כו'. והנה בחי' הארה זו מאצי' לבריאה כמו שהוא עד רום המעלות כך הוא גם מעצמות הא\"ס בקו\"ח שלא ע\"י צמצום הראשון דחשך סתרו כו' שיתגלה מהעלמו כמו שהוא ממש (כמו בעוה\"ב שנא' הנה אלקינו זה<sup data-n=\"9172\">351</sup> ), וזה נק' בשם דילוג וקפיצה כמ\"ש קול דודי כו' מדלג על ההרים מקפץ על הגבעות<sup data-n=\"9173\">352</sup> פי' מדלג ממהות [ועצמות] שלו למטה שלא ע\"י סדר השתלשלו' עו\"ע שנק' הרים וגבעות כו' אלא [מדלג] על ההרים כו'. וכך הי' בקי\"ס דכתי' הים ראה וינוס<sup data-n=\"9174\">353</sup> שמבחי' העלם דים (שהוא המח' שבהעלם) נעשה הוא עצמו בחי' דבור<sup data-n=\"9175\">354</sup> שלא ע\"י צמצום והסתר כלל וז\"ש שהים ראה וינוס שהוא המח' שנעשה דבור וההרים הן המדות<sup data-n=\"9176\">355</sup> רקדו כאלים כו'. והנה הטעם באמת שהוצרך לכ\"ז לעשות שלא כסדר ההשתל' בכלל ובפרט כנ\"ל לפי שלא הי' יכול להיות יצ\"מ כפי סדר ההשתל' כלל, כי הרי ישראל היו משוקעים בנ' שע\"ט<sup data-n=\"9177\">356</sup> דקליפת מצרים<sup data-n=\"9178\">357</sup>",[["9165","344","<b>הרי</b>: שם: ליתא."],["9166","345","<b>לעילת כל העילות</b>: נסמן לעיל פ' וארא עט, ג."],["9167","346","<b>כנ\"ל</b>: יז: כו'."],["9168","347","<b>מל'. . כנישו דכל נהורין</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א כאן (ע' רח). במדבר ח\"א ס\"ע צו."],["9169","348","<b>בבי\"ע</b>: ויז: בבריאה."],["9170","349","<b>ך\"ו כל\"ח</b>: נסמן לעיל קמד, א."],["9171","350","<b>בג' הבו</b>: נסמן לעיל קסה, ג."],["9172","351","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["9173","352","<b>קול דודי כו' מדלג. . הגבעות</b>: שה\"ש ב, ח."],["9174","353","<b>הים ראה וינוס</b>: תהלים קיד, ג."],["9175","354","<b>דבור</b>: ויז: גילוי."],["9176","355","<b>וההרים הן המדות</b>: נסמן לעיל יד, ד."],["9177","356","<b>משוקעים בנ' שע\"ט</b>: נסמן לעיל פ' שמות מא, ד."],["9178","357","<b>מצרים בחי' כתר דק\"נ</b>: נסמן לעיל קלו, ד."]]],[2300540643,"בהסתר<sup data-n=\"9179\">358</sup> דק\"נ שנק' עומק רע ונק' ערות הארץ<sup data-n=\"9180\">359</sup> שרש לכל הז' מדות רעות דק\"נ כו' והי' צריך להוציאם <span data-k=\"pg\">548</span> ּ מבחי' חשך ואפילה כזאת מעומק תחת כ\"כ להעלותם ולהביאם למעלה עליונה כ\"כ שהוא להכניסם לא\"י וכמ\"ש אנכי ארד כו' [ו]אנכי אעלך<sup data-n=\"9181\">360</sup> כו', שבבחי' ירידה גדולה כזו למצרים עומק תחת צריך להיות העלי' ממקום הנעלה ביותר שלא כפי הדרגת ההשתלשלו' בכל העולמות, והוא משארז\"ל שנגלה עליהם מלך מה\"מ הקב\"ה בכבודו ובעצמו<sup data-n=\"9182\">361</sup> דוקא כמ\"ש ועברתי באמ\"צ אני ולא מלאך<sup data-n=\"9183\">362</sup> כו' דהיינו שצריך להיות מבחי' עומק רום דהיינו מעומק רוממות ועצמו' דא\"ס כמו שהוא בלי העלם ולבוש וצמצום כנ\"ל, ולזאת הי' ענין עוד מעלה ומדרגה יתירה בקי\"ס שהי' גילוי אור העצמו' דא\"ס ממש למטה כמו שהוא למעלה ממש שזהו למעלה גם מבחי' עמ\"ר ועמ\"ת כו' ולכך א' זה אלי [ממש] כמו בעוה\"ב כנ\"ל, ומטעם זה הים ראה וינוס כו' שנעשה בחי' ההעלם עצמו גילוי שזהו הארת האצי' בבריאה כמו שהוא למעלה בלי חילוק מדרגות בין אצי' לבריאה, כי מה שיש הפרש בזה אינו רק מצד בחי' עו\"ע משפיע ומקבל [סובב וממלא] בכלל וים ויבשה בפרט כו', אבל בהגלות נגלות מאוא\"ס עצמו ששוין ממש אצי' ובריאה<sup data-n=\"9184\">363</sup> משפיע ומקבל כו' (כמשי\"ת), וזהו וירא ישראל סבא<sup data-n=\"9185\">364</sup> (מדות דח\"ס דא\"א [כו']) את היד הגדולה דעצמו' [או]א\"ס ממש אשר עשה שם הוי' במצרים כו' והוא מה שגוזר ים סוף לגזרים כל\"ח חסד העצמי ששוין שם העלם וגילוי כו' וד\"ל.\n<b>והנה</b> מבואר למעלה שהבקיעה גשמי' בי\"ס שלמטה הי' בב' דברים הא' שהמים דים שנובעים<sup data-n=\"9186\">365</sup> להיות נמשכים ומתפשטי' כטבע המים דניידי ואזלי<sup data-n=\"9187\">366</sup> נעשה בחי' דומם ממש כמ\"ש נצבו כמו נד קפאו כו' כנ\"ל דאגלידו מיא ונעשה כקרח, וז\"ש והמים להם חומה<sup data-n=\"9188\">367</sup> ממש כנ\"ל וזהו הפך ים למהות יבשה, והב' מה שנעשה מבקיעה זו בים מלמעלה עד למטה בהפסק וריוח גדול עד שנעשה מסילה ודרך למטה ביבשה בתוך הים כו' וכמ\"ש הנותן בים דרך כו'. וכך הי' בבחי' קי\"ס למעלה בבחי' הרוחני' דים העליון שהוא בחי' מל'<sup data-n=\"9189\">368</sup> דאצי' שנעשה כת\"ר לבריאה<sup data-n=\"9190\">369</sup> ע\"י העלמת<sup data-n=\"9191\">370</sup> המסך כנ\"ל שמה שלפני המסך נק' מים עליונים דימא עילאה דים הקדמוני שנמשך בקי\"ס סופא דכל דרגין כו' והי' צריך להיות ג\"כ ב' דברים כנ\"ל בקי\"ס בגשמי', הא' מה שבחי' ההעלם דים העליון עצמו נעשה גילוי כדמיון אותיות<sup data-n=\"9192\">371</sup> כו' והוא מה שבחי' העלם דחשך עצמו נעשה",[["9179","358","<b>בהסתר</b>: ויז: בחי' כתר."],["9180","359","<b>מצרים. . ערות הארץ</b>: מקץ מב, ט. יב. ראה קה\"ר פ\"א, ד (בסופה). ע\"ח (שער ציור עולמות) שמ\"ג, פ\"א."],["9181","360","<b>אנכי ארד. . אעלך</b>: ויגש מו, ד."],["9182","361","<b>שנגלה. . בכבודו ובעצמו</b>: הגש\"פ פיסקא מצה זו [שנגלה. . הקב\"ה]. ויוציאנו [הקב\"ה בכבודו ובעצמו]."],["9183","362","<b>ועברתי באמ\"צ אני ולא מלאך</b>: בא יב, ב. ספרי תבוא כו, ח. זהר (מדהנ\"ע) וירא קיז, א. הגש\"פ."],["9184","363","<b>בהגלות. . ששוין ממש אצי' ובריאה</b>: ראה גם הנסמן לעיל קלה, א."],["9185","364","<b>וירא ישראל סבא</b>: נסמן לעיל קנד, ד."],["9186","365","<b>שנובעים</b>: ויז: שטבעם."],["9187","366","<b>כטבע המיים דניידי ואזלי</b>: ראה עירובין מו, א."],["9188","367","<b>והמים להם חומה</b>: בשלח יד, כב. לעיל קפו, ב."],["9189","368","<b>דים. . מל'</b>: נסמן לעיל קלט, ב."],["9190","369","<b>מל' דאצי' שנעשה כת\"ר לבריאה</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. פ\"ה. פ\"ו."],["9191","370","<b>העלמת</b>: ויז: העלאת."],["9192","371","<b>כדמיון אותיות</b>: שם (ב)כדומם דאותיות."]]],[2300540655,"אור, ולא כמו אור המאיר אחר הצמצום והעלם דחשך ע\"י הבדלה שנעשה בין האור והחשך והוא מ\"ש ויהי הענן והחשך ויאר את הלילה כו' שהרי זה הי' קודם הבקיעה (כמשי\"ת) דענן וחשך עצמו הוא שנעשה בבחי' אור להאיר והיינו בחי' הא' שהי' בקי\"ס בגשמי' כנ\"ל, והוא כמו שהי' במצרים כדי להוציאם ממצרים<sup data-n=\"9193\">372</sup> מחשך ואפילה דנ' שע\"ט דמצרים הוכרח להיות [בחי'] תוס' אור העליון מלמעלה מבחי' החשך והאור העלם וגילוי כו' עד שהאיר להם גם בחשך ואפילה וכמ\"ש וגם חשך לא יחשיך ממך<sup data-n=\"9194\">373</sup> כו', וכך הי' בקי\"ס שהאיר הענן והחשך [ב]עצמ[ו] כנ\"ל וזהו ויסע מלאך האלקי' כו'. והב' זהו מה שנעשה [בחי'] דרך ומסילה ביבשה ממש בתוך הים <span data-k=\"pg\">רעד</span> ּ העליון דוקא והיינו כאשר בחי' לבוש והעלם דפרסא זו עצמה יאיר ויהי' בבחי' דרך הוי' לילך בה לנשמות שבגופי' בעוה\"ז וד\"ל.\n(יו\"ד) <b>ולהבין</b> זה, הנה יש להבין מ\"ש תחלה ויסע מלאך האלקי' כו' למה קראו בשם אלקי' דוקא וכידוע דכל בחי' אלקי' הוא מבחי<sup data-n=\"9195\">374</sup>' הגבול<sup data-n=\"9196\">375</sup> והצמצום<sup data-n=\"9197\">376</sup> דוקא כמו בראשית ברא אלקי' שהוא במדה\"ד<sup data-n=\"9198\">377</sup> כו' וגם כאן בחי' מלאך האלקי' דוקא זהו בחי' הצמצום דשם אלקי' שהוא מסתיר על שם הוי' דחסדי' כמ\"ש כי שמש ומגן הוי' אלקי'<sup data-n=\"9199\">378</sup> כו' כידוע, והיינו בחי' צמצום המסך ופרסא שקודם גילוי האור שנק' חשך והסתר כמאמר כברייתו ש\"ע ברישא חשוכא והדר נהורא כו', והיינו ג\"כ בחי' הענן שזהו מה שהאור אלק[י] דהוי' דאצי' מסתתר ומתעלם בתוך הענן וזהו בחי' הלבוש שמתלבש בו הצמצום דשם אלקי' (משום דגם שם אלקי' יוכל להאיר כשם הוי' [כ]מגן ונרתק השמש שיאיר גם הוא, כמו לע\"ל דכתי' ושמתי כדכד שמשותיך<sup data-n=\"9200\">379</sup> כמ\"ש במ\"א). וזהו כמו ויבא משה בתוך הענן<sup data-n=\"9201\">380</sup> שיסתירנו ויוכל לקבל אור ה', או כמו [ו]משה נגש אל הערפל<sup data-n=\"9202\">381</sup> אשר שם האלקי' הרי בחי' אלקי' שהוא בחי' הצמצום וההסתר כמו אתה אל מסתתר<sup data-n=\"9203\">382</sup> ומתלבש בלבוש דענן וערפל שהוא בחי' החשך [ש]קדם לאור, וגם כאן א' בקי\"ס המלאך האלקי' והענן שהיו נוסעי' לפני מחנה ישראל ויעמדו שניהם מאחריהם כדי להסתיר ולהעלים האור למצרים וז\"ש ויסע מלאך האלקי' כו' וד\"ל.\n<b>אך</b> הנה לכאו' יש להפליא בזה מאד דאם עיקר הכוונה הי' במלאך האלקי' [והענן] הזה לעמוד בין מחנה ישראל למצרים להחשיך האור למצרים כמ\"ש ולא קרב זא\"ז כל",[["9193","372","<b>ממצרים</b>: שם: ליתא."],["9194","373","<b>וגם </b>[יז: גם]<b> חשך לא יחשיך ממך</b>: נסמן לעיל פ' וארא סד, א."],["9195","374","<b>אלקי' הוא מבחי' הגבורה</b>: נסמן לעיל סו, ב."],["9196","375","<b>הגבול</b>: ו: הגבורה. יז: הגבורות."],["9197","376","<b>אלקי'. . והצמצום</b>: נסמן לעיל פ' שמות לד, ד."],["9198","377","<b>בראשית ברא אלקי' שהוא במדה\"ד</b>: בראשית א, א וברש\"י שם. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תכט. וש\"נ. וע' תמב."],["9199","378","<b>כי שמש ומגן הוי' אלקי'</b>: נסמן לעיל סג, ג."],["9200","379","<b>ושמתי כדכד שמשותיך</b>: ישעי' נד, יב."],["9201","380","<b>ויבא משה בתוך הענן</b>: משפטים כד, יח. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רעז. וש\"נ."],["9202","381","<b>[ו]משה נגש אל הערפל</b>: יתרו כ, יח. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שעא. וש\"נ."],["9203","382","<b>אתה אל מסתתר</b>: ישעי' מה, טו."]]],[2300540667,"הלילה<sup data-n=\"9204\">383</sup> כו' והלא בפי' א' ויהי הענן והחשך ויאר את הלילה הרי הענן והחשך דשם אלקי' המסתיר הן עצמם האירו אור גדול וא\"כ הי' אור גם למצרים ומדוע לא קרב זה אל זה כל הלילה, וצ\"ל בהכרח דהגם שהי' הענן והחשך מאירים להאיר את הלילה כמ\"ש ויאר את כו' זה הי' רק לישראל [לבדם] אבל למצרים הי' הענן והחשך הזה עצמן להעלים ולהסתיר את האור, וזה פלא גדול איך יוכל להיות שני הפכים בנושא א'. אך הנה התירוץ לזה יש להקדים ענין הנ\"ל בבחי' פרסא המפסיק בין אצי' לבריאה וענין בקיעת הפרסא הזאת, שמבואר למעלה דבחי' הסתר זה דפרסא היינו כמו ענין לבוש המשל אל השכל דוקא שהמשל מדבר בענינים זרים לגמרי אך מתוכו יובן הנמשל, וזהו כאשר אור השכל עמוק ביותר אז מוכרח להלביש אור עומק השכל במשל זר כו'. והנה באמת הגם שענין המשל מדבר רק בדברים זרים ופשוטים שלא מענין [ו]בחי' מהות השכל וחכ' כלל עכ\"ז הרי המשל צ\"ל באופן וערך שיהי' בדוגמא ובדומה ממש לאור השכל והחכ'<sup data-n=\"9205\">384</sup> העמוק[ה] הזאת עצמה שאז דוקא יובן אור השכל הזה שהוא הנמשל כחומר לצורה כמו גשמי' לרוחני' שצ\"ל בדומה לציור הרוחני' מעין ודוגמתו ממש, שהרי משל הזה דוקא הוא דומה לנמשל ולא משל אחר שאינו מעין ודוגמא לשכל הזה, ולפ\"ז הרי יובן ממילא שכאשר צריך אדם להלביש איזה שכל וחכ' עמוקה במשלי' גשמי' כדי <span data-k=\"pg\">550</span> ּ שיבינו אותו עומק החכ' ודאי מוכרח למצוא אופן וענין המשל שיהי' בדומה לנמשל ממש וא\"ל לא יובן הנמשל כלל, וא\"כ הרי יובן ממילא שלא יוכל אדם אחר לכוון אופן המשל בכי טוב שיהי' דומה ממש לנמשל זה אם אינו יודע בטוב לעומק אותו השכל והחכ', והיינו שלא המציא הוא עצמו ממקור השכל שאינו יודע במקור העומק שלו רק מי שהוא המציא לשכל ממקור[ו] שיודע הוא לבד באופן תוכן ועומק זה של השכל הזה אדם הזה דוקא הוא שיוכל למצוא [משל להלבישו כדוגמתו ו]צורתו ממש בלי נטייתו ימין ושמאל כלל, וכמו משלי שלמה לפי ששלמה הי' חכם גדול והי' יודע במקור אופן עומק החכ' כמו שהיא נמשכת מלמעלה [הי'] יודע למצוא אופן המשלים שיהיו מכוונים לנמשל ממש כו' וד\"ל.\n<b>ולפ\"ז</b> הרי יובן עכ\"פ שאותו עומק השכל והחכ' ואופן המשל הצריך לזה להלביש[ו] שניהם ממקור א' באו וממקום א' הן נמשכות כא', דהיינו מאותו מקור שהמציא אור שכל זה מן ההעלם לגילוי מאותו המקור עצמו הוא שנמצא בחי' לבוש הנמשל<sup data-n=\"9206\">385</sup> מעין ודוגמא לנמשל להלבישו (ומ\"מ אופן לבוש המשל להלביש ולכסות על אור השכל צריך שיבא ממקום גבוה יותר ממקום<sup data-n=\"9207\">386</sup> זה שמשפיע לשכל ההוא וא\"ל לא הי' מוצא לבוש [כ]זה דוקא להלבישו בדוגמתו ממש שישתמר בתוכו שזהו",[["9204","383","<b>ולא קרב זא\"ז כל הלילה</b>: בשלח יד, כ."],["9205","384","<b>השכל והחכ'</b>: ויז: החכ'."],["9206","385","<b>הנמשל</b>: שם: המשל."],["9207","386","<b>ממקום</b>: שם: ממקור."]]],[2300540679,"מבחי' מקיף בהעלם [ה]מקור של השכל הזה (וכמו דוגמא לזה מכח ההסבר להביא נקודה דחכ' להשגה יותר גבוה ממקור החכ' דנקודה והוא קוץ העליון כו' שנק' נבון שמבין דבר<sup data-n=\"9208\">387</sup> מתוך<sup data-n=\"9209\">388</sup> כו' וכמו והבן בחכ'<sup data-n=\"9210\">389</sup> כמ\"ש במ\"א) והוא [מבחי'] החשך והעלם דחכ' עצמו קודם שממשיך החכ' לגילוי אור כו'). וראי' לזה ממה שאנו רואים דאין לבוש המשל מסתיר על אור זה השכל רק לזולתו לגבי המקבלים לבד, אבל להחכם בעצמו שהמציא את החכ' והמשיל את לבוש המשל אין המשל מסתיר לו כלל כי ממקור א' יצאו [אצלו] מתעלומות מקור החכ', וזהו עיקר הטעם ושבח משלי שלמה דוקא שמורים על בחי' מקור החכ' שלו כנ\"ל וד\"ל (וכך יובן בענין אור דתורה מה שהוא נק' משל הקדמוני זהו מחמת התלבשות אור הח\"ע דתוה\"ק בלבושים גשמי' דדצח\"[ם] בעוה\"ז בעה\"ד טו\"ר לברר כו', והוא בחי' הנגלה שבתורה שנק' משל לאור הגנוז בה מח\"ע דתו' אור ממש כנ\"ל, ואמנם אין בחי' המשל [ו]לבוש דאור דתו' מסתיר כלל על בחי' האור דח\"ע הגנוז בה, וראי' ממ\"ת ששמעו דברים פשוטים דלא תרצח ולא תגנוב<sup data-n=\"9211\">390</sup> כו', וכללות הדברות המה בבחי' לבושי' כלבוש המשל, וכמו כל המצות שהן <sup data-n=\"9212\">391</sup>כל בחי' לבושי' והעלמות ועכ\"ז לא הסתיר להם על האור הגנוז וח\"ע שבעשה\"ד, שהרי על כל דבור פרחה נשמתן<sup data-n=\"9213\">392</sup> כו', וגם עכשיו הנגלות לנו ולבנינו<sup data-n=\"9214\">393</sup> כו', ואין זה בחי' לבוש מסתיר על הנסתרות שבה שהן סודות התו' וטעמי המצות שהרי בימוהמ\"ש יתגלו כל טעמי המצות<sup data-n=\"9215\">394</sup> שנק' סוד הוי' שגנוז ונעלם עכשיו בכל מצוה כו' וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"9216\">395</sup> כו' וכמ\"ש במ\"א). ומענין הנ\"ל במשל ונמשל מובן שיש שרש לנגלה שבתו' למעלה משרש האור דח\"ע<sup data-n=\"9217\">396</sup> שגנוז בה מטעם שמעצמו' א\"ס ב\"ה שהאיר אור דתורה בתחלה כשא' יהי אור קדמאה הוא עצמו שהמשיל והלביש לאור זה בנגלה דתו' <span data-k=\"pg\">רעה</span> ּ שיהי' מכוון ממש כפי הצורה דאור הנמשל כו' שאין יכולת זו בזולתו שלא ידע בעומק החכ' דתו' אור (רק משה הי' בכל ביתו נאמן<sup data-n=\"9218\">397</sup> כו' [ל]כך תו' צוה לנו משה<sup data-n=\"9219\">398</sup> בלבושו הגשמי' כפי הוראת הנסתר כו'). והנה בהקדמה זאת יתורץ קושי' הנ\"ל במ\"ש ויהי הענן והחשך ויאר כנ\"ל מאחר שהחשך עצמו האיר למה לא קרב זא\"ז כו', דהנה בחי' העלם וחשך דענן זה זהו בהעלם אור דחכ' בלבוש דמשל המסתיר כנ\"ל ואמנם יש במשל דבר והיפוכו שלגבי הממציא השכל והמשל אין המשל מסתיר כלל ולזולתו שאינו יודע בעומק השכל מסתיר לגמרי כו', כך הוא ענן וחשך זה עצמו האיר לישראל (כמשל אור דתו' אור שאינו בחי' הסתר כלל לנש\"י) ולמצרים הי' חשך והסתר גמור כלבוש הגס דמשל שמסתיר על האור דחכ' למי שאינו יודע בעומק החכ' כלל (וכמ\"ש ולחשך קרא לילה<sup data-n=\"9220\">399</sup> (כמשי\"ת), וכמו משל דתו' שלמיימינים בה סמא דחיי<sup data-n=\"9221\">400</sup> ולמשמאילים בה",[["9208","387","<b>נבון שמבין דבר</b>: חגיגה יד, א. ראה מאמרי אדה\"א דברים ח\"ד ע' א'שמה ואילך. לקמן פ' תצוה שסז, ד."],["9209","388","<b>מתוך</b>: ויז: ליתא."],["9210","389","<b>והבן בחכ'</b>: נסמן לעיל פ' שמות יג, א."],["9211","390","<b>דלא תרצח ולא תגנוב</b>: יתרו כ, יג."],["9212","391","<b>כל</b>: ויז: רק."],["9213","392","<b>על כל דבור פרחה נשמתן</b>: נסמן לעיל סט, א."],["9214","393","<b>הנגלות לנו ולבנינו</b>: נצבים כט, כח."],["9215","394","<b>בימוהמ\"ש יתגלו כל טעמי המצות</b>: ראה רש\"י שה\"ש א, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. שער האמונה ג, ב הערה 10."],["9216","395","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["9217","396","<b>שרש לנגלה שבתו'. . דח\"ע</b>: ראה גם ש\"א נח, ב."],["9218","397","<b>משה הי' בכל ביתו נאמן</b>: בהעלותך יב, ז."],["9219","398","<b>תו' צוה לנו משה</b>: ברכה לג, ד."],["9220","399","<b>ולחשך קרא לילה</b>: בראשית א, ה."],["9221","400","<b>שלמיימינים בה סמא דחיי</b>: שבת פח, ב."]]],[2300540691,"כו' כמ\"ש במ\"א בענין נגוף ורפוא<sup data-n=\"9222\">401</sup> כו'). כי הנה ידוע בשרש יעקב ועשו למעלה דעשו הוא הבכור<sup data-n=\"9223\">402</sup> שיצא ראשון בתולדה, ובזריעה הי' טפת יעקב ראשון משל לשפופרת<sup data-n=\"9224\">403</sup> סתומה מצד א' שה[נ]כנס ראשון יצא אחרון וה[נ]כנס אחרון יצא ראשון כו', ולזה יעקב הוא הבכור באמת ונק' ראשית אונו<sup data-n=\"9225\">404</sup> בזריעה אך בתולדה ויציאה עשו יצא ראשון ונק' בכור פטר רחם לאמו ולא יעקב כמ\"ש במ\"א.\n(יא) <b>והנה</b> כך הוא למעלה דיעקב איש חלק<sup data-n=\"9226\">405</sup> שרשו למעלה באור העצמ[ו'] שלפני החשך דישראל עלו במח'<sup data-n=\"9227\">406</sup> ראשון ועשו<sup data-n=\"9228\">407</sup> אחרון שהוא בחי' חשך שנק' מק\"פ וחלל כו' שקדם לאור והוא בחי' התהו שקדם לאור דתיקון<sup data-n=\"9229\">408</sup> כידוע. וזהו שבגילוי האור מן ההעלם בחי' ההעלם קדם לגילוי כמו צמיחת הקליפה שקדמה [לצמוח ואח\"ח צומח ה]פרי<sup data-n=\"9230\">409</sup> שזהו בצמיחה דוקא ולא בזריעה כו', ואחר צמיחת הקליפה בגמר[ה] אח\"כ נגמר הפרי, וכשנגמר הפרי בבישול [כל צרכו] אז נעשה הקליפה קשה יותר וזורק לחוץ כו', או שנופלת מאלי' כו' כמ\"ש במ\"א וד\"ל. וזהו ואלה המלכים<sup data-n=\"9231\">410</sup> כו' לפני מלוך מלך כו' שהן בחי' ז' מלכים דתהו שקדמו לבחי' התיקון בחשך שקד[ם] לאור ונמצא למעלה שרש עשו הוא בבחי' ההעלם שקדם לגילוי אור. אמנם שרש האור שאחר החשך הוא באור העצמו' שלפני החשך, וזהו שרש האור דקו\"ח שהוא בעצמו' אוא\"ס דוקא שלפני הצמצום הראשון דמק\"פ כנ\"ל, שזהו שרש יעקב כו'. וזהו יעקב אותיות יבקע<sup data-n=\"9232\">411</sup> שבוקע החשך עצמו ונגלה האור מן ההעלם והיינו מה שיוכל לעשות מחושך עצמו אור (וכמו בע\"ת שמהפכים חשוכא עצמו לנהורא<sup data-n=\"9233\">412</sup>, וזהו דוקא ע\"י צדיקים שנעשי' בע\"ת כמו תשובה ומע\"ט<sup data-n=\"9234\">413</sup> דוקא ולא ע\"י תשובה לבד מטעם שא\"א להיות הפך חשך העליון לאור כ\"א ע\"י צ\"ג<sup data-n=\"9235\">414</sup> ששרשם באור העצמ[ות] ממש אע\"פ שיצאו אח\"כ אחר ההעלם וצמצום דחשך סתרו כו', וע\"כ אין לבוש והעלם דחשך מסתיר [להם] כלל וד\"ל (וע\"כ מטעם זה עצמו גם לבוש דתו' שנק' משל הקדמוני אין מסתיר להם כלל ולא עוד אלא שנעשה להם בחי' דרך להוי' ונק' דרכי הוי'<sup data-n=\"9236\">415</sup> ממש, [ש]זהו כמו הנותן בים דרך<sup data-n=\"9237\">416</sup> כו' שהי' [ה]מסילה ביבשה בתוך הים בקי\"ס (כמשי\"ת). והנה מובן <span data-k=\"pg\">552</span> ּ מזה עכ\"פ דאע\"פ ששרש עשו בחשך שקדם לאור (שהוא מקו\"פ כו') מ\"מ שרש יעקב למעלה מחשך זה כנ\"ל, והוא יתרון מעלת האור דקו\"ח שיוכל להיות בו דבר והיפוכו לאכללא<sup data-n=\"9238\">417</sup>",[["9222","401","<b>נגוף ורפוא</b>: ראה לעיל פ' בא פח, ד ואילך."],["9223","402","<b>דעשו הוא הבכור</b>: תולדות כה, כה."],["9224","403","<b>משל לשפופרת</b>: ראה ב\"ר פס\"ג, ח. הובא ברש\"י תולדות כה, כו. מאמרי אדה\"א דברים ח\"ב ע' תקעא וע' תקצה. תו\"ח תולדות קפה, א ובהערה 10."],["9225","404","<b>ראשית אונו</b>: לשון הכתוב תצא כא, יז."],["9226","405","<b>דיעקב איש חלק</b>: תולדות כז, יא."],["9227","406","<b>דישראל עלו במח'</b>: נסמן לעיל פ' שמות לב, ב."],["9228","407","<b>דישראל עלו במח'. . ועשו</b>: נסמן לעיל קלה, א הערה 113."],["9229","408","<b>התהו שקדם. . דתיקון</b>: נסמן לעיל לט, ג."],["9230","409","<b>הקליפה שקדמה. . [ה]פרי</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א כאן (ס\"ע רט ואילך). וש\"נ. לעיל פ' בא פז, ד בהערה 40."],["9231","410","<b>ואלה המלכים</b>: ראה גם לעיל פ' שמות מג, ג. וש\"נ."],["9232","411","<b>יעקב אותיות יבקע</b>: נסמן לעיל יט, ג."],["9233","412","<b>לנהורא</b>: אוצ\"ל: לנהורא)."],["9234","413","<b>תשובה ומע\"ט</b>: ראה גם לעיל קס, ב. וש\"נ."],["9235","414","<b>צ\"ג</b>: יז: צדיקים גדולים."],["9236","415","<b>דרכי הוי'</b>: נסמן לעיל מא, א."],["9237","416","<b>הנותן בים דרך</b>: ישעי' מג, טז."],["9238","417","<b>דקו\"ח. . לאכללא</b>: ראה גם לעיל פ' שמות מח, ב. וש\"נ."]]],[2300540703,"כו'<sup data-n=\"9239\">418</sup> אור הגבורה בכלי החסד [כו'] שהוא עצמו אינו מן המדה ונק' קו המדה<sup data-n=\"9240\">419</sup> שמודד כל מדידה כו' כמ\"ש במ\"א בענין וי\"ו דוהנורא<sup data-n=\"9241\">420</sup> כו'.\n<b>ובזה</b> יתורץ דמה שהענן והחשך האיר אור<sup data-n=\"9242\">421</sup> הלילה זה הי' לישראל דוקא מטעם הנ\"ל, אבל הי' הסתר וחשך למצרים וזהו מצד ששרשם למעלה בבחי' החשך דתהו שקדם לאור כו' דגם שלמעלה ה\"ז במדרגה גבוה מבחי' האור, כי זהו בחי' ההעלם וההסתר דבחי' חשך סתרו שהוא בחי' העדר ההשפעה למטה כו', והאור שנמשך אחר ההעלם (אחר ההבדלה כנ\"ל) הוא למטה ממנו וכברייתו ש\"ע ברישא חשוכא כו', שהאור נמשך מבחי' החשך דוקא. אך כ\"ז כמו שהוא למעלה דוקא, אבל בהשתלשלו' וירידות המדרגות למטה מטה ממש אחר ההבדלה שהבדיל בין האור והחשך למטה הרי נהפ[ו]ך הוא דקרא לאור יום ולחשך קרא לילה שהוא בחי' החשך הגמור דלילה המסתיר על האור לגמרי והוא מ\"ש אלביש שמים קדרות ושק<sup data-n=\"9243\">422</sup> כו' שהוא בחי' [לבוש] שק דק\"נ כידוע וד\"ל. אמנם לישראל הי' הענן והחשך זה עצמו לאור כמו שאין בחי' לבוש [דמשל מלביש ו]מכסה על האור דנמשל כלל, להיות שהמשל עצמו נמשך ממקור האור דחכ' שהמשיך החכ' כו', כך בחי' ענן וחשך [זה] אינו מסתיר לישראל כי שרשם מבחי' אור דח\"ע<sup data-n=\"9244\">423</sup> המלובש במשל דחשמ\"ל העליון שאינו מסתיר למעלה כלל לגבי אור העצמי ממש (שמשם עיקר שרש נש\"י שעלו במח' כנ\"ל), לפי שבחי' החשך והסתר העליון הוא ג\"כ מבחי' העצמו' ממש דישת חשך סתרו כו' שמאותו המקום<sup data-n=\"9245\">424</sup> שמשם נמצא האור (וכענין אור וחשך [היו] משתמשין בערבוביא ) כמו<sup data-n=\"9246\">425</sup> דקמי' גם חשך לא יחשיך<sup data-n=\"9247\">426</sup> כחשיכה כאורה ממש, כמו שלגבי החכם בעצמו שוה המשל עם הנמשל יחד כו' ושניהם כא' באים ממקור א', ואדרבה הי' הענן והחשך לאור ממש (כמו שיבהיק לבוש זך ביותר וכמו בתורתו של ר\"מ (שא' ג' מאות משלים כו') הי' כתוב כתנות<sup data-n=\"9248\">428</sup> אור באל\"ף<sup data-n=\"9249\">427</sup> בחי' זיהרא עילאה ונק' מחלצות<sup data-n=\"9250\">429</sup> כו' וכמ\"ש עוטה אור כשלמה שהשלמה הזאת בהירה מן האור ויכולים לראות בה<sup data-n=\"9251\">430</sup> יותר בהבהקה כו'). אבל למצרים הי' חשך גמור להסת[י]ר לגמרי, ואין זה ב' הפכים כלל רק למטה שהאור והחשך מחולקים ולא יכול להיות החשך אור לזה וגם חשך לזה כו'. אבל הנה בחי' ענן ומלאך האלקי' הזה הרי הי' מאיר הדרך תחלה לפני מחנה ישראל מצד שרשם באור",[["9239","418","<b>כו'</b>: ויז: בו."],["9240","419","<b>קו המדה</b>: נסמן לעיל מא, א."],["9241","420","<b>וי\"ו דוהנורא</b>: ראה לעיל קנה, א ואילך. וש\"נ. כט, א. וש\"נ."],["9242","421","<b>אור</b>: ויז: את."],["9243","422","<b>אלביש שמים קדרות ושק</b>: נסמן לעיל א, ד."],["9244","423","<b>דח\"ע</b>: ויז: דחכ'."],["9245","424","<b>המקום</b>: שם: המקור."],["9246","425","<b>כמו</b>: שם: ליתא."],["9247","426","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["9248","428","<b>כתנות</b>: ויז: ליתא. וראה לעיל הערה 340."],["9249","427","<b>בתורתו של ר\"מ. . אור באל\"ף</b>: נסמן לעיל ח, ב."],["9250","429","<b>מחלצות</b>: ראה זהר שלח קסט, ב. פינחס ריד, א."],["9251","430","<b>עוטה. . שהשלמה. . ויכולים לראות בה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ריש ע' תקנד."]]],[2300540715,"הנגלה מתוך החשך דוקא וכמו משה נגש אל הערפל דוקא כו', וע\"כ גם בעמדם אחריהם הי' בהם ב' הפכים להאיר לישראל ולהחשיך למצרים לזה כפי שרשו למעלה בבחי' האור שאין החשך מסתיר כלל אדרבה יאיר גם הוא ולזה כפי שרשו מצרים בחשך המסתיר לאור ואין כאן ב' הפכים כלל וד\"ל.\n(יב) <b>וזהו</b> ויסע מלאך האלקי' ההולך לפני כו', שזהו בחי' ההסתר וההעלם דשם אלקי' שבמל' קודם שנעשה מקור לבי\"ע, וכשבחי' העלם והסתר זה מאיר אור זהו יתרון אור [גדול] בתוס' מרובה על עיקר האור שאחר הצמצום דחשך סתרו כנ\"ל מאחר [ש]העלם עצמו נעשה גילוי, ולזה כאשר עמד[ו] המלאך והענן מאחריהם והאירו <span data-k=\"pg\">רעו</span> ּ אור לישראל הי' זה בבחי' תוס' אור גדול מאשר הי' בהם בתחלה, מאחר שאין בחי' הפרסא מסתיר כלל (שזהו כמו שמשיגים מן המשל כל עומק אור השכל בתוס' גדול יותר מכמו שהיו משיגים בדבור). וזהו למעלה בחי' תוס' אור גדול בג' עולמות בי\"ע כאשר מאיר ההעלם דמל'<sup data-n=\"9252\">431</sup> בגילוי אור שזהו למעלה הרבה מכפי מדתם המצומצם שמקבלים מבחי' האור הנגלה עליהם מבחי'<sup data-n=\"9253\">432</sup> [מ]אותיות הדבור העליון, וכך הי' גילוי אור אלקי ביו\"ד מכות במצרים משם אלקי' שנהפך לגילוי אור וע\"כ [נ]תגלה שם הוי' המוסתר בשם אלקי' וכמ\"ש וידעו מצרים כי אני ה'<sup data-n=\"9254\">433</sup> כו'. ומזה הטעם הי' הכח ועוז לנש\"י לצאת מנש\"ט במצרים שזה לצאת מן החשך ואפילה לאור גדול שנק' היפך חשוכא לנהורא דוקא לפי שנהפך להם מבחי' חשך וצמצום העליון לאור (ועוד יש מדרגה למעלה מזו והוא שבחי' אור האצי' מאיר בבריאה כמו שהוא ממש שלא ע\"י מסך ופרסא כלל (כמשי\"ת), וז\"ש ועברתי באמ\"צ אני ולא מלאך ושליח כו' דגם חשך לא יחשיך כו' כנ\"ל), וג\"כ<sup data-n=\"9255\">434</sup> כדי שיוכל להיות קי\"ס שהוא היפך ההעלם [דים] העליון ליבשה ממש הוצרך להיות תחלה ענין זה שנסעו המלאך האלקי' והענן מפניהם ויעמדו מאחריהם, להיות מאיר לישראל מן החשך דוקא שזהו בחי' ההעלם דמל' דאצי' שבו נעשה הוא עצמו גילוי אור ואז הי' ג\"כ קי\"ס שנהפך הים ליבשה שהוא כמו בקיעת המסך ופרסא למעלה שנהפך לגילוי מן ההעלם כנ\"ל וד\"ל.\n<b>אך</b> הנה מבואר למעלה שהי' בקי\"ס ב' דברים היפך ים ליבשה ומסילה ודרך למטה כו', וגם עוד זאת הי' שבעברם בים ביבשה רדפו מצרים אחריהם ביבשה בתוך הים ולפי שכבר הבדיל המלאך והענן<sup data-n=\"9256\">435</sup> ביניהם ולא קרב זא\"ז כל הלילה טרם בואם לים כו', ע\"כ גם כשנכנסו ישראל לים באשמורת הבוקר ורדפו מצרים בים הי' אז ג\"כ מחיצה דענן וחשך זו המפסקת להאיר לישראל ולהחשיך למצרים. אך עכ\"ז הרי הי' למצרים",[["9252","431","<b>מאיר ההעלם דמל'</b>: ויז: מבחי' ההעלם דמל' יאיר."],["9253","432","<b>מבחי'</b>: שם: ליתא."],["9254","433","<b>וידעו מצרים כי אני ה'</b>: בשלח יד, ד. יח."],["9255","434","<b>וג\"כ</b>: ו: וגם כאן."],["9256","435","<b>והענן</b>: ויז: ליתא."]]],[2300540727,"במצב[ם] ובמעמד[ם] בחלק<sup data-n=\"9257\">436</sup> הים רודפים אחר ישראל, אע\"פ שלא הי' גילוי אור רק לישראל, ורצון הוי' הוא להעביר ממשלת פרעה ולהאבידם לגמרי מכל וכל והוא כאשר נטבעו בי\"ס, ועל דבר זה הוצרך להיות גילוי אור מעצמו' אוא\"ס שבאצי' שנתגלה בבקיעת הפרסא כמו שהוא באצי' ממש שלא ע\"י הארת אור הפרסא שהוא הענן והחשך ג\"כ, כי מה שמאיר מבחי' ההעלם והחשך דצמצום דשם אלקי' וענן כנ\"ל אע\"פ שמאיר בתוס' אור לישראל [ו]החשיך מאד למצרים <sup data-n=\"9258\">437</sup>כי יש להם יניקה ושרשם במ\"ח צירופי' האחרונים דשם אלקי'<sup data-n=\"9259\">438</sup> שנק' ארץ חם<sup data-n=\"9260\">439</sup> כו' וע\"כ הי' מצרים רודפים אחריהם בים, כי יש להם קיום מציאות משרשם בחיצוני' ואחוריי' דשם אלקי' (ואע\"פ שנהפך החשך [העליון] לאור אח\"כ גם להם באשמורת הבוקר כמ\"ש וישקף ה' על מחנה מצרים<sup data-n=\"9261\">440</sup> כו', זהו הי' בתערובות אור וחושך יחד כמו שהי' אור וחשך יחדיו תחלה משתמשי' בערבובי' קודם ההבדלה כנ\"ל) וזה הי' בעמוד אש וענן שזהו מבחי' האור שמאיר מעמוד האש ההולך לפני מחנה<sup data-n=\"9262\">441</sup> ישראל בלילה להאיר להם הדרך כו', וגם בענן זה שהזכיר תחלה שנסע מפניהם ויעמוד מאחריהם, ונמצא שנתחברו ב' הפכים עמוד אש וענן והשקיף על מחנה <span data-k=\"pg\">554</span> ּ מצרים שמפני זה נעשה מהומה גדולה ביניהם כמ\"ש ויהם את מחנה מצרים<sup data-n=\"9263\">442</sup>, אבל עכ\"ז לא נתבטלו ממציאותם לגמרי מכל וכל ממש עד שא' ויסר את אופן מרכבותיו<sup data-n=\"9264\">443</sup> דתבר שלטיהון למעלה שהוכרת<sup data-n=\"9265\">444</sup> שרש יניקתם למעלה משם אלקי' והוסר אופן מרכבותיו למעלה, וזהו רק מצד גילוי אור שם הוי' דאצי' בבריאה ויצי' כו' כמו שהוא ממש שלא ע\"י מסך ואור המאיר בפרסא שנק' ענן וחשך ולא ע\"י עמוד האש אלא מאוא\"ס עצמו שלמעלה מבחי' חשך ואור העלם וגילוי כו', וזהו שא' מצרים אנוסה מפני ישראל<sup data-n=\"9266\">445</sup> כי ה' עצמו נלחם להם במצרים כו', מפני שם הוי' עצמו נתבטלו לגמרי וד\"ל.\n<b>ונמצא</b> מובן מכ\"ז שהי' בקי\"ס ג' דברים הא' בקיעת הים מלמעלה כמ\"ש ויבקעו המים<sup data-n=\"9267\">446</sup> ונכלל בזה מה שנצבו כמו נד כו' כנ\"ל, והוא מה שבחי' [ה]העלם עצמו נעשה בחי' גילוי<sup data-n=\"9268\">447</sup> כאותיות המח' [ש]נעשה בבחי' אותיות הדבור בגילוי גמור שזהו הפך ים ליבשה, וזה נעשה מחמת שהי' עמוד הענן והחשך מאיר להם תוס' אור מן ההעלם דחשך סתרו כנ\"ל, וזהו כמו [ש]מתוך המשל דוקא יאיר אור השכל ולא [י]סתיר המשל כלל (וכמו מצות עכשיו שמלובשים בלבוש גשמי' ואין מסתיר <sup data-n=\"9269\">448</sup>כלל (וכמו כתנות או\"ר בא' כו'). והב' מה שנעשה מסילה ודרך ממש ביבשה בתוך הים מב' צדדי[ה]ם לעבור ברגלם זהו מה שנעשה בחי' כלי ממש לגילוי אור שבא מן החשך עד שנק' דרך הוי' ממש, וכמו לע\"ל שא' שכר מצוה",[["9257","436","<b>בחלק</b>: שם: בתוך."],["9258","437","<b>כי</b>: שם: ליתא."],["9259","438","<b>במ\"ח צירופי'. . אלקי'</b>: נסמן לעיל פ' שמות ל, ב."],["9260","439","<b>ארץ חם</b>: נסמן לעיל פ' שמות כ, ב."],["9261","440","<b>וישקף ה' על מחנה מצרים</b>: בשלח יד, כד [ושם: אל — וכ\"ה בו — ראה לעיל קסט, א. וש\"נ]."],["9262","441","<b>מחנה</b>: ויז: ליתא."],["9263","442","<b>ויהם את מחנה מצרים</b>: בשלח יד, כד."],["9264","443","<b>ויסר את אופן מרכבותיו</b>: נסמן לעיל פ' בא קכד, ג."],["9265","444","<b>שלטיהון למעלה שהוכרת</b>: ויז: שלשליהון לעילא שהוסר."],["9266","445","<b>אנוסה מפני ישראל</b>: בשלח יד, כה."],["9267","446","<b>ויבקעו המים</b>: בשלח יד, כא."],["9268","447","<b>גילוי</b>: ויז: דומם."],["9269","448","<b>כלל</b>: אוצ\"ל: כלל)."]]],[2300540739,"מצוה<sup data-n=\"9270\">449</sup> [עצמה] ש[י]הי' מבחי' לבוש דנוגה ובוא'<sup data-n=\"9271\">450</sup> להכיל אור שם הוי' ממש (כלבושי דכיא<sup data-n=\"9272\">451</sup> לנשמות בג\"ע עכשיו שהולכי' בהם למעלה בעילוי אחר עילוי [ו]כמ\"ש והלך לפניך צדקיך<sup data-n=\"9273\">452</sup> דוקא והן המקיפי' ששורים בלבושי' דמצות בעוה\"ז דוקא שנק' צל ימינו כו' כמו אך בצלם יתהלך איש כו', הרי כל הילוך ממדרגה למדרגה הוא ע\"י בחי' המקיף דצלם דוקא והיינו מלבוש דחשמ\"ל דנוגה שנעשה בהן המצות וכן ילכו מחיל כו' רק ע\"י בחי' מקיף דלבושי' הנ\"ל<sup data-n=\"9274\">453</sup> (וכמ\"ש במ\"א עמ\"ש בזהר ואברהם זקן<sup data-n=\"9275\">454</sup> בא בימים דיומין קריבו לי' כו'), וגם כאן שהלכו בנ\"י בתוך הים כו' וידוע דקי\"ס הי' [רק] הכנה למ\"ת<sup data-n=\"9276\">455</sup> בלבד והילוך זה ביבשה בתוך הים העליון זהו מה שיש הילוך בדרכי הוי' במצות שנעשי' מחשך העליון שנהפך לאור להיות בחי' כלי ודרך לשם הוי' ממש כמו לע\"ל כנ\"ל וד\"ל (וכך הוא קבלת עומ\"ש שלימה ש[ב]עול מצות דוקא שזהו לאכפייא ולאהפכא חשוכא לנהורא כו' בביטול רצון מפני רצונו כו' הוא ג\"כ [ענין] יתרון האור שמאיר מן החשך וההעלם דמל' יראת<sup data-n=\"9277\">456</sup> שמים דלעילא שנק' יראת הרוממות דסדכ\"ס כו' שנמשך ומתלבש בקבלת עומ\"ש זה בביטול היש לבד בקיום רצונו במצות שנק' יר\"ת שהוא כמו<sup data-n=\"9278\">457</sup> יר\"ע יראה בושת ומאיר מן ההעלם עצמו לגילוי כנ\"ל, וזהו והאלקי' עשה שייראו מלפניו<sup data-n=\"9279\">458</sup> האלקי' דוקא המצמצם לשם הוי' כאשר יאיר אור מן ההעלם הוא שעשה זה כדי שייראו מלפניו ממש בבחי' יר\"ע הנ\"ל רק שמלובש כעת בעול מצות ולע\"ל יתגלה כנ\"ל וד\"ל).\n<b>והענין</b> הג' בקי\"ס הוא למעלה גם מזה והוא שהי' מאיר גם בהילוך זה שהלכו ביבשה בתוך הים והיינו מדרגה הב'<sup data-n=\"9280\">459</sup> הנ\"ל שלמעלה גם מבחי' גילוי של ההעלם דחשך וענן הנ\"ל והוא בחי' גילוי אור דשם הוי' דאצי' כמו שהוא בבחי' האצי' ממש שלא ע\"י הארת אור מן המסך או ענן וחשך כלל אלא [אור] הוי' עצמו שלפני צמצום הראשון דחשך <span data-k=\"pg\">רעז</span> ּ סתרו דחשך ואור שוין שם ממש כנ\"ל, ומפני גילוי אור העצמ[ות] דשם הוי' זה בהגלותו בים על מצרים נתבטלו ממציאותם לגמרי וינוסו והוטבעו בים ונאבדו כי לא יכלו לעמוד במקום אור דעצמו' א\"ס ממש (כי אין שרשם רק משם אלקי' דצמצום הראשון כנ\"ל). והוא מ\"ש ויט משה את ידו<sup data-n=\"9281\">460</sup> על הים וישב הים לפנות בוקר לאיתנו [כו'] כי לא נתן למצרים לעבור ביבשה בתוך הים (וכמו לע\"ל שיתגלה אור העצמ[ות] דא\"ס שא' ולא יכנף",[["9270","449","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."],["9271","450","<b>ובוא'</b>: ויז: לבוש זך ובהיר (יז: וברור)."],["9272","451","<b>כלבושי דכיא</b>: ראה לעיל פ' שמות ז, ג. וש\"נ."],["9273","452","<b>והלך לפניך צדקיך</b>: ישעי' נח, ח."],["9274","453","<b>הנ\"ל</b>: ויז: הללו."],["9275","454","<b>ואברהם זקן</b>: ח\"ש כד, א. ראה זהר ח\"ש קכט, א."],["9276","455","<b>דקי\"ס. . הכנה למ\"ת</b>: נסמן לעיל קמח, ג."],["9277","456","<b>יראת</b>: ויז: ליתא."],["9278","457","<b>כמו</b>: שם: בחי'."],["9279","458","<b>והאלקי' עשה שייראו מלפניו</b>: קהלת ג, יד."],["9280","459","<b>הב'</b>: ויז: הג'."],["9281","460","<b>ויט משה את ידו</b>: בשלח יד, כז."]]],[2300540751,"עוד כו' אף לא ע\"י לבוש דמעשה המצות וקבלת עומ\"ש כו' כמו שהי' גילוי אור האצי' בבריאה בקי\"ס שלא ע\"י מסך כלל והוא שהלכו ביבשה שלא ע\"י לבוש כלל רק לאור הוי' עצמו הלכו כמו שעולים הנשמות בלי לבוש ועזר כלל כר\"ח רבה דמנפשי' עייל<sup data-n=\"9282\">461</sup> [כי תו' אומנתו<sup data-n=\"9283\">462</sup> ] כו') וכאסתר שלא בקשה דבר<sup data-n=\"9284\">463</sup> כו' (וכמ\"ש חנם בלא מצות<sup data-n=\"9285\">464</sup> כו'), ואפשר<sup data-n=\"9286\">465</sup> שמצרים נתבטלו ממציאותם מפני גילוי אור זה היינו מפני שה[י'] שרשם מבחי' החשך וראו אור גדול כזה שלא יוכלו להכיל[ו] כלל שממילא נתבטלו (וכמו במחנה סנחרב שנתבטלו מפני שהשמיע ה' את הוד קולו<sup data-n=\"9287\">466</sup> מבחי' מל' דא\"ס שלפני הצמצום כו' כמ\"ש במ\"א), אבל לישראל ששרשם מבחי' האור דעצמות א\"ס שלפני הצמצום הראשון (כנ\"ל בשרש יעקב איש חלק כו' שנק' ראשית אונו <sup data-n=\"9288\">467</sup>כו' לא הי' יתרון אור גדול הזה מזיק להם כלל ולא נתבטלו ממציאותם כלל אלא<sup data-n=\"9289\">468</sup> אדרבה נעשה להם אור לילך בו להיות להם מסילה ודרך ביבשה בתוך הים וזהו כמו שהמצוה עצמה נפשטה מן הלבוש הזך ובהיר (וכמו אור עומק השכל כמו שהוא במקורו קודם שמאיר אור החכ' מאין כו' אלא כמו שהוא בעצמו ממש שא\"צ למשל כלל וד\"ל.\n(יג) <b>והנה</b> מעתה יובן סדר כל הפסוקי' בפ' זאת דקי\"ס בתחלה א[מר] ה' ילחם לכם<sup data-n=\"9290\">469</sup> שלא ע\"י אתעדל\"ת כלל וכלל וכמ\"ש ואתם תחרישו\"ן לא תתערו מידי<sup data-n=\"9291\">470</sup> כו' (אף לא בתו\"מ ) מענין עוה\"ב<sup data-n=\"9292\">472</sup> ממש מטעם הנ\"ל<sup data-n=\"9293\">471</sup>, ואח\"כ א[מר] מה תצעק אלי<sup data-n=\"9294\">473</sup> דגם בחי' העלאת מ\"ן דתפלה וצעקה דמשה בביטול מ\"ה בעצם<sup data-n=\"9295\">474</sup> אינו מגיע לשם כלל, ואי' בזהר מה תצעק אלי בעתיקא תליא<sup data-n=\"9296\">475</sup> דקי\"ס הוא למעלה גם מבחי' הפרסא שבין כתר לחכ' שאין מדות ומוחין דחו\"ב מגיע לשם כלל כמובן מכל הנ\"ל, אך א[מר] לו ואתה הרם את מטך<sup data-n=\"9297\">476</sup> מטך<sup data-n=\"9298\">477</sup> דוקא ונטה את ידך על הים דים זה הוא בחי' ההעלם יהי' גילוי ע\"י אור העצמ[ות] דאוא\"ס<sup data-n=\"9299\">478</sup> שמאיר בפנימי' ע\"י דוקא שלמעלה גם מאור החכ'<sup data-n=\"9300\">479</sup> דח\"ס שנק' אור צח כו' כנ\"ל ובקעהו ליו\"ד דחכ[\"ס] שיצא מן ההעלם לגילוי אור [כ]חשך המאיר כנ\"ל, ואני אחזק<sup data-n=\"9301\">480</sup> כו' וידעו מצרים בגילוי אור הוי' עד שיתבטלו במציאות כמ\"ש ה' ילחם לכם כנ\"ל.\n<b>ועתה</b> מפרש בדרך פרט איך נעשה בזה [ו]הקדים תחלה הכנה לקי\"ס, והוא מה שנסע מלאך האלקי' ו[ה]ענן ויעמוד<sup data-n=\"9302\">481</sup>",[["9282","461","<b>כר\"ח רבה דמנפשי' עייל</b>: ראה בבא מציעא פה, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שעט. תקע\"א ע' קמד. מאמרי אדה\"א נ\"ך ע' תעח ובהנסמן בהנ\"ל."],["9283","462","<b>כר\"ח רבה. . תו' אומנתו</b>: ראה מאמרי אדה\"א שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670474\" data-slug=\"torat-chaim\" data-id=\"2300670474\">תו\"ח נח נה, א</a> ובהערה 8. שע\"ת פ, ג ובהערה 19."],["9284","463","<b>וכאסתר שלא בקשה דבר</b>: אסתר ב, טו."],["9285","464","<b>חנם בלא מצות</b>: נסמן לעיל פ' שמות א, ב."],["9286","465","<b>ואפשר</b>: ויז: ואעפ\"י."],["9287","466","<b>במחנה סנחרב. . הוד קולו</b>: נסמן לעיל פ' שמות ל, ג."],["9288","467","<b>כו'</b>: כנצ\"ל: כו')."],["9289","468","<b>אלא</b>: ויז: ליתא."],["9290","469","<b>ה' ילחם לכם</b>: בשלח יד, יד."],["9291","470","<b>ואתם תחרישו\"ן. . מידי</b>: נסמן לעיל קנז, ב."],["9292","472","<b>מענין עוה\"ב</b>: ו: כעין העוה\"ב. יז: כמו העוה\"ב."],["9293","471","<b>בתו\"מ). . הנ\"ל</b>: ויז: בתו\"מ. . הנ\"ל)."],["9294","473","<b>מה תצעק אלי</b>: בשלח יד, טו."],["9295","474","<b>דמשה. . מ\"ה בעצם</b>: ראה לעיל פ' שמות מג, א ובהערה 6."],["9296","475","<b>בזהר. . בעתיקא תליא</b>: זהר בשלח מח, א. נב, ב."],["9297","476","<b>ואתה הרם את מטך</b>: בשלח יד, טז."],["9298","477","<b>מטך</b>: ו: ונטה משה. יז: מטה משה."],["9299","478","<b>דאוא\"ס</b>: שם: דא\"ס."],["9300","479","<b>החכ'</b>: שם: הכתר."],["9301","480","<b>ואני אחזק</b>: בשלח יד, יז [ושם: הנני מחזק]."],["9302","481","<b>ויעמוד</b>: ויז: ויאירו."]]],[2300540763,"מאחריהם שזהו האו\"ח העולה מלמטה למעלה [מ]אחריהם דוקא וכמו אחרי הוי'<sup data-n=\"9303\">482</sup> כו' לכתך אחרי<sup data-n=\"9304\">483</sup> בלבוש דמצות שיאירו אור מן ההעלם והחשך והענן כמ\"ש ויאר את הלילה<sup data-n=\"9305\">484</sup>, והוא עצמו המחשיך לבחי' הרע [ד]נפש הטבעית שלא יקרב גם הוא לבחי' הטוב וזהו ויבא בין מחנה מצרים כו' ולא א' בין מחנה ישראל כי הי' המלאך מבדיל בין מחנה מצרים, כי מה שהי' אור מן החשך לישראל זה הי' רק מחשך המחשיך <span data-k=\"pg\">556</span> ּ למצרים שנהפך החשך [ה]זה עצמו לאור לישראל, וכמו שנהפך הרע עצמו לטוב שאז נק' [מה\"מ] טוב מאד<sup data-n=\"9306\">485</sup> יותר ממלאך החיים והוא ע\"י [ה]תשובה שהי' פרעה מקריב לבם<sup data-n=\"9307\">486</sup> לאביהם שבשמים כו' כמ\"ש ויצעקו בנ\"י אל הוי'<sup data-n=\"9308\">487</sup> כו', וא\"כ האור הזה לישראל לא הי' רק מבחי' חשך גמור דמצרים שנהפך להם לאור זה[ו] יתרון האור מן החשך דוקא ע\"כ א' בין מחנה מצרים תחלה ואח\"כ א' ויהי הענן והחשך למצרים ויאר את הלילה<sup data-n=\"9309\">488</sup> היינו הענן והחשך עצמו דלא כפרש\"י<sup data-n=\"9310\">489</sup> שאין כאן ב' הפכים כלל לפי שעי\"ז הי' היפך חשך העליון לאור כנ\"ל וד\"ל. ואח\"כ ויט משה את ידו על הים ויולך ה' את הים ברוח קדים עזה מקדמונו של עולם<sup data-n=\"9311\">490</sup> קדמון לכל הקדומים<sup data-n=\"9312\">491</sup>, והוא בחי' רוח אלקי' מרחפת דמשיח<sup data-n=\"9313\">492</sup> שיגלה כל סוד והעלם העליון דח\"ס [ו]למעלה מעלה כמ\"ש ישכיל עבדי כו', וע\"כ נבקעו המים עליו[נים] דח\"ע שבהעלם העצמי' דאוא\"ס<sup data-n=\"9314\">493</sup> שנק' סדכ\"ס כו' וכמים שמעל לשמים<sup data-n=\"9315\">494</sup> [ד]ארובות השמים נפתחו<sup data-n=\"9316\">495</sup> בימוהמ\"ש כולם ידעו אותי<sup data-n=\"9317\">496</sup> כו'. וגם בחי' רזא דרזין שנק' סוד סתום דטעמי המצות יתגלו וא\"כ יהי' ההעלם גילוי כניסים ונפלאות דעכשיו שיבא[ו] [ב]גילוי ממש<sup data-n=\"9318\">497</sup> כמו דרך הטבע ממש כמ\"ש אראנו נפלאות (כמשי\"ת). אך [עכ\"ז] הרי יש מקום יניקה ושרש עדיין גם לבחי' הרע דק\"נ וע\"כ א[חר] שבאו בנ\"י בים והמים להם חומה כו' וירדפו מצרים כו' שגם הם יכלו לילך ביבשה זו בתוך הים העליון, וזהו ויבאו אחריהם כל סוס פרעה<sup data-n=\"9319\">498</sup> אותיות<sup data-n=\"9320\">499</sup> דק\"נ שכלולים בסוס א'<sup data-n=\"9321\">500</sup> שמקבל מסוס דקדושה כמ\"ש והי' מצהלות הסוס<sup data-n=\"9322\">501</sup> קדש לה' כו', אבל באשמורת הבוקר, בוקר דלע\"ל ביום הז', וישקף ה' על מחנה [מצרים] כו' וכמו אז אהפוך אל עמים<sup data-n=\"9323\">502</sup> כו' כמ\"ש ויהם את כו', ולעוה\"ב יהי' הבירור השלם בין צדיקים לרשעים כמ\"ש אלה לחיי עולם ואלה לחרפות ודראון עולם<sup data-n=\"9324\">503</sup>, וזה הי' בקי\"ס<sup data-n=\"9325\">504</sup> מעין עוה\"ב שהרי א' זה אלי ממש וראתה שפחה כו' (כמשי\"ת) והוא מ\"ש ויסר את אופן מרכבותיו כו'. ואח\"כ א' ויט משה את",[["9303","482","<b>אחרי הוי'</b>: פ' ראה יג, ה."],["9304","483","<b>לכתך אחרי</b>: ירמי' ב, ב."],["9305","484","<b>ויאר את הלילה</b>: בשלח יד, כ."],["9306","485","<b>[מה\"מ] טוב מאד</b>: נסמן לעיל פ' בא קכג, ג."],["9307","486","<b>שהי' פרעה מקריב לבם</b>: נסמן לעיל קלח, ג הערה 310."],["9308","487","<b>ויצעקו בנ\"י אל הוי'</b>: בשלח יד, י."],["9309","488","<b>את הלילה</b>: ויז: לישראל."],["9310","489","<b>דלא כפרש\"י</b>: בשלח יד, כ."],["9311","490","<b>ברוח קדים עזה מקדמונו של עולם</b>: נסמן לעיל קמג, ב."],["9312","491","<b>קדמון לכל הקדומים</b>: ת\"ז תי\"ט (מב, א). ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תנט."],["9313","492","<b>רוח אלקי' מרחפת דמשיח</b>: נסמן לעיל פ' שמות מז, א."],["9314","493","<b>דאוא\"ס</b>: ויז: דא\"ס."],["9315","494","<b>וכמים שמעל לשמים</b>: בראשית א, ז. תהלים קמח, ד."],["9316","495","<b>[ד]ארובות השמים נפתחו</b>: נח ז, יא."],["9317","496","<b>כולם ידעו אותי</b>: נסמן לקמן בהערה 515."],["9318","497","<b>ממש</b>: ויז: ליתא."],["9319","498","<b>ויבאו אחריהם כל סוס פרעה</b>: בשלח יד, כג."],["9320","499","<b>סוס. . אותיות</b>: ראה לעיל קסג, א ובהערה 69."],["9321","500","<b>א'</b>: ו: אחד אחר."],["9322","501","<b>והי' מצהלות </b>[ויז: מצילות]<b> הסוס</b>: זכרי' יד, כ [ושם: ביום ההוא יהי' על מצלות הסוס]."],["9323","502","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["9324","503","<b>אלה לחיי עולם. . ודראון עולם</b>: דניאל יב, ב [ושם: לדראון — ראה לקמן ריד, ד]."],["9325","504","<b>בקי\"ס</b>: ויז: ליתא."]]],[2300540775,"ידו כו' שזהו בחי' הטי' שני' להשיב את הים לאיתנו שהוא יתרון<sup data-n=\"9326\">505</sup> גדול מהטי' הא' לבקיעת הים כו' ([כ]גילוי ההעלם וסודות התו'), לפי שבעוה\"ב יהי' דוקא גילוי אור העצמ[ו'] ממש דקמי' ממש כחשיכה כאורה [ממש] ויכולים הכל לקבל גם חשך דק\"נ וכמ\"ש מה נשתנו [אלו]<sup data-n=\"9327\">506</sup> כו', וזהו שביקש משה ונפלינו אני<sup data-n=\"9328\">507</sup> כו' שיבחר לנו את נחלתינו אף בעצם רוממות דא\"ס למעלה מן הברירה<sup data-n=\"9329\">509</sup> דגורלות דיו\"כ<sup data-n=\"9330\">508</sup> מבעל הרצון עצמו כמ\"ש במ\"א וכמ\"ש ואלה לחרפות עולם, וזהו הטי' הב' להשיב את הים לכסות את כל חיל פרעה כו' וד\"ל.\n(יד) <b>והנה</b> להבין ביאור הענין, הנה י\"ל ענין הבקיעה דמל' במסך שזהו בחי' הארת אור האצי' בבריאה שלא ע\"י מסך כלל כנ\"ל, שזהו למעלה גם מבחי' בירור הלבושים דמצות שיהי' לע\"ל וכמ\"ש ולא יכנף עוד מוריך אלא כמו שהוא בעצמו דוקא שא\"צ למשל כלל כנ\"ל (כמשי\"ת). ויש להבין דאיך אפשר שיהי' אור האצי' בבריאה כמו שהוא בלי בחי' צמצום כלל דא\"כ הי' הבריאה מתבטלת לגמרי ונכללת באצי' כנ\"ל דבלתי ב' סיבות דב' בחי' אין [ו]ע\"י פרסא א\"א להיות <span data-k=\"pg\">רעח</span> ּ מציאת יש מיש האמיתי כנ\"ל כמובן מכל המשלים הנ\"ל, ואם מפני שבקי\"ס הי' מאיר [האור] מבחי' העצמו' ממש שלמעלה מהעלם וגילוי דחשך ואור כנ\"ל, אבל בחי' האצי' ממש הרי זה אור העצמו' דא\"ס באצי' איך יקובל בנשמות דבריא' וישארו במציאותם המוגבלת כו'. אך הנה ארז\"ל דראתה שפחה על הים מה שלא ראה יחזקאל הנביא כו', וזהו פלא דאיך יכול להיות גילוי אלקו' בשפחה גשמי' יותר מגילוי הנבואה בנביא כיחזקאל<sup data-n=\"9331\">510</sup> שהי' נשמתו מעולם האצי'<sup data-n=\"9332\">511</sup> וגופו מופשט הי' מגשמי' כו', ועוד מהו שא' בפרט כיחזקאל דוקא<sup data-n=\"9333\">512</sup>. אמנם הכוונה בכלל [ב]מאמר הזה הוא מפני שהי' בקי\"ס גילוי עצמות אלקות מעין שיהי' לע\"ל בעוה\"ב<sup data-n=\"9334\">513</sup> וע\"כ היו כולן שוין בגילוי אור גדול זה ואפי' שפחה (כענין שכתוב אפי' עוברי' [ש]במעי אמן אמרו שירה<sup data-n=\"9335\">514</sup> [זו] כו') לפי שא' זה אלי לנוכח (וכמו לע\"ל שא' כולם ידעו אותי מקטנם ועד גדולם<sup data-n=\"9336\">515</sup> כו'). ובאמת דבר זה א\"א כי ודאי הי' גדולי הדור כזקני ישראל משיגים באור זה עצמו יותר מזולת[ם] וכ\"ש שא\"א ששפחה ראתה [כמוהם] כו'. אך עיקר הענין הוא לפי שהי' בקרי\"ס הארת אור האצי' בבריאה כמו שהוא בלי<sup data-n=\"9337\">516</sup> בקיעה כנ\"ל וע\"כ אפי' שפחה ראתה מה שלא ראה יחזקאל.",[["9326","505","<b>יתרון</b>: שם: יותר."],["9327","506","<b>מה נשתנו [אלו]</b>: נסמן לעיל פ' בא פח, ד."],["9328","507","<b>ונפלינו אני</b>: תשא לג, טז."],["9329","509","<b>הברירה</b>: ויז: הבחירה."],["9330","508","<b>שיבחר לנו. . דגורלות דיו\"כ</b>: ראה גם לעיל פ' בא צ, ד. וש\"נ."],["9331","510","<b>דראתה שפחה. . בנביא כיחזקאל</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שכב."],["9332","511","<b>כיחזקאל שהי' נשמתו מעולם האצי' </b>[גו: היצירה]: ראה בסמוך ובהערה 531."],["9333","512","<b>כיחזקאל דוקא</b>: ראה גם לעיל קמח, ד. מאמרי אדה\"א ויקרא שם."],["9334","513","<b>בקי\"ס. . מעין. . בעוה\"ב</b>: ראה גם לעיל קעח, א ובהנסמן שם."],["9335","514","<b>שכתוב </b>[ויז: שאמ']<b> אפי' עוברי'. . שירה</b>: ראה מכילתא בשלח טו, א. ברכות נ, א."],["9336","515","<b>כולם. . מקטנם ועד גדולם</b>: ירמי' לא, לג. ראה לעיל פ' שמות לח, ג בהערה 47."],["9337","516","<b>בלי</b>: ויז: (ש)נק'."]]],[2300540786,"<b>ויובן</b> זה ע\"פ הידוע בביאור המאמר בהפרש שבין נבואת משה לנבואת כל הנביאים<sup data-n=\"9338\">517</sup> שכל הנביאים [נתנבאו] בכה<sup data-n=\"9339\">518</sup> כה אמר ה'<sup data-n=\"9340\">519</sup> כו' שכה זה הוא בכ\"ף הדמיון [לבד] וכמ\"ש ביד הנביאים אדמה<sup data-n=\"9341\">520</sup> כו' וכתיב הן במראה<sup data-n=\"9342\">521</sup> אליו אתוודע בחלום כו', אבל משה נתנבא בזה<sup data-n=\"9343\">522</sup> כו'. וביאור הענין הנה ידוע דבחי' המל' שמהוה<sup data-n=\"9344\">523</sup> הברואי' מאין ליש זהו בבחי' הארה דהארה בלבד מה שמתגלה רק בצירופי אותיות [הדיבור] העליון שנק' מראה דמות כבוד הוי'<sup data-n=\"9345\">524</sup> דאצי' שאינו יודע<sup data-n=\"9346\">525</sup> רק בחי' מראה [ו]דמות כבוד הוי' דאצי' עצמו, כמ\"ש בזהר במ\"ש בצלמנו כדמותנו [ד]צלם בדכורא<sup data-n=\"9347\">526</sup> בחי' האצי' ממש כדמותנו<sup data-n=\"9348\">527</sup> בנוק' כו' שזהו במל' דאצי' שנעשה מקור לבי\"ע<sup data-n=\"9349\">528</sup>, והוא ע\"י [בחי'] צמצום ולבוש [ד]פרסא הנ\"ל דוקא וכמו שאור המאיר דרך מסך שאינו אלא קצת דוגמא לאור העצמי כנ\"ל. ואמנם אעפ\"כ בהתלבשות אור זה בגילוי הנבואה בנביאים א' וביד הנביאים אדמה בדמיון שהוא העלם המח' הזכה והטהורה של הנביא ההוא כמו שהוא בשרשו א[ם] מבריאה או מיצי' כו', וזהו הן במראה שמראה זה דברים הנגלים<sup data-n=\"9350\">529</sup> בנשמתו רק כפי שרשו בלבד כמו לישעי' [ב]בחי' עולם הבריאה<sup data-n=\"9351\">530</sup> וליחזקאל [ב]בחי' היצי'<sup data-n=\"9352\">531</sup> שמפני זה ראה רק מרכבה דיצי' כו' וכמ\"ש ישעי' דומה לבן כרך<sup data-n=\"9353\">532</sup> שראה את המלך ויחזקאל לבן כפר (כמ\"ש במ\"א). וז\"ש שכל הנביאים נתנבאו בכה כו' בכ\"ף הדמיון שזהו התלבשות בחי' המל' בלבושים והעלמות בכל נברא<sup data-n=\"9354\">533</sup> לפי שרשו, וע\"כ היו הנביאים בעת הגיע אליהם אור הנבואה היו<sup data-n=\"9355\">535</sup> מופשטי' מגשמיות<sup data-n=\"9356\">534</sup> ונפלו על פניהם כאבן דומם מבלי הרגשת חיות ותנועה כלל [כי] היו צריכים להתפשט מלבוש החומר שלהם כדי שיוכלו לקבל גילוי אור האלקי דבחי' המל' ממש (כי הי' אור המל' מתגלה להם יותר מכמו שמתגלה בעולמו' ובמרכבה העליונה ע\"י העלם המסך המפסיק כו', שאם לא הי' האור האלקי מאיר להם רק כפי סדר ההשתל' ע\"י צמצום המסך לא היו מתבטלים כ\"כ). אך הנה משה נתנבא בזה הדבר <span data-k=\"pg\">558</span> ּ כו', פי' זה לשון דכר שהוא במדרג' שם הוי' דאצי' ממש כמו שהוא טרם שמתעלם ומתלבש בלבוש דשם אלקי' במל' כו' שלא ע\"י התלבשות במסך כלל שזהו בלא דמיון ומראה כלל [ו]כמ\"ש לא כן עבדי משה<sup data-n=\"9357\">536</sup> פא\"פ אדבר בו<sup data-n=\"9358\">537</sup> כו', ועוד זאת מעלה יתירה הי' בו שלא הי' נופל על פניו כלל בגילוי אור הוי' בנשמתו כי לא הי' צריך להתפשט מגופו כלל שהרי אמר ולא קם נביא עוד כמשה אשר ידעו ה' פא\"פ<sup data-n=\"9359\">538</sup> במדרגה",[["9338","517","<b>בהפרש שבין נבואת משה. . הנביאים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670123\" data-slug=\"torat-chaim\" data-id=\"2300670123\">תו\"ח בראשית לה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670188\" data-slug=\"torat-chaim\" data-id=\"2300670188\">נח מח, ג</a>."],["9339","518","<b>שכל הנביאים [נתנבאו] בכה</b>: נסמן לעיל קמד, ב."],["9340","519","<b>כה אמר ה'</b>: יהושע ז, יג. ועוד."],["9341","520","<b>ביד </b>[ו: וביד]<b> הנביאים אדמה</b>: נסמן לעיל צט, ב."],["9342","521","<b>הן במראה</b>: נסמן לעיל קמד, א."],["9343","522","<b>משה נתנבא בזה</b>: נסמן לעיל בהערה 518."],["9344","523","<b>שמהוה</b>: ויז: שמחי'."],["9345","524","<b>מראה דמות כבוד הוי'</b>: נסמן לעיל פח, ב."],["9346","525","<b>יודע</b>: ויז: ליתא."],["9347","526","<b>בצלמנו כדמותנו [ד]צלם בדכורא</b>: בראשית א, כו. ראה זהר שמיני לה, סע\"ב."],["9348","527","<b>כדמותנו</b>: ויז: ודמות."],["9349","528","<b>לבי\"ע</b>: שם: לבריאה כנ\"ל."],["9350","529","<b>דברים הנגלים</b>: שם: דבחי' המל' יתגלה."],["9351","530","<b>לישעי'. . הבריאה</b>: נסמן לעיל קיד, ג."],["9352","531","<b>וליחזקאל. . היצי'</b>: נסמן לעיל שם."],["9353","532","<b>ישעי' דומה לבן כרך</b>: ראה חגיגה יג, ב."],["9354","533","<b>נברא</b>: ויז: נביא."],["9355","535","<b>היו</b>: ויז: ליתא."],["9356","534","<b>הנביאים. . מופשטים מגשמיות</b>: ראה גם לעיל פ' בא צז, ד. וש\"נ."],["9357","536","<b>לא כן עבדי משה</b>: בהעלותך יב, ז."],["9358","537","<b>פא\"פ אדבר בו</b>: בהעלותך שם, ח."],["9359","538","<b>ולא קם נביא. . פא\"פ</b>: ברכה לד, י [בדילוגים]."]]],[2300540797,"כאיש אל רעהו<sup data-n=\"9360\">539</sup> כו' (וארז\"ל דשכינה הי[תה] מדברת מתוך גרונו של משה<sup data-n=\"9361\">540</sup> מאליו כו', דהיינו מה שבחי' המל' הנק' שכינה<sup data-n=\"9362\">541</sup> הי' בגילוי נבואה במראה לבד לנביאים, הי' גילוי שכינה זה רק בגרונו של משה כו').\n<b>ושרש</b> הענין הוא לפי שהי' שרש נשמת משה בחי' מ\"ע שלפני הפרסא המפסיק כמ\"ש בו כי מן המים משיתיהו<sup data-n=\"9363\">542</sup> (וידוע בענין אמ\"ר אור מים רקיע<sup data-n=\"9364\">543</sup> דכ\"ז הוא בבחי' המ\"ע<sup data-n=\"9365\">544</sup> דתוה\"ק שהיתה תחלה כלולה בעצמותו ית' ממש ונק' אור עצמ[י] מאור עצמו' א\"ס ב\"ה (כמו עצם כח המשכיל בו<sup data-n=\"9366\">545</sup> שכל בנפש האדם שנק' נפש השכלי' וכמו הוא המדע<sup data-n=\"9367\">546</sup> כו'), ועוד<sup data-n=\"9368\">547</sup> שנתלבש אור העצמו' דתו' בלבוש ונק' משל הקדמוני כמו עוטה אור כשלמה שזהו הי' דוקא ע\"י משה<sup data-n=\"9369\">548</sup> כמ\"ש משה ידבר<sup data-n=\"9370\">549</sup> כו'), וע\"כ אין בחי' הפרסא שהוא בחי' הלבוש והצמצום מסתיר כלל לגבי משה כמ\"ש ומשה נגש אל הערפל אשר שם האלקי' דוקא (וכמשי'<sup data-n=\"9371\">550</sup> שאין לבוש דמשל הקדמוני מסתיר לו כלל). וז\"ש פא\"פ אדבר בו במראה ולא בחידות כו' במראה המאירה מאור העצמו' ממש שלא ע\"י לבוש והעלם כלל וכלל, משא\"כ בשאר הנביאי' הי' נראה במראה דפרסא רק שהוא לבוש זך ובהיר שנק' חשמל כו', וכמו שיהי' בעוה\"ב ממש [ד]כתי' ונחי' לפניו<sup data-n=\"9372\">551</sup> ממש שלא ע\"י צמצום ולבוש מסתיר ואף לא ע\"י לבוש זך ובהיר רק מאור העצמו' דא\"ס ב\"ה ממש כמ\"ש הנה אלקינו זה ממש, וכמו\"כ משה נתנבא בזה לנוכח כו' וד\"ל. והוא עצמו הטעם שא' ודיבר ה' אל משה פא\"פ כאשר ידבר איש אל רעהו כו' שהי' משה עומד בגופו בלי ביטול המציאות כלל כשאר הנביאים (כמו שהי' בהר מ' יום לחם לא אכל<sup data-n=\"9373\">552</sup> הרי הי' גופו מקבל האור והחיות האלקי בעצמו כמו נשמתו ממש שזהו כמו לע\"ל בעוה\"ב ממש, כי לא הי' גופו מבחי' נוגה דבריאה שיסתיר עליו כלל וכלל כי גם בגופו האיר כמו בנשמתו<sup data-n=\"9374\">553</sup>, ולא הי' צ\"ל בהפשטת הגשמיות כלל כשאר הנביאים שגופם מסתיר עליהם וצריכים להתבטל מישות חומר הגופני לגמרי מכל וכל וא\"ל לא היו יכולים לקבל אור גילוי שכינה בנשמתם, לפי שהי' [מקבלים] רק מבחי' המל' שנק' כה כו' שהוא ע\"י העלמת המסך והי' האור בוקע עליהם כפי מציאותם [ו]השגתם ע\"י לבוש החשמ\"ל העליון כדי שלא יתבטלו במציאותם לגמרי, וע\"כ הי' גופם דמבחי' נוגה מסתיר להם שא\"א שיקבל בחי' יש גמור מבחי' אלק[ו]' ממש",[["9360","539","<b>במדרגה כאיש </b>[ויז: כאשר ידבר איש]<b> אל רעהו</b>: תשא לג, יא. ראה בסמוך בפנים. לעיל קנט, סע\"ב."],["9361","540","<b>דשכינה הי[תה] מדברת. . של משה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' רלא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670123\" data-slug=\"torat-chaim\" data-id=\"2300670123\">תו\"ח בראשית לה, ב</a> הערה 26. שע\"ת לט, א ובהערה 6."],["9362","541","<b>המל' הנק' שכינה</b>: נסמן לעיל א, ד."],["9363","542","<b>שרש נשמת משה. . כי מן המים משיתיהו</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["9364","543","<b>אמ\"ר. . רקיע</b>: נסמן לעיל לג, ג."],["9365","544","<b>המ\"ע</b>: ויז: הח\"ע."],["9366","545","<b>בו</b>: שם: כל."],["9367","546","<b>הוא המדע</b>: נסמן לעיל פ' בא קב, א."],["9368","547","<b>ועוד</b>: ו: ועד. יז: וע\"ד."],["9369","548","<b>ע\"י משה</b>: שם: בעצמותו ית'. וכנראה שזה טעות המעתיק."],["9370","549","<b>משה ידבר</b>: יתרו יט, יט."],["9371","550","<b>(וכמשי'</b>: ו: (וכמו בשרשו. יז: או כמו בשרשו."],["9372","551","<b>ונחי' לפניו</b>: הושע ו, ב."],["9373","552","<b>בהר מ' יום לחם לא אכל</b>: תשא לד, כח. עקב ט, יח. ראה גם שע\"ת מה, א ובהנסמן במ\"מ לשם."],["9374","553","<b>בנשמתו</b>: אוצ\"ל: בנשמתו)."]]],[2300540807,"ויתקיימו במציאותם כמ\"ש כי לא יראו<sup data-n=\"9375\">554</sup> כו', אם לא ע\"י בחי' הצמצום שע\"י מסך בריחוק מקום אף במלאכים [כ]מרכבה עליונה שהרי א' הושיט אצבעו קטנה ביניהם ושרפן<sup data-n=\"9376\">555</sup> (כמ\"ש במ\"א). אבל נשמת משה הי' [מ]למעלה <span data-k=\"pg\">רעט</span> ּ מן הפרסא עד רום המעלות גם במל' דא\"ס שהוא כמו בבחי' יש האמיתי דעצמו' אוא\"ס ממש כמו שהוא בלי לבוש כלל (וכנ\"ל ביעקב ששרשו באור העצמו' שלפני החשך סתרו כו'), שהוא למעלה מבחי' ד\"ע וד\"ת שהן ב' דעות דמיש לאין ומאין ליש דזהו רק בשביל שהי' בחי' יש ממש בריחוק מקום [בלבד] כנ\"ל בב' בחי' אין, ואע\"פ שהי' משה בבחי' מ\"ה ואין דבחי' ח\"ע הקדומה גם זה הי' בבחי' יש כמו שהוא במקורו בבחי'<sup data-n=\"9377\">556</sup> יש האמיתי וזהו יש מיש שלא ע\"י אמצעי כו'<sup data-n=\"9378\">557</sup>, דהיינו שאין צ\"ל ע\"י ב' בחי' אין הנ\"ל ובחי' פרסא כלל אלא כמו שהוא ביש האמיתי כך [נתקבל] ביש המוגבל<sup data-n=\"9379\">558</sup> ממש (וכמו בעוה\"ב שא' להנחיל אוהבי יש<sup data-n=\"9380\">559</sup> האמיתי כו' [י]הי' גופ[ם] בלי ביטול כלל כמא' צדיקים יושבים שזהו יושבים בגופם ועטרותיהם<sup data-n=\"9381\">560</sup> בראשיהם ונהנין כו'), והיינו דאע\"פ שהמקבל הוא בבחי' יש ממש כמו שהוא בגוף גשמי אינו בבחי' יש נפרד כלל וכלל, וכך הי' משה גם כמו שהי' בגופו בלי פירוד כלל וכלל אדרבה בתכלית הביטול וכמו שהי' עניו מאד<sup data-n=\"9382\">561</sup> מכל האדם כו' אע\"פ שהי' בגופו ממש כו' וד\"ל.\n(טו) <b>וזהו</b> שהי' מדבר ה' עמו כאשר ידבר איש כו' והיינו כמו שהי' בגופו ולא הי' גופו מסתיר לו כלל ואינו נק' בחי' יש כלל (והיינו [מ]בחי' האין הא' דח\"ע<sup data-n=\"9383\">562</sup> שמיש לאין דכלא חשיב ממש ע\"כ יכול להיות בבחי' יש דוקא), וכ\"ז אות וסימן שאין בחי' הבריאה שנק' יש תופס מקום כלל וכלל דכלא ממש חשיב ע\"כ א\"צ להפש[י]ט א\"ע מגופו כלל ואף כמו שה[וא] בגופו אינו נחשב למאומה ויכול להיות בו גילוי [יש] האמיתי ממש בלי פירוד כלל ואינו מתבטל כלל. ודוגמא ממש לזה מצינו ביוסף הצדיק שהי' בחי' מרכבה לצ\"ע בחי' יסוד<sup data-n=\"9384\">563</sup> דע\"ס<sup data-n=\"9385\">564</sup> כו' בחי' סובב ומקיף לאבי\"ע בכלל שע\"כ הי' בחי' [אצי' ובריאה ויצי' ו]עשי' [שוין] אצלו ממש, ולכך גם כשהי' עוסק במלאכתו בטרדא גדולה בכתבי חושבני' בעסקו<sup data-n=\"9386\">565</sup> כמ\"ש בתרגום עכ\"ז לא הי' נפסק ונפרד כלל משרשו במקיף העליון דאצי' באותו העת עצמו, כי לא הי' טרדא זו בלבוש דבריאה ועשי' מפסיק ומסתיר לו כלל וכלל ואף כמו שהוא טרוד במחשבתו בעניני עוה\"ז אין זה הפסק וביטול כלל לגבי שרשו וה[י]א דביקותו למעלה בלי פירוד",[["9375","554","<b>כי לא יראו </b>[ויז: יראני]: תשא לג, כ."],["9376","555","<b>הושיט אצבעו. . ושרפן</b>: ראה גם לעיל פ' שמות ל, ב. וש\"נ."],["9377","556","<b>בבחי'</b>: ויז: ליתא."],["9378","557","<b>כו'</b>: שם: כלל."],["9379","558","<b>המוגבל</b>: שם: המקבל."],["9380","559","<b>להנחיל אוהבי יש</b>: נסמן לעיל קלח, ד."],["9381","560","<b>צדיקים יושבים. . ועטרותיהם</b>: ברכות יז, א."],["9382","561","<b>משה. . עניו מאד</b>: בהעלותך יב, ג."],["9383","562","<b>דח\"ע</b>: ויז: דד\"ע."],["9384","563","<b>ביוסף. . יסוד דע\"י</b>: ראה גם מאמרי אדה\"א בראשית ס\"ע תצא בהערה."],["9385","564","<b>דע\"ס</b>: ויז: דע\"י."],["9386","565","<b>בעסקו</b>: שם: בפנקסו."]]],[2300540816,"<sup data-n=\"9387\">566</sup>כלל, לפי שהי' במדרגה עליונה דאור עצמו' א\"ס ב\"ה שמעלה ומטה אצי' ועשי' שוין ממש (וכמאמר הוא מקומו ש\"ע<sup data-n=\"9388\">567</sup> ואין העולם מקומו כו' וכן א' איהו תפיס בכ\"ע<sup data-n=\"9389\">568</sup> ולית מאן דתפיס בי' כלל כמ\"ש במ\"א) וע\"כ אין בחי' הבריאה ועשי' נק' הפסק כלל רק כאשר האור הולך בדרך השתל' מאצי' לבריאה ע\"י פרסא בריחוק מקום אזי נק' הבריאה בחי' יש נפרד, משא\"כ למעלה כמו שהוא קמי' [ממש] אין בחי' הבריאה נק' יש נפרד כלל כמ\"ש את השמים ואת הארץ אני מלא בהשוואה אחת ממש כו', ולכך לא הי' צריך להפשיט [את] עצמו מלבוש דמח' בעוה\"ז כלל לפי שהי' דבוק למעלה כמו שהוא למטה בשוה ממש, וכך הי' במשה שהי' נשמתו ג\"כ מבחי' זו כנ\"ל באורך גדול<sup data-n=\"9390\">569</sup>.\n<b>ודוגמא</b> לזה הי' גם בדוד והגבורים שהיו לו [ש]שרש נשמתן הי' מבחי' האצי'<sup data-n=\"9391\">570</sup> עצמו שלמעלה מן הפרסא (כמו שהמל' בבחי' האצי' שאו' דברך נצב בשמים במדות דז\"א כו' ולמ\"ד <span data-k=\"pg\">560</span> ּ הגבורים הם בחי' נה\"י דז\"א<sup data-n=\"9392\">571</sup> [ב]ל' כלים פנימי' אמצעי' חיצוני' כו' כידוע בזהר בענין ג' עדרי צאן רובצים<sup data-n=\"9393\">572</sup> כו' וכענין המל' נקנית בל'<sup data-n=\"9394\">573</sup> מדות<sup data-n=\"9395\">574</sup> כו') היו עוזרים לדוד בחי' המל' בלא לב ולב<sup data-n=\"9396\">575</sup> פי' בלא לב ולב שניהם שוין כו' בלב היינו בדעת ומוחין דגדלות וכמו בקירוב אל הוי' בראי' באור נשמתם בהשגה עמוקה כמו בק\"ש ותפלה ועת גילוי שעת רצון כנבואה, ובלא לב היינו בחי' הקטנות דמוחין שלמטה מן הדעת כמו שמוסתר אור האלקי בגופם ממש הכל הי' שוה אצלם לפי שהי' שרש נשמתם מבחי' אצי' עצמו שאין בחי' הפרסא מפסיק כו', ואין הבריאה ויצי' תופסים מקום כלל וכנ\"ל ע\"כ הי' שוה אצלם בחי' הקטנות שבגופם עם בחי' הגדלות שבנשמתם כי לא הי' גופם מסתיר להם כלל, וכמ\"ש דוד אם זכרתיך על יצועי<sup data-n=\"9397\">576</sup> בבחי' הקטנות מוחין ומדות ביצוע[י] שעת השינה כך באשמורת [ב]גדלות המוחין בדביקות וקירוב אהבה כך בשוה ממש (וכמו שהי' דוד מלך על ישראל בהתנשאו' ויש גדול והי' בעת ההיא בתכלית הביטול והפשטה מכל עצמותו כו' ואין זה סתירה כלל, כי הי' שרשו במל' שלמעלה באצי' בבחי' ביטול והתכללו' ולמטה נעשה ראש לשועלים כנ\"ל ואין הצמצום דמסך עושה שינוי כלל), וגם עכשיו הרי בק\"ש נצטוינו כ\"א אף פחותי הערך (שבכל ניצוץ קטן יש לו שרש בל' כלים<sup data-n=\"9398\">577</sup> דנה\"י דז\"א שהן בבחי' הגבורים הנ\"ל) ודברת בם בשבתך בביתך [בשכבך] ובקומך<sup data-n=\"9399\">578</sup> פי' בש[כב]ך בשינה אז האדם בקטנות הדעת והמדות",[["9387","566","<b>כלל</b>: בתו\"ח כאן באים התיבות: כאשר האור הולך בדרך השתלשלו'. ונשתרבב לכאן מבסמוך (קצה, ב) שו\"ה כאשר."],["9388","567","<b>הוא מקומו ש\"ע</b>: נסמן לעיל קנ, ד."],["9389","568","<b>איהו תפיס בכ\"ע</b>: נסמן לעיל פ' וארא נ, ג."],["9390","569","<b>גדול</b>: ו: כנ\"ל. יז: וד\"ל."],["9391","570","<b>בדוד והגבורים. . נשמתן. . האצי'</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א כאן (ע' ריב)."],["9392","571","<b>ולמ\"ד הגבורים. . נה\"י דז\"א</b>: ראה שמואל-ב כג, ח ואילך. דהי\"א יא, יא ואילך. מאמרי אדה\"א נ\"ך ע' שנ. וש\"נ. קונטרסים ס\"ע שנב ואילך. לקמן פ' תצוה שכ, ד."],["9393","572","<b>ג' עדרי צאן רובצים</b>: ויצא כט, ב. ראה זהר (ס\"ת) קנא, ב. הנסמן במאמרי אדה\"א נ\"ך שם."],["9394","573","<b>המל' נקנית בל' מעלות</b>: אבות פ\"ו, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רכ. וש\"נ."],["9395","574","<b>מדות</b>: ויז: מעלות."],["9396","575","<b>בלא לב ולב</b>: דהי\"א יב, לג. ראה גם לקמן פ' משפטים רפד, ד. תצוה שיט, ב. שכב, ב. ויקהל תב, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680209\" data-slug=\"torat-chaim\" data-id=\"2300680209\">תו\"ח ויחי רמה, ג</a> ובהערה 18."],["9397","576","<b>אם זכרתיך על יצועי</b>: תהלים סג, ז. ראה גם לקמן פ' משפטים רפד, ד. תצוה שיט, ב. ויקהל תג, א."],["9398","577","<b>שבכל </b>[ויז: כי כל]<b> ניצוץ. . בל' כלים</b>: ראה גם לעיל קפ, ד."],["9399","578","<b>ודברת בם. . [בשכבך] ובקומך</b>: ואתחנן ו, ז [בדילוג. ובשכבך]. ראה גם לקמן פ' משפטים רפד, ד. תצוה שיט, ב. שכב, א ואילך. ויקהל תב, סע\"ד ואילך."]]],[2300540825,"בקטנות מאד כידוע ובקומך בשחר שדעתו מיושב ומכין לבו ומוחו בהפשטת גשמי' החומר עד שיהי' בר לבב ובעומק אמיתי' ההשגה ביחו\"ע למס\"נ באחד<sup data-n=\"9400\">579</sup> כידוע בענין המאריך באחד<sup data-n=\"9401\">580</sup> כו', ועכ\"ז א' במצוה זו דק\"ש שיהי' לאדם ב' העיתים הללו בשכבך ובקומך בשוה ממש שגם בטרדתו במו\"מ כל היום ובש[כב]ו יכול למס\"נ באחד בק\"ש ובש\"ע<sup data-n=\"9402\">581</sup> כמו בקומו בשחרית (לפי ששרש נשמתו מא\"ס ממש דאין עוה\"ז תופס מקום כלל ומאיר למטה כמו למעלה ממש כנ\"ל). וכ\"ז אינו רק מצד הארת אור דאצי' בבי\"ע שלא ע\"י מסך [ד]פרסא כנ\"ל אלא כמו שהוא ממש ואעפ\"כ אין הבריאה מתבטלת ממציאותה כלל אדרבה נשארת במהותה וישותה ואינה בבחי' נפרד כלל וכלל כנ\"ל.\n<b>ויובן</b> זה ע\"פ דוגמא [ממה] שאנו רואים בעניני הניסים והנפלאות [שעושה ה' ושכבר עשה למעלה מן הטבע כניסים] דמצרים וקי\"ס ושאר הניסים שעשו נביאים כאליהו ואלישע וכה\"ג שכ\"ז נק' נפלאות ענין הפלא ופלא גדול שלמעלה מהשגת אדם כי זהו למעלה מהטבע המוטבע, וכאשר האור שלמעלה מן הטבע מאיר בעוה\"ז המוטבע נק' פלא כהפך ים ליבשה וכה\"ג ונק' אין של היש המוטבע שמהפך היש מצירוף לצירוף כמ\"ש מי שא' לשמן וידל[י]ק<sup data-n=\"9403\">582</sup> כו', אמנם עכשיו אמר אותותינו לא ראינו<sup data-n=\"9404\">583</sup> כנ\"ל רק מתנהג הכל ע\"פ הטבע. אך יש מעלה יתירה בזה יותר מן הנסים שנק' נפלאות כאשר הנפלאות האלה עצמן הן מלובשים בדרך הטבע עצמה ואין בחי' הטבע [עצמה] מסתיר כלל כמו נס דאחשורש וכה\"ג הרי הטבע עצמה אינה בבחי' יש סדכ\"ס<sup data-n=\"9405\">584</sup> כו'. וכך ענין גילוי סודות שנק' נפלאות ג\"כ <span data-k=\"pg\">רפ</span> ּ כמו גל עיני ואביטה נפלאות<sup data-n=\"9406\">585</sup> כמו בימוהמ\"ש שיתגלה כל בחי' העלם וסוד ה' כו', אבל יותר עליון מזה כשבחי' הלכה<sup data-n=\"9407\">586</sup> שהן הלכות דתושבע\"פ הן עצמן בחי' כלי לאור העצמי כמו הנפלאות בלי פירוד ולבוש מסתיר כלל זהו בחי' יש מיש שלמעלה מבחי' אין הממוצע וכמו לחם פנג<sup data-n=\"9408\">587</sup> שתוציא הארץ גלוסקאות וכלי מילת<sup data-n=\"9409\">588</sup> כו' שהוא התהוות יש מיש בלי ביטול היש לאין בתחלה כלל וכך יהי' מלמעלה למטה מיש האמיתי ליש המוגבל כנ\"ל במשה ויוסף וד\"ל<sup data-n=\"9410\">589</sup> וכמו שהי' ברכת אברהם מעין עוה\"ב<sup data-n=\"9411\">590</sup> ממש מיש האמיתי לבחי' יש ממש (וכמ\"ש במ\"א) וד\"ל.\n<b>(טז) </b>והנה אחר כ\"ז יובן מאמר הנ\"ל דראתה שפחה על הים מה שלא ראה יחזקאל כו' להיות שהי' גילוי אור העצמו'",[["9400","579","<b>למס\"נ באחד</b>: נסמן לעיל פ' וארא עז, א."],["9401","580","<b>המאריך באחד</b>: ברכות יג, ב. ראה מאמרי אדה\"א שמות ח\"א ע' רעח."],["9402","581","<b>ובש\"ע</b>: ויז: שעהמ\"ט."],["9403","582","<b>מי שא' לשמן וידל[י]ק</b>: ראה גם לעיל פ' שמות כ, א. וש\"נ."],["9404","583","<b>אותותינו לא ראינו</b>: תהלים עד, ט. ראה גם שה\"א ל, א."],["9405","584","<b>סדכ\"ס כו'</b>: ויז: נפרד כלל."],["9406","585","<b>גל עיני ואביטה נפלאות</b>: תהלים קיט, יח."],["9407","586","<b>הלכה</b>: ויז: נגלה."],["9408","587","<b>לחם פנג</b>: נסמן לעיל כג, ב."],["9409","588","<b>שתוציא הארץ גלוסקאות וכלי מילת</b>: נסמן לעיל שם."],["9410","589","<b>וד\"ל</b>: ויז: ליתא."],["9411","590","<b>ברכת אברהם מעין עוה\"ב</b>: ראה בבא בתרא טז, סע\"ב ואילך. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שעד. דברים ח\"ג ע' א'לח. קונטרסים ע' שכו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670252\" data-slug=\"torat-chaim\" data-id=\"2300670252\">תו\"ח לך צו, סע\"ד</a> ואילך."]]],[2300540834,"דא\"ס ב\"ה [בקי\"ס] כמו שא' זה אלי לנוכח כמו שיהי' לע\"ל בעוה\"ב ממש כנ\"ל<sup data-n=\"9412\">591</sup> והיינו שהי' בבחי' דילוג שלא כפי סדר ההשתלשלו' והוא כמו אוא\"ס עצמו שאצי' ועשי' שוין לפניו ממש כנ\"ל, והיינו שהי' בקיעת המסך שלא הי' האור ע\"י התלבשות במסך <sup data-n=\"9413\">592</sup>כנ\"ל ע\"כ בחי' אצי' ובריאה שוין ואין הבריא' מתבטלת ממציאותה כלל (ולא כגילוי המל' בנביאים שמתבטלי' מצד גילוי האור מן ההעלם ביותר מכפי הצמצום והמדה בלבוש החשמ\"ל העליון דחשך סתרו כו'), אלא כמו שהוא בבריאה בבחי' יש אינו בחי' נפרד כלל [וכלל] מטעם הנ\"ל (כמו במשה ויוסף וכה\"ג), ולזאת הרי הי' גילוי אלקות למטה ממש כמו למעלה בלי שינוי כלל. ומטעם זה הי' גם שפחה יכולה לראות <sup data-n=\"9414\">593</sup>גם אור הזה בקי\"ס בשוה ממש עם גדולי זקני ישראל וכה\"ג מאחר שאין הסתר כלל מצד הגוף החומרי להיות בבחי' יש נפרד, כי כמו שהוא דוקא הוא בבחי' הביטול וכלי ממש לגילוי אור האלקי כדוגמא דפרות שנשאו הארון שהי' בחי' מרכבה ממש לבחי' המל' כו', וכמו שיהי' לע\"ל שיתגלה כבוד הוי' וראו כל בשר אפי' בהמות וחיות<sup data-n=\"9415\">594</sup> גשמי' לא יסתיר להם חומרם הגשמי' (וכחמורו של רפב\"י<sup data-n=\"9416\">595</sup> וכבהמות בהררי אלף<sup data-n=\"9417\">596</sup> כו', וראי' לזה ממה שיבטלו הטורפים כמ\"ש וגר זאב עם כבש<sup data-n=\"9418\">597</sup> כו'), שהרי בקי\"ס לא היו צריכים להתעוררות והכנה מעצמם כלל כמ\"ש ואתם תחרישון לא תתערון מידי לפי שאין אתעדל\"ת מגיע לשם כלל מטעם הנ\"ל, וא\"כ לא הי' בהם בחי' [ה]ביטול במציאות בגופים שלהם כלל וכלל כי הרי הלכו ביבשה בתוך הים ואמרו שירה בשמחת הנפש עצמה שזהו בחי' ביטול והתכללות הנשמות מבריאה לאצי' (כמשי\"ת בסמוך שיש ב' דעות בזה) והכל היו שוין בזה בגילוי אור זה כקטן כגדול. וזהו שראתה שפחה על הים במראה דזה בגילוי לומר זה אלי ואנוהו מה שלא ראה יחזקאל שהי' שרש נבואתו רק בנו\"ה דיצי' במרכבה דפני ארי' ושור כו', דגם שהי' אור המל' מאיר על נשמתו [מ]נו\"ה דמל' דאצי' שמלובש ביצי' שלא ע\"י לבוש פרסא שבין בריאה ליצי' כו' וע\"כ היו מתבטלים ממציאותם, אבל הי' זה האור רק מבחי' המל' שמצמ\"ד<sup data-n=\"9419\">598</sup> להיות כתר לבי\"ע ולא בבחי' זה דשם הוי' דז\"א דאצי' בנבואתו כו'<sup data-n=\"9420\">599</sup> וד\"ל (ומה שאמר שפחה דוקא רמז בזה דגם בחי' נוגה דעשי' שהוא בבחי' יש נפרד בגסות כמו <span data-k=\"pg\">562</span> ּ נפש הטבעית דאדם בחומר גופני כו' וכמו שפחה כי תירש גבירתה<sup data-n=\"9421\">600</sup> בזמן הגלות דשכינה כו' כידוע גם בחי' שפחה ועבד דכתרים דנוגה<sup data-n=\"9422\">601</sup> שראו אור דאצי' עצמו כמו שראה משה ואהרן וזקני ישראל באמרם זה אלי כו' מה שלא ראה יחזקאל שנתנבא",[["9412","591","<b>כנ\"ל</b>: ויז: ליתא."],["9413","592","<b>כנ\"ל</b>: שם: כלל."],["9414","593","<b>גם</b>: שם: ליתא."],["9415","594","<b>וראו כל בשר אפי' בהמות וחיות</b>: ראה גם לעיל פ' וארא עד, א ובהערה 100."],["9416","595","<b>וכחמורו של רפב\"י</b>: חולין ז, סע\"א ואילך. ראה סוף פיסקא זו. מאמרי אדה\"ז אתהלך לאזניא ע' ס. מאמרי אדה\"א ויקרא ח\"ב ע' תשסו. וש\"נ. שע\"ת ח, א ובהערה 2."],["9417","596","<b>וכבהמות בהררי אלף</b>: תהלים נ, י. ראה גם לקמן פ' תצוה שכט, ב. וש\"נ."],["9418","597","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."],["9419","598","<b>שמצמ\"ד</b>: ויז: שמתצמצם:"],["9420","599","<b>בנבואתו כו'</b>: שם: כנבואת משה כנ\"ל."],["9421","600","<b>שפחה כי תירש גבירתה</b>: משלי ל, כג [ושם: ושפחה]."],["9422","601","<b>שפחה ועבד דכתרים דנוגה</b>: ראה זהר וישלח קסו, ב. לעיל פ' שמות כו, ג."]]],[2300540843,"רק בכה כו' (ואין זה פלא כ\"כ שהרי הגר<sup data-n=\"9423\">602</sup> שפחת שרה ראתה מלאך [ה'] ג' פעמים<sup data-n=\"9424\">603</sup> ואמרה הגם הלום ראיתי<sup data-n=\"9425\">604</sup> אחרי רואי כו' לפי שהאבות והאמהות היו מעין עוה\"ב<sup data-n=\"9426\">605</sup> ממש שלא הסתיר להם גופם שלהם כלל ואף שפחה דשרה הי' ביכולתה לראות גילוי אור הוי' מה שלא ראו שאר נביאים מטעם הנ\"ל וד\"ל). וזהו הי' כדוגמא דלע\"ל ממש דכתי' וראו כל בשר כו' שיהי' גילוי אלקות למטה כמו למעלה ממש שלא ע\"י מסכים והעלמות כלל וע\"כ א' ולא ילמדו [עוד] איש את רעהו<sup data-n=\"9427\">606</sup> כו' כי כולם ידעו אותי ממש כולם בשוה כו', וע\"כ לא יהי' בחי' ביטול במציאות כלל לע\"ל ואף לא בגופים דבהמות וחיות דגם שיראו כל בשר יהי' בבחי' יש גמור ולא יצטרך להיות בהם בחי' ביטול היש כלל לא בגוף ולא בחומר ולא בנפש שלהם כמו קודם חטא אדה\"ר בעה\"ד שהיו כל בהמות וחיות בגופים זכים וטהורים מאד ואף נחש הקדמוני שהרי א' ויאמר ה' אל הנחש<sup data-n=\"9428\">607</sup> כו' וחמורו של רפב\"י [יוכיח] ולכך א' אם אנו כחמורים<sup data-n=\"9429\">608</sup> ולא כחמורו של רפב\"י שחמור שלו נזדכך ביותר מחומר שלנו כמו שהי' קודם חטא דעה\"ד שעקבו של אדה\"ר [הי'] מכהה גלגל חמה<sup data-n=\"9430\">609</sup> כידוע.\n<b>אך</b> הנה עכ\"ז הי' גם בשעת קי\"ס בחי' ביטול במציאות בנשמות שלהם שהיו עולין ונמשכי' למעלה באצי' באמרם זה אלי כו' (כמשי\"ת), וב[ב]חי' ביטול זה דנשמות הי' חילוק מדריג[ות] בין גדולים לקטנים כמו שהי' במ\"ת שהי' חילוק מדריגות בבחי' ביטול [ד]נשמות וגם בביטול דגופים, דגם שהי' גילוי אור הוי' בבחי' פ[ב]\"פ ממש כמ\"ש פא\"פ דיבר ה' עמכם<sup data-n=\"9431\">610</sup> כו', [עכ\"ז] הי' ערך גילוי הארת אור פנימי' [ד]הוי' בכ\"א לפי שרש נשמתו דוקא ולפ\"ע ההעלאה והזדככות [ה]חומר שלו בימי הספי' קודם מ\"ת<sup data-n=\"9432\">611</sup> שאומר היום יום א' לעומר כו', שזהו בחי' הבירור דז' מדות הרעות<sup data-n=\"9433\">612</sup> דק\"נ כידוע בכוונת הספי' שהספירה ה[י]א בחי' הכנה למ\"ת בז' מדות דקדושה לברר לז' מדות דבהמה כדי שיהי' ראוי[ם] עי\"ז לקבלת התורה פב\"פ ביחו\"ע במוחין דחב\"ד בגילוי אור הארת פנים העליו[נים] דאור דתורה כו' שנק' חופה ונשואין כמו ביום חתונתו זה מ\"ת<sup data-n=\"9434\">613</sup> כו', ומ\"ט ימי הספי' שהן ז' שבועות בכלל הן כספירת ז' ימים נקיים<sup data-n=\"9435\">614</sup> דאשה שתטהר לבעלה כו', ולזה הטעם הי' גילוי אור פב\"פ דמ\"ת בכ\"א לפי הבנתו<sup data-n=\"9436\">615</sup> ומדרגתו דוקא כו', ואע\"פ שביטול הרצון שלהם במה שא' נעשה<sup data-n=\"9437\">616</sup> היו כולם<sup data-n=\"9438\">617</sup> כאיש א' ולמעלה מן הטעם [ושכל של כל",[["9423","602","<b>ואין זה פלא. . הגר</b>: השוה מאמרי אדה\"א ויקרא ח\"א ס\"ע שכח ואילך."],["9424","603","<b>הגר. . מלאך [ה'] ג' פעמים</b>: מעילה יז, ב."],["9425","604","<b>הגם הלום ראיתי</b>: לך טז, יג."],["9426","605","<b>האבות והאמהות. . עוה\"ב</b>: ראה ב\"ב טז, סע\"ב ואילך. מאמרי אדה\"א ויקרא שם ואילך. וש\"נ. לקמן פ' יתרו רנב, א."],["9427","606","<b>ולא ילמדו [עוד] איש את רעהו</b>: ירמי' לא, לג."],["9428","607","<b>ויאמר ה' אל הנחש</b>: בראשית ג, יד [ושם: ה\"א]. ראה גם לקמן פ' ויקהל תא, ב."],["9429","608","<b>אם </b>[הו: ליתא]<b> אנו כחמורים</b>: שבת קיב, ב."],["9430","609","<b>שעקבו של אדה\"ר. . חמה</b>: נסמן לעיל פ' שמות מ, ב."],["9431","610","<b>פא\"פ </b>[הו: פב\"פ]<b> דיבר ה' עמכם</b>: ואתחנן ה, ד."],["9432","611","<b>והזדככות [ה]חומר. . הספי' קודם מ\"ת</b>: ראה גם לעיל פ' בא קכא, ג. וש\"נ."],["9433","612","<b>הבירור דז' מדות הרעות</b>: ראה גם לקמן רא, ד. לעיל פ' בא קיז, ב. וש\"נ."],["9434","613","<b>ביום חתונתו זה מ\"ת</b>: נסמן לעיל פ' בא קיח, ב."],["9435","614","<b>הספי'. . כספירת ז' ימים נקיים</b>: ראה גם לעיל פ' בא קיא, ד. וש\"נ."],["9436","615","<b>הבנתו</b>: הו: הכנתו."],["9437","616","<b>שא' נעשה</b>: יתרו יט, ח. משפטים כד, ג. ז."],["9438","617","<b>כולם</b>: הו: ליתא."]]],[2300540852,"א'], אבל מ\"מ הי' האור דח\"ע דתו' מאיר בכאו\"א כפי מדריגתו עד שהי' למשה מחיצה בפ\"ע ולאהרן מחיצה בפ\"ע כידוע במ\"ש ועלית אתה<sup data-n=\"9439\">618</sup> ואהרן עמך כו'<sup data-n=\"9440\">619</sup> והכהנים והעם אל יהרסו לעלות כו' (וכך יהי' גם בעוה\"ב שכאו\"א יקבל כפי מדרגתו ושרש עבודתו בתומ\"צ באוי\"ר בעוה\"ז כו' אע\"פ שא' הנה אלקינו זה בגילוי לכולם בשוה, מ\"מ בחי' קבלת השכר יהי' לכאו\"א <span data-k=\"pg\">רפא</span> ּ כמו שהוא דוקא, שזהו כמו התחלקות אור החיות באברי הגוף כו' שכאו\"א מיוחד בפ\"ע כו' ואין א' שייך לחבירו כך צדיק א' נכוה מחופתו של חבירו<sup data-n=\"9441\">620</sup> כו' שהוא מציור אדם בחי' ממלא <sup data-n=\"9442\">621</sup>כו', אבל בקי\"ס הי' [ה]אור בגילוי המקיף [דהעלם דים שנעשה יבשה כנ\"ל] שהאיר לכולם בשוה שלא ע\"י מסך כלל כי לא הי' ע\"י העלאת מ\"ן מבירור דנוגה כלל וע\"כ לא הי' הביטול בגופם וגם שפחה כו' <sup data-n=\"9443\">622</sup>כנ\"ל. אבל במ\"ת היו קולות וברקים וקול השופר<sup data-n=\"9444\">623</sup> וינועו ויעמדו מרחוק<sup data-n=\"9445\">624</sup> שהי' ביטול גדול בגופים דוקא וגם בנשמתם שעכ\"ד פרחה נשמתן כו' ולא הי' כזה בקי\"ס אע\"פ שהי' הכנה למ\"ת מלמעלמ\"ט ומלמטלמ\"ע באו\"ח ואו\"י כמשי\"ת וד\"ל.\n(יז) <b>והנה</b> בעיקר ענין דקי\"ס שזהו בחי' גילוי אור האצי' בבריאה שלא ע\"י התלבשו' במסך ופרסא כלל [כנ\"ל] יש בזה ב' דעות שונות<sup data-n=\"9446\">625</sup> ומחולקות, שלפי הזהר (במאמ' כד סליק ימא גלגלוהי<sup data-n=\"9447\">626</sup> כו') הי' זה הענין בבחי' או\"ח בהעל[א'] מלמטה למעלה דוקא, והיינו בחי' עליות עולם הבריאה בעולם האצי' שלא ע\"י לבוש והעלם, [ו]דלא כעכשיו שיש נשמות דבריאה שעולין בבחי' האצי' ממש שזהו כמו מיכאל כה\"ר מקריב נשמות<sup data-n=\"9448\">627</sup> ע\"ג המזבח העליון דאצי' שנכללים ונשתאבים באור האצי' כו' שאינם מתקיימים שם במציאות כ\"א ע\"י לבוש וכיסוי דהיינו מבחי' החשמ\"ל כו' (כמו בכל חדש ושבת שיבא כל בשר להשתחוות לפני הוי'<sup data-n=\"9449\">628</sup> באצי' כנ\"ל<sup data-n=\"9450\">629</sup> ). ולפי דעת המקובלים בקבלת האריז\"ל יהי' זה הענין דקי\"ס בבחי' ירידה והמשכה דאו\"י מלמעלה למטה דוקא דהיינו שגילוי אור האצי' ירד מאצי' לבריאה כמו שהוא שלא ע\"י בחי' לבוש והעלם כלל כנ\"ל (ושרש מחלוקת ז[את] הוא בסיבת הבקיעה בפרסא שבין אצי' לבריאה שלפ\"ד הזהר הי' הבקיעה מלמטה למעלה ברוח קדים עזה שהי' עולה בים מלמטה למעלה ועולין בגילוי כ\"כ עד שבוקעין<sup data-n=\"9451\">630</sup> המים). ולפ\"ד האריז\"ל הי' הבקיעה מלמעלה למטה",[["9439","618","<b>למשה מחיצה בפ\"ע. . ועלית אתה</b>: יתרו יט, כד וברש\"י ממכילתא שם."],["9440","619","<b>כו'</b>: כ\"ה גם בהו."],["9441","620","<b>צדיק א' נכוה. . חבירו</b>: ראה בבא בתרא עה, א. הו: אין צדיק נכוה — ראה מאמרי אדה\"א שמות ח\"א ע' רטו. וש\"נ. שמות ח\"ב ע' שמח. ולהעיר מאור יקר — להרמ\"ק — פ' ויקהל ס\"ד כרך יא דף עג."],["9442","621","<b>כו'</b>: אוצ\"ל: כו')."],["9443","622","<b>כנ\"ל</b>: בתו\"ח כאן באים עוה\"פ התיבות: וגם שפחה כו'."],["9444","623","<b>במ\"ת היו קולות וברקים וקול השופר</b>: יתרו יט, טז. כ, טו."],["9445","624","<b>וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["9446","625","<b>ב' דעות שונות</b>: ראה לעיל קפב, ג. וש\"נ."],["9447","626","<b>כד סליק ימא גלגלוהי</b>: זהר בשלח מח, ב."],["9448","627","<b>מיכאל כה\"ר </b>[הו: כה\"ג]<b> מקריב נשמות</b>: ראה גם לעיל פ' שמות ה, א. וש\"נ."],["9449","628","<b>בכל חדש ושבת. . הוי'</b>: ע\"פ ישעי' סו, כג."],["9450","629","<b>כנ\"ל</b>: הו: כו'."],["9451","630","<b>ועולין בגילוי. . שבוקעין</b>: הו: והעלה גלים. . שבקע(ו)."]]],[2300540861,"כמו ענין ובחי' לידה דולד שיצא מן ההעלם דבטן אמו לגילוי כו' (כמבואר במ\"א במאמר דהאי אי' לתתא<sup data-n=\"9452\">631</sup> כו'). ופי' הפסוק דויולך ה' ברוח קדים עזה כו' היינו מלמטה למעלה<sup data-n=\"9453\">632</sup> דוקא וכן משמע פשט הכתוב דויט משה את ידו על הים ויולך ה' כו' כמ\"ש ואתה הרם את מטך ונטה את ידך על הים ובקעהו. וכך אנו אומרים בוקע ים לפני משה<sup data-n=\"9454\">633</sup> דמשמע שע\"י משה נבקע הים מלמטה למעלה, וכן פי' הפשוט דהפך ים ליבשה משמע כפשט<sup data-n=\"9455\">634</sup> האריז\"ל דבקיעה הוא מלמעלה למטה ע\"כ א' הפך ים ליבשה דמבחי' ים נעשה יבשה והוא מ\"ש נצבו כמו נד כו' (וכן א' הים ראה וינוס כו' כנ\"ל), אבל לפי' הזהר הל\"ל בהפך [הפך] יבשה לים מאחר שבחי' בריאה עולה למעלה באצי' שהבקיעה הי' מלמטה למעלה, וכן ממ\"ש ובנ\"י הלכו ביבשה בתוך הים<sup data-n=\"9456\">635</sup> דמשמע דים נהפך ליבשה וכמ\"ש והמים להם חומה<sup data-n=\"9457\">636</sup> כו', אך מלשון זה יכול יותר לדרוש<sup data-n=\"9458\">637</sup> כפי' הזהר שהרי אמר בתוך הים כמו שהוא למעלה הלכו ביבשה שזהו בנשמות שבגופי' שעלו למעלה והלכו שם ביבשה (כחנוך<sup data-n=\"9459\">638</sup> ואליהו<sup data-n=\"9460\">639</sup> שעלו למרום כמו שהן בגופים שלהם [ממש] כנ\"ל ), אבל לפי האריז\"ל זה[ו] [כ]נשמת <span data-k=\"pg\">564</span> ּ משה ומשיח וכה\"ג באור האצי' מאיר כמו שהוא בגוף כמו שהוא למטה בלי שינויים כלל כמו שהוא למעלה וא\"צ לעלות למעלה כלל [ו]כמ\"ש במשיח אני היום ילדתיך<sup data-n=\"9461\">640</sup> וכך יהי' בכללות נש\"י כמ\"ש במ\"א.\n<b>אך</b> הנה בעצם גוף הענין דקי\"ס אין נ\"מ כ\"כ בין ב' דעות הנ\"ל שלפ\"ד הזהר הי' יחוד וחיבור אל<sup data-n=\"9462\">641</sup> האצי' בבריאה ובריאה באצי' שלא ע\"י לבוש וממוצע כלל כנ\"ל, אלא שהן חלוקין באופן גילוי חיבור ויחוד זה, שלפ\"ד הזהר הי' יחוד וחיבור זה באצי' דוקא (שזהו כמו שילוב [שם אדנ\"י בהוי' מלמטה למעלה כו') ולפ\"ד האריז\"ל הי' חיבור זה למטה (שזהו כשילוב] שם הוי' באד'<sup data-n=\"9463\">642</sup> מלמעלה למטה). וזהו כמו משל ב' בנ\"א<sup data-n=\"9464\">643</sup> א' עומד למעלה בגובה ההר והב' עומד למטה בעמק ותשוקת שניהם להתחבר יחד כאב עם הבן וכה\"ג [ו]יש באופן חיבורם שני אופנים א' שירד העליון מלמעלה למטה אל התחתון ויחוברו שניהם למטה, או אופן הב' שיעלה התחתון העומד למטה למעלה בגובה ההר ויהי' חיבורם יחד למעלה. ואין נ\"מ בעצם החיבור והקירוב זע\"ז כשמתחברים יחד למעלה או כשמתחברים יחד למטה באיזה מהאופנים<sup data-n=\"9465\">644</sup> היחוד הוא אמיתי בלי לבוש והעלם [כלל (]רק שהתחתון שעולה למעלה",[["9452","631","<b>במ\"א במאמר דהאי אי' לתתא</b>: הו: במא' דהאי איילתא — ראה זהר בשלח נב, ב. פע\"ח (שער חה\"מ) שכ\"א, פ\"ח."],["9453","632","<b>מלמטה למעלה</b>: הו: מלמעלה למטה."],["9454","633","<b>בוקע ים לפני משה</b>: תפלת ערבית."],["9455","634","<b>כפשט</b>: הו: כפי'."],["9456","635","<b>ובנ\"י הלכו ביבשה בתוך הים</b>: בשלח יד, כט."],["9457","636","<b>והמים להם חומה</b>: המשך הכתוב ובנ\"י."],["9458","637","<b>לדרוש</b>: הו: לפרש."],["9459","638","<b>כחנוך. . למרום. . בגופים</b>: ראה בראשית ה, כד. מאמרי אדה\"א קונטרסים ע' שעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670427\" data-slug=\"torat-chaim\" data-id=\"2300670427\">תו\"ח בראשית כו, ב</a> ובהערה 16."],["9460","639","<b>ואליהו. . למרום. . בגופים</b>: ראה מלכים-ב ב, יא. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. קונטרסים שם. וש\"נ. שע\"ת מה, א ובהערה 4. לקמן רז, א."],["9461","640","<b>אני היום ילדתיך</b>: נסמן לעיל פ' שמות א, ג."],["9462","641","<b>שלפ\"ד הזהר הי' יחוד וחיבור אל</b>: הו: שלפי דעת שניהם הי' רק ענין גילוי וחיבור אור."],["9463","642","<b>שילוב. . אדנ\"י בהוי'. . הוי' באד'</b>: נסמן לעיל פ' וארא נ, א הערה 32."],["9464","643","<b>משל ב' בנ\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסז. מאמרי אדה\"א הנחות תקע\"ז ע' רסח. וש\"נ. שע\"ת ק, ב ובהערה 18."],["9465","644","<b>באיזה מהאופנים</b>: הו: שבשני האופנים."]]],[2300540870,"מתפשט ממדרגתו מפני שעולה למהות גבוה ממנו ואמנם העליון היותר למעלה<sup data-n=\"9466\">645</sup> צריך להשפיל א\"ע ממדריגתו). ודוגמא לזה [יש] גם עכשיו רק שהוא ע\"י לבוש זך בעילוי הנשמות מבריאה לאצי' ובליל שבת שהוא בקבלת שבת<sup data-n=\"9467\">646</sup> כידוע, והוא ע\"י בקיעת המסך שבין [כל] עולם לעולם מלמטה למעלה, וביום השבת יורד האור בבקיעת המסך מלמעלה למטה. ואמנם הנה באמת כ\"ז שיפול בו ענין עליות וירידות באו\"ח ואו\"י כנ\"ל אין שייך רק בבחי' ההשתל' דע\"ס ד[א]בי\"ע (כמו מרצון לשכל ומשכל למדות ומחדו\"מ בהמשכה או בהעלאה וביטול היש לאין מדו\"מ למח' [כו')], שזהו כמו [בחי'] ב' דיעות [הנ\"ל] דמיש לאין ומאין ליש כו', והיינו כמו למשל העומד למעלה ועומד למטה שיש בחי' מעלה ומטה עכ\"פ כעיגול שבו קו א' ההולך מעליו[נו] לתחת[יתו] יתכן בו עלי' מתחת[יתו] לעליו[נו] וירידה מעליו[נו] כו', אבל קמי' עצמות א\"ס ב\"ה ממש ה\"ז למעלה מהגבלה זו דמעלה ומטה (דגם שבעצמו' אוא\"ס יש בחי' מעלה ומטה והוא [מה] שאוא\"ס למעלה עד אין קץ ולמטה עד אין תכלית זהו [ג\"כ] בחי' חו\"ג שבעצמות<sup data-n=\"9468\">647</sup> שאוא\"ס<sup data-n=\"9469\">648</sup> בלבד[ו] שוין לפניו גם עומ\"ר ועמ\"ת זה כו' כנ\"ל, דע\"כ סובל ב' דעות הנ\"ל, וכמ\"ד שמים וארץ כא' נבראו<sup data-n=\"9470\">649</sup> שהן עומ\"ר ועמ\"ת דשמים לרום וארץ לעומק<sup data-n=\"9471\">650</sup> כו' כמ\"ש במ\"א) ולא יתכן ענין עלי' וירידה כלל (כמו שיהי' לע\"ל בבחי' מנוחה לחיי העולמים<sup data-n=\"9472\">651</sup> כו'). והנה מצד שהי' גילוי אור מעצמו' א\"ס ב\"ה ממש שלמעלה מבחי' מעלה ומטה זה הי' עיקר סיבת הטעם בקי\"ס שהי' בזה<sup data-n=\"9473\">652</sup> גילוי אור האצי' בבריאה שלא ע\"י מסך כלל, כי הי' עי\"ז<sup data-n=\"9474\">653</sup> גילוי אור העליון שנעלה הרבה מן המשפיע דאו\"י והמקבל דאו\"ח שז\"ש הים ראה וינוס כו' שממילא [נ]בקע הים ונעשה יבשה כו', שזהו בחי' העלם המקיף הכללי שנק' עיגולי א\"א דאצי' שמקיף לרגלי העשי'<sup data-n=\"9475\">*654</sup> שהי' בבחי' גילוי או\"כ<sup data-n=\"9476\">654</sup> לבד ש[ז]מ\"ש וירא ישראל [ישראל] סבא שהוא מדות דכתר שנק' א\"א ועתיק את היד הגדולה [ש]מעצמו' א\"ס שלמטה כמו למעלה ממש להיות[ו] למעלה ג\"כ מבחי' מקיף דמעלה ומטה כנ\"ל וד\"ל. וזהו לגוזר י\"ס לגזרים כל\"ח שקריעה זו הי' מבחי' <span data-k=\"pg\">רפב</span> ּ חסד העצמ[י] שעשה מים ליבשה בב' אופנים הנ\"ל מלמעלה למטה מאצי' לבריאה כנ\"ל ומלמטלמ\"ע מבריאה לאצי' באו\"ח דשניהם שוין שם ממש, וזהו חסד שכלול מגבורה יחד כי הרי העביר ישראל בתוכו וניער פרעה וחילו כו' והכל מחסד א' שנעשה חסד לזה ודין לזה בים עצמו והיינו מטעם הנ\"ל וד\"ל.",[["9466","645","<b>היותר למעלה</b>: הו: שיורד למטה."],["9467","646","<b>בעילוי </b>[הו: כעליות]<b> הנשמות. . בקבלת שבת</b>: ראה גם ע\"ח (שער קיצור אבי\"ע) ש\"נ, ספ\"ו. לעיל קצ, ג. ראה גם לקמן פ' תצוה שנא, ד הערה 383."],["9468","647","<b>חו\"ג שבעצמות</b>: נסמן לעיל פ' בא פט, ב."],["9469","648","<b>שאוא\"ס</b>: הו: ליתא."],["9470","649","<b>שמים וארץ כא' נבראו</b>: חגיגה יב, א. ראה גם לעיל פ' וארא ס, ד."],["9471","650","<b>דשמים לרום וארץ לעומק</b>: משלי כה, ג."],["9472","651","<b>מנוחה לחיי העולמים</b>: סוף תמיד."],["9473","652","<b>שהי' בזה</b>: הו: במה שהי'."],["9474","653","<b>עי\"ז</b>: הו: ע\"י."],["9475","*654","<b>עיגולי א\"א. . לרגלי העשי'</b>: ראה גם לקמן פ' תצוה שמא, א. וש\"נ."],["9476","654","<b>או\"כ</b>: הו: או\"פ."]]],[2300540879,"<b>ולהבין</b><sup data-n=\"9477\">655</sup> כ\"ז הי' בקי\"ס בזמן יצ\"מ שהי' בחי' הבקיעה בפרסא שבין אצי' לבריאה [ב]בחי' [מל' ד]אצי' שנעשה כתר לבריאה כנ\"ל, והיינו רק בחי' ה' אחרונה דשם הוי'<sup data-n=\"9478\">656</sup> שנק' סופא דכ\"ד כנ\"ל, והי' כ\"ז הכנה למ\"ת שיוכלו לקבל התו' פב\"פ כו', שע\"י שהי' גילוי ההעלם מים סופא דכ\"ד למטה כך הי' גילוי אור פנימי' הח\"ע במדות ד[כ]נ\"י פב\"פ שהוא שם הוי' דמ\"ה דחכ' דאדם העליון דאצי' עצמו כידוע. אך כתי' כימי צאתך מאמ\"צ אראנו נפלאות אראנו לבחי' יצ\"מ<sup data-n=\"9479\">657</sup> הנ\"ל (כמשי\"ת) דלע\"ל יהי' העברה ב' בנהר פרת (וכמ\"ש למעלה) כמ\"ש עד יעבור להבא<sup data-n=\"9480\">658</sup> כנ\"ל, שאז יהי' גילוי אלקות במעלה ומדרגה גבוה הרבה מקי\"ס שעבר עד שיהי' יצ\"מ וקי\"ס לע\"ל רק בבחי' דוגמא ומשל למה שיהי' לע\"ל, כמ\"ש הפך ים ליבשה לשון עבר בנהר יעברו ברגל לע\"ל שם נשמחה בו ממש כו' ופי' נהר זה הוא מ\"ש והניף ידו על הנהר והכהו לז' נחלים והדריך בנעלים דוקא כו' (ומבואר למעלה שבזה עצמו יש ב' העברות א' בנחל שהוא לשון ים מצרים והב' בנהר פרת הוא דמעיקרא שהוא הנהר שיצא מעדן כו'). והנה ביאור [ענין] בחי' נהר זה שיעברו ברגל לע\"ל וזהו מבחי'<sup data-n=\"9481\">659</sup> בינה עילאה דאצי' שהוא ה' ראשונה דשם הוי' כידוע די\"ה הוא בחו\"ב ו\"ה במדות ודבור כו', וכמו שהנהר יוצא ומתגלה מן המעיין שנובע בהעלם עדיין ומן ההעלם יוצא לגילוי בהמשכה דנהר כו', כך בחי' אור הבינה שהוא בחי' [ה]התפשטות דהשגה והבנה בתפיסת השכל לאורך [ורוחב] ועומק כו' שנמשך ליש מאין והעלם דנקודה דחכ' (כמשי\"ת) והוא שנק' בזהר ימא עילאה<sup data-n=\"9482\">660</sup> או ים הקדמוני<sup data-n=\"9483\">661</sup> ובחי' המל' נק' ים תתאה<sup data-n=\"9484\">662</sup> או ים האחרון<sup data-n=\"9485\">663</sup> והן ב' ההי\"ן דשם הוי' בינה ומל'<sup data-n=\"9486\">664</sup> שז\"ש כאמה כבתה<sup data-n=\"9487\">665</sup> כו' ואמר בזהר ע\"פ אתי מלבנון כלה<sup data-n=\"9488\">666</sup> כו' תרין נוקבין פריש שלמה מלכא<sup data-n=\"9489\">667</sup> כו' שהוא שם ס\"ג דבינה<sup data-n=\"9490\">668</sup> בחי' נוק'<sup data-n=\"9491\">669</sup> מקבל מחכ' בחי' שם ע\"ב<sup data-n=\"9492\">670</sup> ושם ב\"ן דמל'<sup data-n=\"9493\">671</sup> דמקבל משם מ\"ה דז\"א<sup data-n=\"9494\">672</sup> כנ\"ל והיינו ג\"כ ושם הגדולה לאה<sup data-n=\"9495\">673</sup> פנימי' מח' במל' דבינה ושם הקטנה רחל, וכן במיילדות העבריות שם הא' שפרה<sup data-n=\"9496\">674</sup> בחי' פנימי' בינה ושם השנית פועה בחי' עולם הדבור והיינו ב' ההי\"ן דשם הוי' ה' עילאה וה' תתאה כנ\"ל, וכמו שהי' ענין קי\"ס במל' ה' תתאה כנ\"ל כך יהי' לע\"ל בה' עילאה דבחי' בינה שנק' נהר שזהו שא' בנהר יעברו ברגל להבא לע\"ל כנ\"ל וד\"ל.\n(יח) <b>והנה</b> להבין ביאור ענין העברה דלע\"ל בנהר דבחי' בינה דה\"א עילאה כנ\"ל, הנה זה יהי' בדומה ממש כמו",[["9477","655","<b>ולהבין</b>: שם: והנה."],["9478","656","<b>[מל'. . ה' אחרונה דשם הוי'</b>: נסמן לעיל פ' שמות יב, ד הערה 581."],["9479","657","<b>יצ\"מ</b>: הו: יש\"ס — נסמן לעיל פ' שמות כא, א."],["9480","658","<b>עד יעבור להבא</b>: ראה גם לעיל קפה, ד."],["9481","659","<b>וזהו מבחי'</b>: ה: זהו בחי' מבחי'. ו: זהו בחי'."],["9482","660","<b>הבינה. . ימא עילאה</b>: ת\"ז תי\"ט (לח, ב)."],["9483","661","<b>הבינה. . ים הקדמוני</b>: נסמן בהערה 663."],["9484","662","<b>המל' נק' ים תתאה</b>: ת\"ז תי\"ט (לח, ב)."],["9485","663","<b>המל'. . ים האחרון</b>: פרדס (שער ערה\"כ) שכ\"ג מערכת ים."],["9486","664","<b>ב' ההי\"ן. . בינה ומל'</b>: ראה ת\"ז בהקדמה (ו, ב)."],["9487","665","<b>כאמה כבתה</b>: יחזקאל טז, מד."],["9488","666","<b>אתי מלבנון כלה</b>: שה\"ש ד, ח."],["9489","667","<b>תרין נוקבין פריש שלמה מלכא</b>: ראה זהר (אד\"ז) האזינו רצ, ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכח."],["9490","668","<b>ס\"ג דבינה</b>: נסמן לעיל פ' וארא פד, ד."],["9491","669","<b>ס\"ג. . נוק'</b>: ראה מבו\"ש ש\"ב ח\"ג, פ\"א. ע\"ח (שער התיקון) ש\"י, פ\"ב."],["9492","670","<b>מחכ' בחי' שם ע\"ב</b>: נסמן לעיל פ' וארא פד, ד."],["9493","671","<b>ב\"ן דמל'</b>: נסמן לעיל פ' שמות יב, ג."],["9494","672","<b>מ\"ה דז\"א</b>: ראה ע\"ח (שער ז\"א) שי\"ז, פ\"ד."],["9495","673","<b>ושם הגדולה לאה</b>: ויצא כט, טז [ושם: שם]."],["9496","674","<b>שם הא' שפרה</b>: שמות א, טו. ראה גם לעיל פ' שמות כה, ג ואילך. לב, סע\"ד ואילך."]]],[2300540888,"שהי' בקי\"ס בה\"א תתאה [ד]בחי' המל' ע\"ד שנת' למעלה בקי\"ס בכל פרטי אופנים ממש כו'. דהנה מבואר למעלה בפרטי ענין קי\"ס במל' דאצי' כו' שהיו ג' מדרגות בכלל יש ואין ויש ובחי' יש המוגבל הוא מה שנברא מאין ליש בע\"ג ממש ו[כ]חיות הנפש בדם באברים וכצומח העשב הגשמי' כו') <span data-k=\"pg\">566</span> ּ ובחי' אין הוא אין להיש המוגבל, ומדרגה הב' באין זה עצמו כמו שהוא בבחי' חשך דכלא וכאין חשיב לבחי' יש האמיתי שנמשך מיש לאין כו'. וכך הוא ממש במעלה גבוה יותר והוא בבחי' אין ויש דחו\"ב שיש בזה ג\"כ ג' מדרגות [בחי'] יש ואין ויש, יש האמיתי [ז]הו בחי' [אור] הכתר עצמו, שזהו בחי' הרצון והתענוג הפשוט [עצמו] כמו שהוא למעלה מבחי' החכ' אפי' מטעם כמוס לרצון שנק' ח\"ס חכ' שבכתר כידוע דאין טעם לרצון כלל<sup data-n=\"9497\">675</sup> והוא בחי' גולגלתא דחפיא על מוחא סתימא'<sup data-n=\"9498\">676</sup> כו' כידוע. ובחי' אין שנמשך מיש האמיתי זה היינו בחי' החכ' שתמצא מאין דכתר כמ\"ש והחכ' מאין תמצא<sup data-n=\"9499\">677</sup> כו', וכמו מטעם ושכל לרצון שמורכב הרצון בו כו', והוא כח נקודת הברקת אור השכל וח\"ס<sup data-n=\"9500\">678</sup> שיוצא כברק מבריק<sup data-n=\"9501\">679</sup> על המוח ואין בו התפשטות אורך ורוחב בהסבר [ו]השגה אפי' לעצמו עדיין להבין איכות ומהות הדבר ונק' כח זה מה פשפשת<sup data-n=\"9502\">680</sup> כו', שהוא [ב]בחי' ההעלם והפלאה מהשגה דבינה עדיין כנקוד' דיו\"ד שאינה מתפשטת כלל. ואמנם כאשר נקודה זו עצמה בהתפשטו' בהשגה ותפיסא ממש איך ומה ובהתחלקות ענינים פרטי' ואופנים שונים זה [ש]נק' בינה בבחי' יש ממש ומוגבל הוא לאורך ורוחב ועומק כפי ש[י]צ[ו]ייר המושג באיכותו ומהותו בדרך פרט [ב]אותיות המח' כידוע. ולפ\"ז הרי יובן ממילא שבחי' אור החכ' שמבריק [מ]למעלה מן השכל ונק' ממוצע ממש בין ב' בחי' יש הנ\"ל, שהוא בין יש האמיתי [ד]עונג ורצון העצמ[י] הנ\"ל שלמעלה מן החכ' לגמרי ובין בחי' יש הב' דבינה שהוא המורכב בהשגה מוגבלת מ[מ]ש שנק' יש מוגבל כו'. וא\"כ כמו שמבואר למעלה בקי\"ס במל' שא\"א להיות דילוג כזה מיש האמיתי ליש המוגבל אם לא ע\"י ממוצע שהוא בחי' אין באופן שנחלק לב' בחי' אין דוקא, אין הנעלם שנק' חשך כמו שמיש לאין כו'<sup data-n=\"9503\">681</sup> ואין של היש המ[ו]גבל שנק' אור, וגם זה בריחוק מקום דוקא שהוא בחי' הפרסא כנ\"ל באורך, כך הוא ג\"כ בחו\"ב שהחכ' יש בה ב' בחי' אין הא' דחכ' היינו כמו שהחכ' באין דכתר שהוא בבחי' ביטול המציאות לגמרי שנק' חשך ולא אור כלל כמאמר [ד]אפי' אור צח [כו' שהוא] <sup data-n=\"9504\">682</sup>חכ' אוכם הוא ממש לגבי עה\"ע שהוא יש האמיתי דבחי' הכתר עצמו <sup data-n=\"9505\">683</sup>שהוא, והיינו כמו שכח השכל הזה נובע ומבריק כברק עדיין גם הוא",[["9497","675","<b>דאין טעם לרצון כלל</b>: נסמן לעיל פ' בא פט, ד."],["9498","676","<b>גולגלתא דחפיא על מוחא סתימא'</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["9499","677","<b>והחכ' מאין תמצא</b>: נסמן לעיל פ' בא קא, ג."],["9500","678","<b>וח\"ס</b>: הו: וחכ'."],["9501","679","<b>כברק מבריק</b>: ראה גם לקמן פ' תרומה שיב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670214\" data-slug=\"torat-chaim\" data-id=\"2300670214\">תו\"ח בראשית י, א</a> ובהערה 4."],["9502","680","<b>זה </b>[הו: מה]<b> מה פשפשת</b>: זהר בהקדמה א, ב."],["9503","681","<b>כו'</b>: הו: כנ\"ל."],["9504","682","<b>חכ'</b>: ה: ח\"ס."],["9505","683","<b>שהוא</b>: הו: ליתא."]]],[2300540897,"בהעלם וביטול במקורו בכח <sup data-n=\"9506\">684</sup>השכל ההיולי שנכלל באור הכתר עצמו שהוא עצם הרצון והתענוג כו' (וכנ\"ל בבחי' יר\"ע בפנימי' חכ' שנק' יראה בושת) דאיידי דטריד למבלע לא פליט להיות משפיע מאין ליש בבינה (והוא קוש\"י שפונה למעלה ליכלל באור הכתר). ובחי' אין הב' דחכ' היינו כשמאיר ונובע בהברקה עכ\"פ כנקודה דיו\"ד [ו]נמשך ליש ממש המוגבל שהוא יש דהשגה דבינה, אע\"פ שנביעה זו בהברק[ת] <sup data-n=\"9507\">685</sup>עכ\"פ אור החכ' הוא בבחי' העלם, מ\"מ יוצא לאור להיות שרש ומקור להשגה דבינה שנק' יש גמור ונק' אין של היש עכ\"פ, והוא קוץ התחתון דיו\"ד שע\"ז א' הבן בחכ'<sup data-n=\"9508\">686</sup> להביא נקודה דחכ' מאין ליש בהסבר והשגה לאור<sup data-n=\"9509\">687</sup> כמ\"ש במ\"א וד\"ל. ואז החכ' נק' בשם אור המאיר <span data-k=\"pg\">רפג</span> ּ לזולתו, משא\"כ בבחי' אין הא' דח\"ס דא\"א שנק' שכל הנעלם מכל רעיון כו' (וכמו רזא דרזין כנ\"ל), וגם זה א\"א להיות מציאת היש המוגבל דבינה בהשגה כ\"א ע\"י בחי' ריחוק מקום דוקא, דהיינו להפריד בין [ב'] בחי' אין [ד]חכ' הנ\"ל, שיוכל להתהפך [מ]ביטול ד[כ]אין כלפי עילתו עה\"ע שהוא אין הנעלם<sup data-n=\"9510\">688</sup> כו', והיינו שיהי' שרש לבינה<sup data-n=\"9511\">689</sup> ע\"י בחי' הפרסא דבחי' קרומא דאוירא כו' שהוא המפסיק בין הכתר לחכ' כנ\"ל, והוא מ\"ש והבדילה הפרוכת לכם בין הקדש דח\"ע לקה\"ק דאור הכתר שנק' עה\"ע בכלל כמ\"ש למעלה שא\"א להיות השתלשלו' והתהוות יש מאין כו' שהי'<sup data-n=\"9512\">690</sup> הכל חוזר למקומו<sup data-n=\"9513\">691</sup> הראשון אם לא ע\"י ג' מדרגות דיש ואין [ויש] ובריחוק מקום דבחי' הפרסא, כך א\"א להיות בחי' יש דבינה בלא צמצום דקרומא זה שעי\"ז נעשה אור החכ' [מ]אין ליש בבינה כו' וא\"ל הי' הכל בביטול והתכללו' דעצמו' א\"ס שבכתר ולא הי' השתלשלו' דמע\"ב שמאין דחכ' בבינה כנ\"ל, וכך עד רום המעלות גם במל' דא\"ס שיאיר בקו\"ח כנ\"ל שיש שם ג\"כ בחי' פרסא רק שנק' בשם מקו\"פ וחלל כו' מטעם הנ\"ל וד\"ל.\n<b>וא\"כ</b> הרי יובן עכ\"פ שכל פרטי אופנים הנ\"ל למעלה בענין הבקיעה בפרסא שבין אצי' לבי\"ע במל' כך הוא למעלה בא\"ס<sup data-n=\"9514\">692</sup> שהוא אין ויש למעלה, שבחי' אין דחכ' הוא בחי' הממוצע בין כתר לבינה, והוא ע\"י בקיעת הקרומא דאוירא כו' שילך האור והשפע מכתר שהוא מע\"י וא\"א לבינה מיש ליש שלא ע\"י מסך זה דקרומא כלל [כמו שהי' אור האצי' בבריאה בקי\"ס שלא ע\"י מסך כלל] כנ\"ל (והיינו כמו שאנו רואים באדם שכח השפע מעצמות העונג שבעצמו' הנפש יבא ע\"י הארת צמצום העונג בבחי' אין דחכ' במוח החכ' אחר ההעלם דבחי' קרומא הנ\"ל, כמו [שרואים] בחכמת אדם שמחדש אור שכל חדש שנמשך מהעלם דכח החכ' כמו שהוא בבחי' אין ממש ששם הוא",[["9506","684","<b>השכל</b>: שם: המשכיל."],["9507","685","<b>עכ\"פ</b>: שם: ליתא."],["9508","686","<b>הבן בחכ'</b>: ס\"י פ\"א, מ\"ד. ראה ביאוה\"ז וארא לט, ב ואילך."],["9509","687","<b>לאור</b>: הו: לאורך ורוחב."],["9510","688","<b>שהוא אין הנעלם</b>: שם: להיות אין והעלם ושורש לבינה. וראה הערה שלאח\"ז."],["9511","689","<b>שיהי' שרש לבינה</b>: שם: ליתא. וראה הערה שלפנ\"ז."],["9512","690","<b>כו' שהי'</b>: שם: כי הי'."],["9513","691","<b>למקומו</b>: שם: למקורו."],["9514","692","<b>בא\"ס</b>: שם: בחו\"ב."]]],[2300540905,"התלבשות אור העונג הנעלם הרוחני שבמוח החכ' (שנק' קוועלין<sup data-n=\"9515\">693</sup> אין תענוג) שמזה יחודש ע\"י הקרומא הנ\"ל בבחי' שינוי המהות להיות נק' אין להשגה בעונג מורגש בהשגה דבינה עד שכל שמשיג השכל בטוב טעם יותר [י]רגיש עונג כמו הנשמות שנהנין<sup data-n=\"9516\">694</sup> ומשיגי' בגעה\"ע כו'. וזהו ג\"כ ביו\"ד נברא העוה\"ב<sup data-n=\"9517\">695</sup> דאע\"פ שהעוה\"ב ה[ו]א בהשגה דבינה דוקא בעונג מורגש שישבעו ויתענגו מרב טוב העליון כו', אבל עונג זה נמשך מעונג הנעלם האין דחכ' כמו שהוא ג\"כ<sup data-n=\"9518\">696</sup> עצמו ואין בחי' הקרומא הנ\"ל מפסקת כלל, שזהו ג\"כ סיבת גילוי כל ההעלם דחכ'<sup data-n=\"9519\">697</sup> ברזין וסודות התו' במשיח דכתי' בי' ישכיל עבדי כו' ממקור [ד]ח\"ס ע\"ד דכל רז לא אניס לי'<sup data-n=\"9520\">698</sup> ונק' פלא יועץ חכם חרשים<sup data-n=\"9521\">699</sup> כו', וכך הי' בגילוי אור דח\"ע מפנימי' הכתר במ\"ת רק שהי' נמשך בגילוי בלבוש גשמי בנגלה שבתורה בעה\"ד טו\"ר ולע\"ל יהי' זה עצמו בפנימי' התו' שלזה [י]הי' הכנה דהעברה בנהר דבינה דוקא כמשי\"ת.\n(יט) <b>אך</b> באמת כמו שמבואר למעלה שיש ב' אופנים בקי\"ס הא' ש[מ]ההעלם עצמו דים נעשה גילוי ביבשה כמו הפך ים ליבשה כו', כך לע\"ל בחי' ים דחכ' <span data-k=\"pg\">568</span> ּ שנק' ים הקדמוני<sup data-n=\"9522\">700</sup> (דלא [כדלעיל דימא עילאה בבינה שהרי כל בחי' בקיעת הפרסא דקרומא הנ\"ל לע\"ל הכל הוא בבחי' אין דחכ' ולא ב]בינה שנק' יש) בחי' אין הנעלם <sup data-n=\"9523\">701</sup>דחכ' יהי' הוא עצמו [ב]בחי' גילוי בבינה שנק' יש ממש, והוא לפי שלא יתעלם בחי' החכ'<sup data-n=\"9524\">702</sup> שנק' אין כמו שהוא מיש לאין בדעת דכתר כנ\"ל בלבוש קרומא הנ\"ל ויהי' בחי' החשך העליון אור כמו ויהי הענן והחשך<sup data-n=\"9525\">703</sup> כו' ויאר את הלילה כו' שיש יתרון האור מן ההעלם דחכ' (כמעיינות תהום וכה\"ג). והב' הוא מה שיהי' אור העצמו' דא\"ס שבכתר בהתגלות בבינה שנק' יש שלא ע\"י בחי' אין דחכ' כלל<sup data-n=\"9526\">704</sup> אף לא בבחי' ח\"ס הנ\"ל שזהו שלא ע\"י ממוצע כלל שנק' מיש ליש כמו שהי' בקי\"ס שא' זה אלי ממש כו'. וכך יהי' לע\"ל בעוה\"ב שיהי' התגלות אור התענוג הפשוט שבעצמו' א\"ס (שנק' שעשוע המלך בעצמו כו') לנשמות בהשגה שלהם להיות בבחי' עונג המורגש בבחי' יש גמור, וכמ\"ש להנחיל אוהבי יש [י\"ש] האמיתי שלא ע\"י הממוצע דחכ' הנק' אין, והוא שלא כסדר ההשתל' דמיש לאין ומאין ליש כנ\"ל אלא מי\"ש לי\"ש כמו שהי' מעין זה בנשמת משה אע\"פ ששרשו בפנימי' דח\"ע וכן במשיח בבחי' פנימי' התורה, אבל לא יהי' גילוי זה ע\"י לבוש והעלם ואין דחכ' כלל וכמ\"ש לא למראה עיניו<sup data-n=\"9527\">705</sup> כו' בעין השכל הבא בהשגה דבינה אלא דמורח ודאין<sup data-n=\"9528\">706</sup> כמ\"ש והריחו ביראת ה'<sup data-n=\"9529\">707</sup> שהוא [בחי'] ריח דתענוג שבבינה שנק' נהרי אפרסמונא<sup data-n=\"9530\">708</sup> כו'",[["9515","693","<b>קוועלין</b>: הו: קוועל."],["9516","694","<b>הנשמות שנהנין</b>: ראה ברכות יז, א."],["9517","695","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב."],["9518","696","<b>ג\"כ</b>: ו: בכתר."],["9519","697","<b>דחכ'</b>: הו: דח\"ע."],["9520","698","<b>במשיח. . דכל רז לא אניס לי'</b>: נסמן לעיל קנו, ד."],["9521","699","<b>במשיח. . פלא יועץ חכם חרשים</b>: נסמן לעיל פ' שמות כג, א."],["9522","700","<b>דחכ' שנק' ים הקדמוני</b>: ראה גם מאמרי אדה\"א בראשית ריש ע' קכה. שע\"ת כג, ג ובהערה 29."],["9523","701","<b>דחכ'</b>: הו: דח\"ס."],["9524","702","<b>בחי' החכ'</b>: שם: הארת ח\"ס."],["9525","703","<b>והחשך</b>: שם: ליתא."],["9526","704","<b>כלל</b>: שם: ליתא."],["9527","705","<b>לא למראה עיניו</b>: ישעי' יא, ג [ושם: ולא — ראה שע\"ת יב, ב. מאמרי אדה\"א נ\"ך ס\"ע ר]."],["9528","706","<b>דמורח ודאין</b>: נסמן לעיל קנח, ג."],["9529","707","<b>והריחו ביראת ה'</b>: התחלת הכתוב לא למראה עיניו."],["9530","708","<b>נהרי אפרסמונא</b>: נסמן לעיל פ' שמות לד, ב."]]],[2300540912,"(וכמ\"ש בזהר ע\"פ ועבד הלוי הוא<sup data-n=\"9531\">709</sup> כו' דא הוא עתיקא ממש שיש שרש בבינה שנק' הוא<sup data-n=\"9532\">710</sup> בע\"י עצמו שלמעלה מנקודת החכ' ואין דחכ'<sup data-n=\"9533\">711</sup> והוא ענין ג' קוצין דיו\"ד<sup data-n=\"9534\">712</sup> שקוץ התחתון שבא בבינה שרשו בקוץ העליון בכתר כו', וזהו הבן בחכמה שלמעלה מחכ' עצמה כמ\"ש במ\"א). ולפ\"ז יוכל להתפשט<sup data-n=\"9535\">713</sup> בחי' הבקיעה בנהר דבינה לע\"ל שהוא בה\"א עילאה [שנק'] ימא ע\"י<sup data-n=\"9536\">714</sup> כנ\"ל ולא בחכ', כי אין ויש יש בבינה עצמה והוא מה פשפשת שנק' עומק המושג בהשגה לבד שזהו חכ' שבבינה ע\"ב דס\"ג בחי' אין ליש המושג בהסבר בחיצוני' השכל, ומ\"ש הבן בחכ' זהו שרש הבינה שלמעלה מן החכ' שהוא הכתר שנק' יש האמיתי, ובחי' הקוץ העליון הוא הארת [מיש ל]אין דחכ' וע\"כ יש כח בבינה שבכתר להביא נקודה דחכ' באין הנעלם לגילוי כו' (כנ\"ל בהמוצא משל לשכל ששרשו למעלה ממקור השכל והוא לבוש החשמ\"ל דבינה בשרשו למעלה שיוכל להיות כמו משל להעלים אור עומק השכל כו'). וזהו ועבד הלוי <sup data-n=\"9537\">715</sup>הוא בגבו' דבינה בפנימי' שזה<sup data-n=\"9538\">716</sup> שנק' הוא כמ\"ש ואי' מקום בינה<sup data-n=\"9539\">717</sup> כו' שעולה בע\"י עצמו שלמעלה מן הפרסא המפסיק בין כתר לחכ' [כו'], והוא הכח הבוקע הפרסא בין מלמעלה למטה (כמו הבן בחכ') ובין מלמטה למעלה ע\"י בחי' ההעלא' [ב]עומק ההשגה כמו ביגיעת המוח דבינה להשיג ואינו משיג לעומק שדוחק את הקרום ובוקע אותו מלמטה למעלה וחוזר ומאיר אור חדש מ[י]ש דכת\"ר לאין דחכ' כו' וד\"ל. ונמצא הבקיעה [ד]נהר לע\"ל זהו הכל בבחי' בינה דוקא ולא באי\"ן דחכ' שאינו דומה לקי\"ס שהי' במל' ה\"א תתאה כנ\"ל, וכתי' בנהר יעברו ברגל<sup data-n=\"9540\">718</sup> בבינה שנק' נהר כידוע, ויהי' בזה ב' אופנים בבקיעה מלמטה למעלה שזהו עלי' דבינה בע\"י <span data-k=\"pg\">רפד</span> ּ עצמו כעונג המורגש בהשגה שעולה בעצמו' התענוג הפשוט (שלא ע\"י בחי' אין דחכ' כלל כנ\"ל), והב' ירידה דאו\"י מלמעלה למטה בבקיעה דקרום הנ\"ל שזהו מאור עצמו' התענוג הפשוט שיתגלה בבינה דוקא להיות בבחי' עומק ויש<sup data-n=\"9541\">719</sup> מורגש דוקא שזהו מיש ליש כנ\"ל וד\"ל (וגם מה שיהי' גילוי סודות ורזין דאוריי' בימוהמ\"ש זה יהי' בהשגה דבינה דוקא כמ\"ש כולם ידעו אותי כנ\"ל וד\"ל).\n(ך) <b>וזהו</b> שא' כימי צאתך מאמ\"צ אראנו נפלאות לשון רבים כו', דהנה יצ\"מ וקרי\"ס שהפך ים ליבשה יהי' רק משל ודוגמא לע\"ל שיעברו בנהר ברגל שיהי' אז בחי' הגילוי ממדרגה גבוה ונעלה הרבה, והוא להיות שהבקיעה והעברה יהי' בנהר דבחי' בינה שיתגלה שם מאור העצמו' דא\"ס שלא ע\"י מסך שהוא בחי' הקרומא הנ\"ל, שזהו [ב'] בחי' אין דחכ' שנק' העלם (דים הקדמוני כנ\"ל) שיהי' הוא עצמו בבחי' גילוי ביבשה שהוא",[["9531","709","<b>ועבד הלוי הוא</b>: נסמן לעיל פ' שמות לד, א."],["9532","710","<b>בבינה שנק' הוא</b>: ראה ע\"ח (שער תקון הנוקבא) של\"ד, ספ\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a> ובהערה 7."],["9533","711","<b>ואין דחכ'</b>: הו: מאין דכתר."],["9534","712","<b>ג' קוצין דיו\"ד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670175\" data-slug=\"torat-chaim\" data-id=\"2300670175\">תו\"ח לך פב, ב</a> ובהערה 11. לעיל פ' שמות שם."],["9535","713","<b>להתפשט</b>: הו: להתפרש."],["9536","714","<b>ע\"י</b>: שם: עילאה."],["9537","715","<b>הוא</b>: שם: ליתא."],["9538","716","<b>שזה</b>: שם: שלה."],["9539","717","<b>ואי' מקום בינה</b>: איוב כח, יב [ושם: ואי זה — ראה מאמרי אדה\"א דברים ח\"ד ע' א'רי. וש\"נ]."],["9540","718","<b>ברגל</b>: הו: ליתא."],["9541","719","<b>עומק ויש</b>: שם: עונג ביש."]]],[2300540919,"המסילה שיעברו ברגל בנהר דוקא, ויש בזה ב' אופנים באו\"ח ואו\"י כנ\"ל, וז\"ש ונהרותם כשמן אוליך<sup data-n=\"9542\">720</sup> כו', ויותר משמן דחכ' תעלה בינה בכתר עצמו או [ש]הכתר בחי' ע\"י עצמו יתגלה בבינה כנ\"ל, והוא לפי שלע\"ל יהי' הכנה זו דהעברה בנהר לענין מ\"ת [ד]פנימי' התו' כמו שהי' במ\"ת בנגלה הי' קי\"ס במל' הכנה לזה כנ\"ל, והוא גילוי סודות התו' טעמי מצות מהעלם דח\"ס בימוהמ\"ש עד [ש]כולם ידעו אותי [ממש כו',] ובשביל <sup data-n=\"9543\">721</sup>זה גילוי אור גדול כזה הוצרך להיות בחי' הבקיעה במקום גבוה יותר והוא בבחי' אין דחכ' שמתעלם בלבוש דקרו[מא] שנק' פרוכת שבין הקדש לקה\"ק כו' שלא יסתיר כלל וממילא יתגלה כל תעלומו' דח\"ע (אפי' סוד סתום לגמרי). ואע\"פ שגם עכשיו מאיר אור הכתר בחכ' ומחכ' לבינה מאין ליש, זהו ע\"פ צמצום והסתר בבחי' פרסא זו דקרומא עד שגם בהשגה דמוח בינה יתעלם עוד נקודת החכ' שנק' אין ולא יבוא בהשגה כ\"א חיצוני' שלו לבד מה שיוכל להבין ולהשיג, אבל פנימי' שבו מוסתר ונעלם ונק' נקודה בהיכלא<sup data-n=\"9544\">722</sup>, או כמו מזל ונוצר [ש]הוא מקור לגילוי החכ' מאין שהוא בלבוש וצמצום דשערה בצנור וכמ\"כ בנקודה דיו\"ד כו' (וכך הוא ברצון אותיות ונוצר<sup data-n=\"9545\">723</sup> שלמעלה [גם] מחכ' וטעם כמוס לרצון שמתעלם בקרומא הנ\"ל כנ\"ל). אבל לע\"ל יתגלה הכל מן ההעלם ע\"כ יהי' גילוי אלקו' גם בכל הברואים כמ\"ש ונגלה כבוד הוי' וראו כל בשר וידע כל פעול<sup data-n=\"9546\">724</sup> כי אתה פעלתו וכ[נ\"ל ב]חמורו של רפב\"י וכפרות שנשאו את הארון וכה\"ג וכמו וייראוך כל המעשים<sup data-n=\"9547\">725</sup> כו' וכידוע.\n<b>וזהו</b> שא' אראנו נפלאות לשון רבים ב' מיני נפלאות שהם ב' מדרגות זו למעלה מזו, הא' בימוהמ\"ש שיתגלה בחי' ההעלם דחכ' שבכתר [ש]נק' שכל מופלא הנעלם מכל רעיון שלא יתעלם במסך ופרסא הנ\"ל וזהו בחי' פלאות דח\"ס<sup data-n=\"9548\">726</sup> וזהו אהי' אשר אהי'<sup data-n=\"9549\">727</sup> שאנא זמין לאולדא או לאתגלא במשיח ודורו, וידוע דשם אהי' בכתר<sup data-n=\"9550\">728</sup> זהו בחכ' שבכתר עצמו שנק' אור צח ומצוחצח כמו והשביע בצחצחות נפשך<sup data-n=\"9551\">729</sup> בעונג הנעלם דח\"ס שבא במורגש בשביע' בנפש כמ\"ש והשביע בצחצחות כמו מתיקות התורה שנתגלה לר\"ע ורשב\"י וכה\"ג. ואהי' הב' הוא למעלה גם מזה והוא בחי' התגלות <span data-k=\"pg\">570</span> ּ דאור הכתר <sup data-n=\"9552\">730</sup>והוא בחי' ע\"י עצמו בחי' התענוג הפשוט שלמעלה גם מבחי' ח\"ס הנ\"ל, שיתגלה בעוה\"ב לנשמות בעונג מורגש בהשגה דבינה כנ\"ל שזהו מיש ליש כנ\"ל, והוא בב' אופנים באו\"ח ואו\"י כנ\"ל. וזהו אשר אהי' עוד פעם ב' שזהו למעלה מבחי' הבירורים דתו\"מ בעה\"ד טו\"ר אלא רק שכר המצות בעוה\"ב כידוע, וע\"כ יהי' גילוי אור זה מן העצמות דא\"ס בתענוג הפשוט העצמי שלא ע\"י",[["9542","720","<b>ונהרותם כשמן אוליך</b>: יחזקאל לב, יד."],["9543","721","<b>זה</b>: הו: ליתא."],["9544","722","<b>נקודה בהיכלא</b>: ראה גם לעיל פ' בא קכח, ב. וש\"נ."],["9545","723","<b>ברצון אותיות ונוצר</b>: נסמן לעיל פ' שמות כו, ד."],["9546","724","<b>וידע כל פעול</b>: תפלת העמידה לר\"ה."],["9547","725","<b>וייראוך כל המעשים</b>: תפלת העמידה לימים נוראים."],["9548","726","<b>פלאות דח\"ס</b>: ראה גם הנסמן לעיל פ' שמות כא, ב."],["9549","727","<b>אשר אהי'</b>: הו: הא'."],["9550","728","<b>דשם אהי' בכתר</b>: נסמן לעיל פ' בא קיב, א."],["9551","729","<b>והשביע בצחצחות נפשך</b>: ישעי' נח, יא."],["9552","730","<b>והוא</b>: הו: ליתא."]]],[2300540926,"בחי' ממוצע דחכ' מאין ליש כו', ולא ע\"י לבוש ומסך דפרסא הנ\"ל שמפסיק בין קדש דחכ' לקה\"ק <sup data-n=\"9553\">731</sup>כנ\"ל לפי שלא יתלבש בדבר להסתיר אור העצמו' כמ\"ש הנה אלקינו זה<sup data-n=\"9554\">732</sup> לנוכח כו'. וזהו [ענין] עד יעבור סתם שאינו נזכר שם הוי', [כי] העברה הא' עד יעבור עמך ה' שזהו בעלי' הא' דימוהמ\"ש שיעברם בנחל מצרים שהכה לנהר זה לז' נחלים והדריך בנעלים דוקא, שזהו בחי' בירור דזמ\"ל דתהו שנפלו בשבירה ואין זה הבירור שלהם אלא בחכ' דתו' ומצות דבחכ' אתברירו<sup data-n=\"9555\">733</sup> דוקא כידוע דמ\"ה דוקא מברר לב\"ן<sup data-n=\"9556\">734</sup> כו', וזהו ע\"י גילוי פנימי' דח\"ע דתורה בימוהמ\"ש שהוא בחי' שלימות הבירורי' דרפ\"ח הנ\"ל [ו]עי\"ז יהופך חשך העליון לאור שלא יסתיר בחי' פרסא הנ\"ל ומביא כל ההעלם לגילוי בהשגה כנ\"ל (וזהו והדריך בנעלים<sup data-n=\"9557\">735</sup> אחר הכאה לז' נחלים כו' שהוא בירור [ד]חשמ\"ל דנוגה בשלימות עד שיהי' ממנו נעלים [דווקא כמו] שמט\"ט<sup data-n=\"9558\">736</sup> הי' תופר מנעלים<sup data-n=\"9559\">737</sup> לשכינה [כו'], כמו כתנות אור באל\"ף אחר הבירור [ו]כמו מה יפו פעמיך<sup data-n=\"9560\">738</sup> בנעלים בת נדיב כו' (כמ\"ש במ\"א), והוא בירור המשל לנמשל שיבא ממנו יתרון אור הרבה יותר מן העומק הנמשל כו'). אמנם העברה הב' הוא בנהר פרת שיעברו בו לעדן העצמי<sup data-n=\"9561\">739</sup> שהוא העוה\"ב ממש שנק' תענוג הפשוט שבעצמו' ממש כנ\"ל אז הוא למעלה מבירורים דתומ\"צ ע\"י שם הוי' ולכך א' עד יעבור סתם עד יעבור עם זו קנית בקנין עצמו כמאמר ישראל קנין א'<sup data-n=\"9562\">740</sup> כו'.\n<b>ונמצא</b> שיש כאן ג' מדרגות בכלל והכל בחי' בקיעה בפרסא לע\"ל לבד קי\"ס שהי' בבחי' המל', [א'] בנהר יעברו ברגל <sup data-n=\"9563\">741</sup>בנהר [ב]חיצוני' דבינה שנק' נחל מצרים, ולצאת ממצרים פעם ב' בימוהמ\"ש זהו ע\"י בירור זמ\"ל דתהו כנ\"ל והוא בשביל קבלת התו' בפנימי' דח\"ע כנ\"ל וזהו הנק' ג\"כ יצ\"מ, ולא בבחי' המל' לבד שנק' שכינה תתאה<sup data-n=\"9564\">742</sup> שהי' בגלות מצרים ויצאו ממיצר בבחי' עיבור ולידה באימא תתאה כו', אלא יהי' במדרגה גבוה יותר והוא בעיבור ולידה דמדות שנק' [ישראל מ]מיצר מ\"י דבינה ה\"א עילאה והוא שהכהו לז' נחלים לנחל מצרים ויעברו בו ברגל בשלימות הבירורים דמדות ויזכו לפנימי' התורה כנ\"ל. ועוד יהי' עלי' גדולה מזו ג\"כ והוא יציאת (יש\"ס בחי' מדות דחכ' כמשי\"ת) במצרים<sup data-n=\"9565\">743</sup> דח\"ע בפנימי' ג\"כ והוא עליות דבינה בע\"י עצמו לקבל מבחי' יש האמיתי דעצמו' [התענוג] ורצון כו' כנ\"ל, וזהו העברה הב' בעיבור ולידה דכת\"ר עצמו שז\"ש אשר אהי' אנא זמין כו' למעלה גם מבחי' לידה דמשיח ממיצר מי הים",[["9553","731","<b>כנ\"ל</b>: ה: ודכ' ( ). ו: דכתר."],["9554","732","<b>זה</b>: הו: ליתא."],["9555","733","<b>דבחכ' אתברירו</b>: נסמן לעיל פ' שמות י, ג."],["9556","734","<b>דמ\"ה. . מברר לב\"ן</b>: נסמן לעיל ד, ב."],["9557","735","<b>והדריך בנעלים</b>: ראה גם לעיל קנח, ב."],["9558","736","<b>שמט\"ט</b>: הו: חנוך."],["9559","737","<b>חנוך הי' תופר מנעלים</b>: נסמן לעיל קנח, ב."],["9560","738","<b>מה יפו פעמיך</b>: שה\"ש ז, ב. ראה גם מאמרי אדה\"א נ\"ך ס\"ע רצז ואילך. ס\"ע שיח ואילך. ע' שמב."],["9561","739","<b>העצמי</b>: העליון עצמו."],["9562","740","<b>ישראל קנין א'</b>: אבות פ\"ו, י."],["9563","741","<b>בנהר</b>: הו: ליתא."],["9564","742","<b>המל'. . שכינה תתאה</b>: נסמן לעיל פ' וארא נד, ב."],["9565","743","<b>במצרים</b>: הו: ממיצר ים."]]],[2300540933,"דחכ'<sup data-n=\"9566\">744</sup> כו' וד\"ל. ועלי' הג' גם למעלה מזו דאור הכתר והוא בעוה\"ב עצמו שנק' עדן שיעלו לפנימי' ועצמו' א\"ס שלמעלה גם מבחי' הכתר שהוא למעלה גם מקבלת השכר בעונג המורגש לנשמות שז\"ש עם זו קנית (כמשי\"ת). והנה באמת יש ג' מדרגות לבד זה העלי' <span data-k=\"pg\">רפה</span> ּ למעלה בעוה\"ב, והוא בבחי' הפרסא שנק' מיצר מי דגרון שהוא בחי' יציאת המדות מצמצום המוחין דבינה כשבאין בהתגלות בלב שנק' לידה, וכן מלמטה למעלה בחי' עליית המדות שבלב שעול[י'] למעלה בבחי' בינה ע\"י בקיעה דפרסא זאת שנק' מיצר הגרון שזה יהי' לע\"ל כמ\"ש בנהר יעברו ברגל, שזהו עליית המדות דז\"א בבינה שנק' נהר וכך יהי' עליות רבות עד רום המעלות כו' וד\"ל. ולהבין זה, וגם י\"ל דלפי זה מה הי' ענין קי\"ס שא' בצאת ישראל ממצרים<sup data-n=\"9567\">745</sup> ממיצר מ\"י<sup data-n=\"9568\">746</sup> דבינה כמ\"ש בס' הקבלה, ולפי הנ\"ל יהי' זה לע\"ל שבנהר יעברו ברגל כנ\"ל. אך [הנה] זהו שא' כימי צאתך מאמ\"צ אראנו נפלאות לשון רבים, ופי' אראנו היינו כמו שפי' בזהר דאראנו זה קאי על ישראל דוקא שהוא מ\"ש וירא ישראל את היד הגדולה כו', וא' שאראנו לישראל זה עצמו כשיהי' לע\"ל בבחי' הגדלות דזקנה ויהי' נק' יש\"ס אראנו נפלאות גדולות ורבות יותר כו', שזהו בכלל בחי' עליות המדות דז\"א שנק' ישראל<sup data-n=\"9569\">747</sup> למעלה עד בחי' הכתר עצמו שנק' פלא<sup data-n=\"9570\">748</sup> ולמעלה מעלה בעליות רבות שנק' אדו\"ן הנפלאות<sup data-n=\"9571\">749</sup> דכמ\"כ יהיו עליות רבות בכל פרטי התחלקו' הפרצופי' גם בע\"י וא\"א עד בחי' מל' דא\"ס עצמו כנ\"ל וד\"ל.\n<b>וביאור</b> כ\"ז, הנה י\"ל תחלה במ\"ש בצאת ישראל ממצרים כו' דבחי' ישראל זה יש ג' מדריגות והיינו ג' בחי' אדם כו' כידוע שזהו ג' מדרגות דבי\"ע באצי' עצמו בחי' אדם דעשי' כמו אף עשיתיו, ובחי' אדם דיצי' כמ\"ש יצרתיו ובחי' אדם דבריאה כמ\"ש בראתיו<sup data-n=\"9572\">750</sup> כו', וכל בחי' אדם כו' זהו בחי' המדות שנחלקו לג' קוין<sup data-n=\"9573\">751</sup> ימין ושמאל ואמצע בחי' חג\"ת שהן ג' קוין דאצי' בכלל והיינו ג' מדרגות דישראל למעלה [מעלה]. הא' בחי' ישראל סתם שהוא בחי' כנס\"י למטה ושרשם למעלה הוא בחי' מל' דאצי' שנק' אימא<sup data-n=\"9574\">753</sup> תתאה, והוא בחי' מדות שבדבור ומח' שבאין בגילוי מאין ליש ממש בעולמות דבי\"ע שנק' אדם דעשי'. והב' בחי' ישראל שבבחי' יצי' דאצי' שהוא בחי' ז\"א דכתי' [בי'] וייצר ה' את האדם<sup data-n=\"9575\">754</sup> כו' והוא בחי' מדות דז\"א דאצי' כמו שהן נולדים ונמשכי' מבחי' בינה או<sup data-n=\"9576\">755</sup> אימא עילאה קודם שבא בגילוי אותיות דו\"מ כו', וזהו שנק' בזהר בחי' ישראל זוטא למטה מן החכ'<sup data-n=\"9577\">756</sup> כו', והוא אדם דיצי' סתם שמאיר לאדם דעשי' בחי'",[["9566","744","<b>מי הים דחכ'</b>: שם: ים החכ'."],["9567","745","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א."],["9568","746","<b>ממצרים ממיצר מ\"י</b>: נסמן לעיל פ' שמות לז, ב."],["9569","747","<b>דז\"א שנק' ישראל</b>: ראה ע\"ח (שער הקליפות) שמ\"ח פ\"ג. מאמרי אדה\"א דברים ח\"ב ע' שצב. וש\"נ. שעה\"י קלג, א."],["9570","748","<b>הכתר. . פלא</b>: ראה תיקונים לז\"ח צח, ד."],["9571","749","<b>אדו\"ן הנפלאות</b>: ראה מאמרי אדה\"א שמות ח\"א ע' קכב ואילך."],["9572","750","<b>אף עשיתיו. . יצרתיו. . בראתיו</b>: ישעי' מג, ז."],["9573","751","<b>קוין</b>: הו: ליתא."],["9574","753","<b>אימא</b>: הו: אדם."],["9575","754","<b>וייצר ה' את האדם</b>: בראשית ב, ז [ושם: ה\"א]."],["9576","755","<b>או</b>: הו: ליתא."],["9577","756","<b>החכ'</b>: שם: הכו\"ח."]]],[2300540940,"המל' כמ\"ש כמים הפא\"פ כן לב האדם אל האדם<sup data-n=\"9578\">757</sup> וזהו על הכסא<sup data-n=\"9579\">758</sup> כו' כידוע. ובחי' ומדרגה הג' דישראל הוא שנק' ישראל סבא והוא בחי' אדם דבריאה [ד]אצי' בכלל, וזהו בחי' המדות דח\"ס שהמדות הן בבחי' הגדלות דחכ' כמו שהוא בבחי' אין הנעלם שבכת\"ר עצמו שהוא בבחי' זקנ' כזקן שקנה חכ'<sup data-n=\"9580\">759</sup> ממקורו בהעלם החכ' שגם מדותיו הן בבחי' הגדלות [ד]ח\"ע וכנ\"ל, כמ\"ש לפי שכלו דוקא יהולל איש<sup data-n=\"9581\">760</sup> שהן המדות וכתי' כי האדם עץ השדה<sup data-n=\"9582\">761</sup> כו' שגדלות המדות הוא לפי עצם<sup data-n=\"9583\">762</sup> גדלות השכל, ומקור גדלות [השכל] הוא בח\"ס דא\"א וע\"י כו' שלמעלה [מגילוי] אור הח\"ס<sup data-n=\"9584\">763</sup> מאין ליש בבינה שנק' המדות [ו\"ק] דאבא<sup data-n=\"9585\">764</sup> או ז\"ת דאימא<sup data-n=\"9586\">765</sup> כו' [ש]זהו בחי' ישראל זוטא שכולה מיחוד דאור אבא<sup data-n=\"9587\">766</sup> דאצי' כידוע, וזהו רמז [ש]דבור שלמה מן הארז אשר בלבנון תכלית גדלות המדות בלבנון בתענוג דח\"ס עד אזוב<sup data-n=\"9588\">767</sup> כו' <span data-k=\"pg\">572</span> ּ קטנות המדות [ש]במל' שנק' קיר<sup data-n=\"9589\">768</sup> בהתלבשות ש[ל]ה בבי\"ע כו'.\n(ךא) <b>והנה</b> להבין ביאור ענין ההפרש בין ב' מדרגות דיש\"ז ויש\"ס הנ\"ל (לבד בחי' המדות שבלב שמאירים באותיות הדבור שנק' אדם תתאה<sup data-n=\"9590\">752</sup> בחי' המל' כו'<sup data-n=\"9591\">784</sup> ) הנה מבשרי אחזה כו' שאנו רואים ששרש מהות המדות אינו רק בחי' רצון לבד, כמו מדת אהבה בלב מפני שהוא חפץ ורוצה בדבר מה שהוא האהבה שאוהב [כל דבר] כי אהבה הוא לשון אבה<sup data-n=\"9592\">769</sup> הוא הרצון רק בגילוי הרצון בהבל הלב נק' אהבה בה\"א כו'<sup data-n=\"9593\">770</sup>, וכן במדת השנאה בלב הוא מה שנסתלק<sup data-n=\"9594\">771</sup> רצונו מאד ישנה אותה וכן במדת הנצחו[ן] והת\"ת<sup data-n=\"9595\">772</sup> כו' הכל הוא רק בחי' רצון לבד. וראי' ממה שהרצון שולט במדות שבלב להפוך מאהבה לשנאה ומחסד לדין וחוב או להפך וכידוע. והנה זה הרצון הוא שנק' רעו\"ד<sup data-n=\"9596\">773</sup> דוקא ונק' רצון התחתון והוא בחי' מדות שבאין בלב שנולדי' מן השכל או השגה במוח בינה דוקא כמ\"ש בזהר אית רצון<sup data-n=\"9597\">774</sup> ואית רצון כו', ושורש הרצון שבמדות באין הן מבחי' הכתר שלמעלה מהשכל והטעם לגמרי [ו]כמ\"ש בזהר דז\"א בע\"י עצמו אחיד ותליא<sup data-n=\"9598\">775</sup> (כמשי\"ת). אך אית רצון שנק' רצון המורכב ונק' רצון הנולד שנולד לפי שעה והוא נק' רצון התחתון שלמטה מן הדעת, והיינו כמו שרואין בחוש שבלתי העמקת השכל והדעת לאיזה דבר מה לא יוליד רצון [ו]התפעלות המדות אליו כלל, רק כשמעמיק דעתו ומחשבתו",[["9578","757","<b>כמים הפא\"פ </b>[הו: כו']<b>. . אל האדם [הו</b>: לאדם]: משלי כז, יט. וראה הנסמן לעיל פ' בא קב, ב."],["9579","758","<b>על הכסא</b>: נסמן לעיל כח, ג — ראה מאמרי אדה\"ז תקע\"א ע' מד."],["9580","759","<b>כזקן שקנה חכ'</b>: נסמן לעיל פ' שמות לא, ד."],["9581","760","<b>לפי שכלו. . יהולל איש</b>: משלי יב, ח. ראה גם לקמן רמא, א."],["9582","761","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["9583","762","<b>לפי עצם</b>: הו: לפ\"ע."],["9584","763","<b>הח\"ס</b>: הו: החכ'."],["9585","764","<b>[ו\"ק] דאבא</b>: נסמן לעיל יא, א. ראה להלן פכ\"א."],["9586","765","<b>ז\"ת דאימא </b>[הו: דבינה]: ראה גם שעה\"י קי, ב ובהערה 13. ראה לקמן שם וספכ\"ז."],["9587","766","<b>שכולה. . אבא</b>: הו: שנולד מיחוד דאו\"א."],["9588","767","<b>מן הארז אשר בלבנון. . עד אזוב</b>: מלכים-א ה, יג. ראה גם שעה\"י קלד, ב."],["9589","768","<b>[ש]במל' שנק' קיר</b>: ראה זהר ויחי רכח, ב. תרומה קלג, א. מאו\"א מערכת קיר (אות כג)."],["9590","752","<b>מל'. . שנק' אדם תתאה</b>: ראה פרדס (שער ערכי הכינויים) שכ\"ג, מערכת אדם. לקמן פ' משפטים רצא, ד. ויקהל תכא, ב. תכט, א. שע\"ת טו, ד. צב, ג. ש\"א לא, ב."],["9591","784","<b>כו'</b>: שם: עילאה."],["9592","769","<b>אהבה הוא לשון אבה</b>: ראה שרש ישע שרש אבה הובא בס' חקירה להצ\"צ מערכת אהב (צב, רע\"א). לקמן פ' ויקהל תלד, ג. פקודי תנב, א. מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ."],["9593","770","<b>כו'</b>: הו: כידוע."],["9594","771","<b>שנסתלק</b>: שם: שהיפוך."],["9595","772","<b>והת\"ת</b>: שם: והתפארות."],["9596","773","<b>רעו\"ד</b>: זהר וירא ק, א."],["9597","774","<b>כמ\"ש בזהר אית רצון</b>: כ\"ה בכ\"מ — ראה זהר (אד\"ר) נשא קכט, א: מצחא דאקרי רצון כו'. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרמז. לקמן פ' תצוה שסא, א. ויקהל תלד, ב."],["9598","775","<b>דז\"א בע\"י. . אחיד ותליא</b>: נסמן לעיל פ' בא קל, ב."]]]]});
